import React, { useRef, useCallback } from 'react';
import Skeleton from 'react-loading-skeleton';
import 'react-loading-skeleton/dist/skeleton.css';
import { Badge } from '../../components/Badge/Badge';
import { Pagination } from '../../components/Pagination/Pagination';
import { AuditTimestamp } from './AuditTimestamp';
import type { AuditTimelineProps } from './AuditTimeline.types';
import type { AuditHistoryItem } from '../types/audit.types';

const MAX_FIELDS_PREVIEW = 3;

const ACTION_CONFIG: Record<AuditHistoryItem['action'], { color: 'green' | 'amber' | 'red'; label: string }> = {
  Created: { color: 'green', label: 'Creado' },
  Modified: { color: 'amber', label: 'Actualizado' },
  Deleted: { color: 'red', label: 'Eliminado' },
};

function groupByDate(entries: AuditHistoryItem[]): Array<{ dateLabel: string; entries: AuditHistoryItem[] }> {
  const groups = new Map<string, AuditHistoryItem[]>();
  for (const entry of entries) {
    const date = new Date(entry.timestamp);
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(today.getDate() - 1);

    let label: string;
    if (date.toDateString() === today.toDateString()) {
      label = 'Hoy';
    } else if (date.toDateString() === yesterday.toDateString()) {
      label = 'Ayer';
    } else {
      label = date.toLocaleDateString('es', { day: '2-digit', month: '2-digit', year: 'numeric' });
    }

    if (!groups.has(label)) groups.set(label, []);
    groups.get(label)!.push(entry);
  }
  return Array.from(groups.entries()).map(([dateLabel, entries]) => ({ dateLabel, entries }));
}

const SkeletonCard: React.FC = () => (
  <div className="px-4 py-3 border-b border-slate-100 dark:border-slate-800">
    <div className="flex items-center gap-2 mb-2">
      <Skeleton width={64} height={20} borderRadius={4} />
      <Skeleton width={100} height={14} />
    </div>
    <Skeleton width={80} height={12} className="mb-1" />
    <Skeleton width={140} height={12} />
  </div>
);

interface TimelineCardProps {
  entry: AuditHistoryItem;
  selected: boolean;
  onSelect: (id: string) => void;
}

const TimelineCard: React.FC<TimelineCardProps> = ({ entry, selected, onSelect }) => {
  const { color, label } = ACTION_CONFIG[entry.action];
  const previewFields = entry.changedFields.slice(0, MAX_FIELDS_PREVIEW);
  const extraCount = entry.changedFields.length - MAX_FIELDS_PREVIEW;

  const cardClasses = [
    'px-4 py-3 cursor-pointer border-b border-slate-100 dark:border-slate-800',
    'focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500',
    'transition-colors duration-100',
    selected
      ? 'bg-blue-50 dark:bg-blue-950/40 border-l-2 border-l-blue-500'
      : 'hover:bg-slate-50 dark:hover:bg-slate-800/60',
  ]
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onSelect(entry.id);
    }
  };

  return (
    <div
      role="listitem"
      aria-selected={selected}
      tabIndex={0}
      className={cardClasses}
      onClick={() => onSelect(entry.id)}
      onKeyDown={handleKeyDown}
    >
      <div className="flex items-center gap-2 mb-1">
        <Badge color={color} label={label} aria-label={`Acción: ${label}`} />
        <span className="text-sm font-medium text-slate-800 dark:text-slate-200 truncate">
          {entry.actorFullName}
        </span>
      </div>
      <AuditTimestamp timestamp={entry.timestamp} className="block mb-1" />
      {previewFields.length > 0 && (
        <p className="text-xs text-slate-500 dark:text-slate-400 truncate">
          {previewFields.join(', ')}
          {extraCount > 0 && (
            <span className="text-slate-400 dark:text-slate-500"> +{extraCount} más</span>
          )}
        </p>
      )}
    </div>
  );
};

/**
 * Panel izquierdo del split view: lista cronológica de entradas de auditoría
 * con separadores de fecha, skeleton de carga y paginación.
 */
export const AuditTimeline: React.FC<AuditTimelineProps> = ({
  entries,
  selectedId,
  onSelect,
  isLoading = false,
  totalCount,
  page,
  pageSize,
  onPageChange,
  className = '',
}) => {
  const listRef = useRef<HTMLDivElement>(null);
  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));

  const containerClasses = ['flex flex-col h-full', className]
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (!entries.length) return;
      const currentIndex = entries.findIndex((en) => en.id === selectedId);
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        const next = entries[Math.min(currentIndex + 1, entries.length - 1)];
        if (next) onSelect(next.id);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        const prev = entries[Math.max(currentIndex - 1, 0)];
        if (prev) onSelect(prev.id);
      }
    },
    [entries, selectedId, onSelect]
  );

  return (
    <div className={containerClasses}>
      {/* Lista */}
      <div
        ref={listRef}
        role="list"
        aria-label="Historial de cambios"
        className="flex-1 overflow-y-auto"
        onKeyDown={handleKeyDown}
      >
        {isLoading ? (
          Array.from({ length: 5 }).map((_, i) => <SkeletonCard key={i} />)
        ) : entries.length === 0 ? (
          <div
            role="status"
            aria-live="polite"
            className="flex items-center justify-center h-32 text-sm text-slate-400 dark:text-slate-600 px-4 text-center"
          >
            No hay registros de auditoría para este elemento
          </div>
        ) : (
          groupByDate(entries).map(({ dateLabel, entries: group }) => (
            <React.Fragment key={dateLabel}>
              {/* Date separator */}
              <div className="flex items-center gap-2 px-4 py-2 sticky top-0 bg-white dark:bg-slate-950 z-10 border-b border-slate-100 dark:border-slate-800">
                <span className="text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wide">
                  {dateLabel}
                </span>
                <div className="flex-1 h-px bg-slate-200 dark:bg-slate-700" />
              </div>
              {group.map((entry) => (
                <TimelineCard
                  key={entry.id}
                  entry={entry}
                  selected={entry.id === selectedId}
                  onSelect={onSelect}
                />
              ))}
            </React.Fragment>
          ))
        )}
      </div>

      {/* Pagination */}
      {!isLoading && totalPages > 1 && (
        <div className="flex-shrink-0 border-t border-slate-200 dark:border-slate-700 px-2 py-2">
          <Pagination
            currentPage={page}
            totalPages={totalPages}
            onPageChange={onPageChange}
            siblingCount={0}
            ariaLabel="Navegación de páginas del historial"
          />
        </div>
      )}
    </div>
  );
};

AuditTimeline.displayName = 'AuditTimeline';
