import React, { createContext, useContext } from 'react';
import type { DashboardFetcher } from './types';

interface DashboardContextValue {
  fetcher: DashboardFetcher;
}

const DashboardContext = createContext<DashboardContextValue | null>(null);

export const DashboardProvider: React.FC<{
  fetcher: DashboardFetcher;
  children: React.ReactNode;
}> = ({ fetcher, children }) => (
  <DashboardContext.Provider value={{ fetcher }}>
    {children}
  </DashboardContext.Provider>
);

/**
 * Expone el fetcher inyectado por el host.
 * Lanza error si se usa fuera de DashboardProvider.
 */
export const useDashboardContext = (): DashboardContextValue => {
  const ctx = useContext(DashboardContext);
  if (!ctx) {
    throw new Error('useDashboardContext debe usarse dentro de <DashboardProvider>. Asegurate de pasar un fetcher a <DashboardPage>.');
  }
  return ctx;
};
