import type { TranslationEngine, TranslationResources } from '../types';

/**
 * Motor de traducción predeterminado
 * Permite manejar múltiples recursos cargados en memoria y realizar fallbacks
 */
export class DefaultTranslationEngine implements TranslationEngine {
  private resources: { [lang: string]: TranslationResources } = {};
  private currentLanguage: string = 'es';
  private defaultLanguage: string = 'es';

  constructor(defaultLang: string = 'es') {
    this.defaultLanguage = defaultLang;
    this.currentLanguage = defaultLang;
  }

  /**
   * Traduce una llave. Busca en el idioma actual y hace fallback al default si falla.
   * @param key Llave del mensaje (ej: 'saludo.bienvenida')
   */
  translate(key: string): string {
    // 1. Intentar en idioma actual
    const currentResources = this.resources[this.currentLanguage];
    if (currentResources && currentResources[key]) {
      return currentResources[key];
    }

    // 2. Intentar en idioma default (fallback)
    const defaultResources = this.resources[this.defaultLanguage];
    if (
      this.currentLanguage !== this.defaultLanguage &&
      defaultResources &&
      defaultResources[key]
    ) {
      return defaultResources[key];
    }

    // 3. Devolver la llave si no existe en ninguna parte para no romper la UI
    return key;
  }

  /**
   * Registra recursos en el motor
   */
  loadResources(lang: string, resources: TranslationResources): void {
    // Mergeamos si ya existen recursos para ese idioma
    this.resources[lang] = {
      ...(this.resources[lang] || {}),
      ...resources,
    };
  }

  /**
   * Cambia el idioma activo en el motor
   */
  changeLanguage(lang: string): void {
    this.currentLanguage = lang;
  }

  /**
   * Obtiene el código del idioma activo
   */
  getCurrentLanguage(): string {
    return this.currentLanguage;
  }
}
