/** Diccionarios de respaldo por idioma, listos para registrar en el host si se desea. */
export const SERIAL_PANEL_TRANSLATIONS = {
  es: SERIAL_PANEL_TRANSLATIONS_ES,
  en: SERIAL_PANEL_TRANSLATIONS_EN,
} as const;

/** Función de traducción con interpolación `{var}`. */
export type SerialPanelT = (key: string, vars?: Record<string, string | number>) => string;

/**
 * Hook de traducción del SerialPanel. Usa `useTranslation` del kit; si la clave
 * no está registrada en el host, cae al diccionario local en español.
 */
export function useSerialPanelTranslation(): { t: SerialPanelT } {
  const { t: baseT } = useTranslation();

  const t = useMemo<SerialPanelT>(
    () => (key, vars) => {
      let value = baseT(key);
      if (value === key) {
        value = SERIAL_PANEL_TRANSLATIONS_ES[key] ?? key;
      }
      if (vars) {
        for (const [name, replacement] of Object.entries(vars)) {
          value = value.replace(`{${name}}`, String(replacement));
        }
      }
      return value;
    },
    [baseT],
  );

  return { t };
}
