/**
 * TabBar — tab navigation for the form panel.
 *
 * "Datos básicos" with a red "*" is always the first tab (key: 'basicData').
 * Additional tabs come from `definition.tabs`.
 * Error count badges are shown per tab from `errors` mapped to tab keys.
 * When navigationType='modal' + more than 1 content tab, logs console.warn and truncates.
 *
 * @module components/form/TabBar
 * @see FMPV-MVWC-E003-S001 I-004
 */
import React, { useMemo } from 'react';
import type { MasterPatternViewDefinition } from '../../types/definition.types';
import { getAllFields } from '../../engine/fieldEngine';
import type { MasterDetailTabConfig } from '../../types/detail.types';
import type { MasterPatternViewEntity } from '../../types/service.types';

export interface TabBarProps {
  definition: MasterPatternViewDefinition;
  activeTabKey: string;
  errors: Record<string, string>;
  onTabChange: (key: string) => void;
  navigationType?: 'sidebar' | 'modal' | 'page';
  /** Form mode — detail tabs only shown in 'editing' mode */
  formMode?: 'creating' | 'editing' | 'viewing' | 'closed';
  /** Structured detail tab configurations (only visible in editing mode) */
  detailTabConfigs?: MasterDetailTabConfig<MasterPatternViewEntity>[];
}

interface ResolvedTab {
  id: string;
  label: string;
  badge?: number;
}

/** Resolve the tab key for a field: uses formTab if set, otherwise 'basicData'. */
function getFieldTabKey(fieldName: string, formTab?: string): string {
  return formTab ?? 'basicData';
}

export function TabBar({
  definition,
  activeTabKey,
  errors,
  onTabChange,
  navigationType,
  formMode,
  detailTabConfigs,
}: TabBarProps) {
  const items = useMemo((): ResolvedTab[] => {
    const contentTabs = definition.tabs ?? [];
    const isModal = navigationType === 'modal';
    const showDetailTabs = (formMode === 'creating' || formMode === 'editing' || formMode === 'viewing') && (detailTabConfigs?.length ?? 0) > 0;

    let visibleContentTabs = contentTabs;
    if (isModal && contentTabs.length > 1) {
      console.warn(
        '[MasterPatternView] navigationType="modal" with more than 1 content tab is not supported. ' +
          'Only "Datos básicos *" and the first content tab will be shown.'
      );
      visibleContentTabs = contentTabs.slice(0, 1);
    }

    // Count errors per tab key
    const errorCountByTab: Record<string, number> = {};
    for (const [fieldName] of Object.entries(errors)) {
      const field = getAllFields(definition).find((f) => f.fieldName === fieldName);
      const tabKey = getFieldTabKey(fieldName, field?.formTab);
      errorCountByTab[tabKey] = (errorCountByTab[tabKey] ?? 0) + 1;
    }

    const basicDataTab: ResolvedTab = {
      id: 'basicData',
      label: 'Datos básicos',
      badge: errorCountByTab['basicData'],
    };

    const additionalTabs: ResolvedTab[] = visibleContentTabs
      .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
      .map((t) => ({
        id: t.key,
        label: t.label,
        badge: errorCountByTab[t.key],
      }));

    const detailTabs: ResolvedTab[] = showDetailTabs
      ? (detailTabConfigs ?? []).map((dt) => ({ id: dt.key, label: dt.label }))
      : [];

    return [basicDataTab, ...additionalTabs, ...detailTabs];
  }, [definition, errors, navigationType, formMode, detailTabConfigs]);

  return (
    <div
      data-testid="tabs"
      className="flex flex-shrink-0 overflow-x-auto bg-transparent mb-2"
    >
      {items.map((item) => {
        const isActive = item.id === activeTabKey;
        const isBasicData = item.id === 'basicData';

        return (
          <button
            key={item.id}
            type="button"
            data-testid={`tab-${item.id}`}
            data-active={isActive}
            onClick={() => onTabChange(item.id)}
            className={`flex items-center gap-1.5 px-2.5 py-1.5 text-xs font-bold whitespace-nowrap cursor-pointer transition-colors border-b-2 bg-transparent ${
              isActive
                ? 'text-[#0c6ade] border-[#0e79fd]'
                : 'text-content-tertiary dark:text-dark-content-tertiary border-transparent hover:text-content-primary dark:hover:text-dark-content-primary hover:bg-black/[0.03] dark:hover:bg-white/[0.05] hover:rounded-t-md'
            }`}
          >
            {isBasicData ? (
              <>
                Datos básicos{' '}
                <span style={{ color: '#dc2626', fontSize: '12px' }}>*</span>
              </>
            ) : (
              item.label
            )}
            {item.badge != null && item.badge > 0 && (
              <span
                data-testid={`tab-error-badge-${item.id}`}
                className="inline-flex items-center justify-center w-4 h-4 bg-[#dc2626] text-white rounded-full text-[9px] font-bold"
              >
                {item.badge}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}
