import React from 'react';
import { TrendingUp, CheckCircle } from 'lucide-react';
import type { WizardFormData } from './types';
import type { EconomicIndicator } from '../../utils/indicatorsCatalog';

interface Step4AppearanceProps {
  formData: WizardFormData;
  onUpdateForm: (key: keyof WizardFormData, value: unknown) => void;
  /** Unidad del indicador seleccionado (para la vista previa) */
  indicatorUnidad?: string;
  /** Bandera del país del indicador (para la vista previa) */
  indicatorBandera?: string;
  /** Indicador completo seleccionado (para badge de resumen) */
  selectedIndicator?: EconomicIndicator | null;
  /** Si está en modo catálogo (muestra badge de resumen) */
  isCatalogMode?: boolean;
}

export const Step4Appearance: React.FC<Step4AppearanceProps> = ({
  formData,
  onUpdateForm,
  indicatorUnidad,
  indicatorBandera,
  selectedIndicator,
  isCatalogMode = false,
}) => {
  return (
    <div className="max-w-2xl mx-auto space-y-5">
      <h3 className="text-lg font-semibold text-gray-800">Apariencia y Dimensiones</h3>

      {/* Badge resumen — solo modo catálogo */}
      {isCatalogMode && selectedIndicator && (
        <div className="flex items-center gap-3 px-3 py-2.5 bg-gray-50 border border-gray-200 rounded-lg">
          <span className="text-xl flex-shrink-0">{selectedIndicator.bandera}</span>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-semibold text-gray-800 truncate">{selectedIndicator.nombre}</p>
            <p className="text-[11px] text-gray-400">KPI · {selectedIndicator.frecuencia} · {selectedIndicator.unidad}</p>
          </div>
          <div className="flex items-center gap-1.5 text-xs text-green-700 font-semibold flex-shrink-0">
            <CheckCircle className="w-3.5 h-3.5" /> Tipo y mapeo configurados
          </div>
        </div>
      )}

      <div className="grid gap-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Nombre del Widget</label>
          <input
            type="text"
            placeholder="Ej. Tasa de Conversión B2B"
            value={formData.nombre}
            onChange={e => onUpdateForm('nombre', e.target.value)}
            className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Descripción corta (opcional)</label>
          <input
            type="text"
            value={formData.descripcion}
            onChange={e => onUpdateForm('descripcion', e.target.value)}
            className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
          />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Categoría</label>
            <select
              value={formData.categoria}
              onChange={e => onUpdateForm('categoria', e.target.value)}
              className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white"
            >
              <option value="Ventas">Ventas</option>
              <option value="Compras">Compras</option>
              <option value="Inventario">Inventario</option>
              <option value="Operaciones">Operaciones</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Ancho por defecto</label>
            <select
              value={formData.cols_default}
              onChange={e => onUpdateForm('cols_default', Number(e.target.value))}
              className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white"
            >
              <option value={3}>Pequeño (3 cols)</option>
              <option value={6}>Mediano (6 cols)</option>
              <option value={12}>Ancho Total (12 cols)</option>
            </select>
          </div>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Frecuencia de actualización</label>
          <select
            value={formData.refresh_policy ?? 300}
            onChange={e => onUpdateForm('refresh_policy', Number(e.target.value))}
            className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white"
          >
            <option value={0}>Sin auto-refresh</option>
            <option value={30}>Cada 30 segundos</option>
            <option value={60}>Cada 1 minuto</option>
            <option value={120}>Cada 2 minutos</option>
            <option value={300}>Cada 5 minutos</option>
            <option value={600}>Cada 10 minutos</option>
            <option value={1800}>Cada 30 minutos</option>
          </select>
          <p className="text-xs text-gray-500 mt-1">Tiempo entre consultas automáticas al endpoint. Aplica cuando el widget está visible en el dashboard.</p>
        </div>
      </div>

      {/* Vista previa — solo KPI */}
      {formData.tipo === 'kpi' && (
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1.5">Vista previa</label>
          <div className="bg-gray-50 border border-gray-200 rounded-xl p-3">
            <div className="bg-white rounded-lg px-4 py-3 shadow-sm border border-gray-100">
              <p className="text-[10px] font-semibold text-gray-400 uppercase tracking-wide mb-1">
                {indicatorBandera && <span className="mr-1">{indicatorBandera}</span>}
                {formData.nombre || 'Widget'}
              </p>
              <p className="text-2xl font-bold text-gray-900 mb-1 tracking-tight">
                — {indicatorUnidad ?? ''}
              </p>
              <div className="flex items-center gap-2">
                <span className="text-xs text-green-600 font-semibold flex items-center gap-0.5">
                  <TrendingUp className="w-3 h-3" /> +0.00%
                </span>
                <span className="text-[11px] text-gray-400">· Hoy</span>
              </div>
              {formData.descripcion && (
                <p className="text-[11px] text-gray-400 mt-1">{formData.descripcion}</p>
              )}
            </div>
          </div>
          <p className="text-[11px] text-gray-400 mt-1">La vista previa muestra el layout — los valores reales se cargarán desde el endpoint.</p>
        </div>
      )}
    </div>
  );
};
