/**
 * FilterPanel — filter panel with basic field controls + advanced filters.
 *
 * Layout:
 * 1. Basic row: filterable field inputs + Estado ButtonGroup + Ver ButtonGroup (GLOBAL only)
 * 2. Action row: [Filtros avanzados ▾ (badge)] [spacer] [Limpiar] [Buscar]
 * 3. Advanced filters panel (collapsible):
 *    - Connector selector: Y (AND) / O (OR)
 *    - Condition rows: [#N] [Campo ▼] [Operador ▼] [Valor] [×]
 *    - "+ Agregar condición" button
 * 4. Chips row: visible when advanced conditions have values and panel is closed
 *
 * @module components/toolbar/FilterPanel
 * @see FMPV-MVWC-E002-S001 I-005
 */
import React, { useState, useCallback } from 'react';
import {
  Eraser, Search, Square, SquareCheck, SquareX,
  ChevronDown, Plus, X,
} from 'lucide-react';
import { Button } from '../../../Button/Button';
import { LookupField } from '../../../LookupField/LookupField';
import type { LookupRecord } from '../../../LookupField/LookupField.types';
import type { MasterPatternViewDefinition, MasterPatternViewLookupConfig } from '../../types/definition.types';
import { getAllFields } from '../../engine/fieldEngine';
import type { ActiveFilter } from '../../store/types';
import { useFieldEngine } from '../../hooks/useFieldEngine';
import type { FilterOperator } from '../../types/definition.types';

export interface FilterPanelProps {
  definition: MasterPatternViewDefinition;
  activeFilters: ActiveFilter[];
  onSearch: (filters: ActiveFilter[]) => void;
  onClear: () => void;
}

interface FilterValues {
  [field: string]: {
    value: string;
    valueTo?: string;
    operator: FilterOperator;
    booleanValue?: boolean | null;
  };
}

interface AdvCondition {
  id: string;
  field: string;
  operator: string;
  value: string;
  /** Human-readable label for lookup conditions (chip display) */
  displayLabel?: string;
}

// ── Operator sets by data type ─────────────────────────────────────────────
const STRING_OPS = [
  { value: 'contains',    label: 'contiene' },
  { value: 'starts_with', label: 'empieza con' },
  { value: 'equals',      label: 'es igual a' },
  { value: 'not_equals',  label: 'no es igual a' },
];
const NUMBER_OPS = [
  { value: 'equals',      label: 'es igual a' },
  { value: 'not_equals',  label: 'no es igual a' },
  { value: 'gt',          label: 'mayor que' },
  { value: 'gte',         label: 'mayor o igual a' },
  { value: 'lt',          label: 'menor que' },
  { value: 'lte',         label: 'menor o igual a' },
];
const DATE_OPS = [
  { value: 'gte',         label: 'desde' },
  { value: 'lte',         label: 'hasta' },
  { value: 'equals',      label: 'es igual a' },
];
const BOOLEAN_OPS = [
  { value: 'equals',      label: 'es igual a' },
];
const LOOKUP_OPS = [
  { value: 'equals',      label: 'es igual a' },
];

function getOpsForDataType(dataType: string) {
  if (dataType === 'number' || dataType === 'decimal') return NUMBER_OPS;
  if (dataType === 'date') return DATE_OPS;
  if (dataType === 'boolean') return BOOLEAN_OPS;
  return STRING_OPS;
}

function resolveDisplay(record: LookupRecord, cfg: MasterPatternViewLookupConfig): string {
  if (cfg.displayTemplate) {
    return cfg.displayTemplate.replace(/\{(\w+)\}/g, (_, k) => String(record[k] ?? ''));
  }
  if (cfg.displayValue) return String(record[cfg.displayValue] ?? '');
  return cfg.displayFields.map((f) => String(record[f] ?? '')).join(' ');
}

function buildInitialValues(activeFilters: ActiveFilter[]): FilterValues {
  const result: FilterValues = {};
  for (const f of activeFilters) {
    if (f.field.startsWith('__')) continue;
    result[f.field] = {
      value: String(f.value ?? ''),
      operator: (f.operator as FilterOperator) ?? 'contains',
    };
  }
  return result;
}

let _idSeq = 0;
function newId() { return `cond-${++_idSeq}`; }

// ── Shared styles ──────────────────────────────────────────────────────────
const inputClass =
  'border border-border-primary dark:border-dark-border-primary rounded-md px-2.5 py-1.5 text-xs text-content-primary dark:text-dark-content-primary bg-bg-primary dark:bg-dark-bg-primary ' +
  'focus:border-[#93d1fd] focus:outline-none focus:ring-[3px] focus:ring-[rgba(14,121,253,0.1)] transition-colors';
const selectClass =
  'border border-border-primary dark:border-dark-border-primary rounded-[6px] px-2 py-[5px] text-xs text-content-primary dark:text-dark-content-primary bg-bg-primary dark:bg-dark-bg-primary ' +
  'outline-none focus:border-[#93d1fd] transition-colors cursor-pointer';
const labelClass = 'text-[11px] font-semibold text-content-tertiary dark:text-dark-content-tertiary tracking-[0.3px]';

/**
 * Compact LookupField overrides injected via <style> tag.
 * Tailwind v4 breaks BEM double-underscore selectors in arbitrary variants,
 * so we inject plain CSS scoped via [data-testid="filter-panel"].
 */
const LOOKUP_COMPACT_CSS = `
[data-testid="filter-panel"] .lookup-field {
  gap: 0 !important;
}
[data-testid="filter-panel"] .lookup-field__trigger {
  height: 30px !important; padding: 4px 8px !important; font-size: 0.75rem !important;
}
[data-testid="filter-panel"] .lookup-field__placeholder,
[data-testid="filter-panel"] .lookup-field__selected-text {
  font-size: 0.75rem !important;
}
[data-testid="filter-panel"] .lookup-field__clear {
  width: 0.75rem !important; height: 0.75rem !important;
}
[data-testid="filter-panel"] .lookup-field__chevron {
  width: 0.75rem !important; height: 0.75rem !important;
}
[data-testid="filter-panel"] .lookup-field__search {
  height: 30px !important; padding: 4px 2rem !important; font-size: 0.75rem !important;
}
[data-testid="filter-panel"] .lookup-field__search-icon {
  width: 0.75rem !important; height: 0.75rem !important;
}
[data-testid="filter-panel"] .lookup-field__search-clear {
  width: 1rem !important; height: 1rem !important;
}
`;

export function FilterPanel({
  definition,
  activeFilters,
  onSearch,
  onClear,
}: FilterPanelProps) {
  const { filterControls } = useFieldEngine(definition);
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [filterValues, setFilterValues] = useState<FilterValues>(() =>
    buildInitialValues(activeFilters),
  );

  // Advanced filters state
  const [advOpen, setAdvOpen] = useState(false);
  const [connector, setConnector] = useState<'AND' | 'OR'>('AND');
  const [advConditions, setAdvConditions] = useState<AdvCondition[]>([]);

  const hasFilterableFields = filterControls.length > 0;

  const getFieldValue = (fieldName: string) =>
    filterValues[fieldName] ?? { value: '', operator: 'contains' as FilterOperator };

  const setFieldValue = useCallback((fieldName: string, value: string) => {
    setFilterValues((prev) => ({
      ...prev,
      [fieldName]: { ...getFieldValue(fieldName), ...prev[fieldName], value },
    }));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const setFieldProp = useCallback((fieldName: string, prop: string, val: unknown) => {
    setFilterValues((prev) => ({
      ...prev,
      [fieldName]: { ...getFieldValue(fieldName), ...prev[fieldName], [prop]: val },
    }));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ── Advanced conditions helpers ──────────────────────────────────────────

  const addCondition = useCallback(() => {
    const first = filterControls[0];
    const isFirstLookup = first?.inputType === 'lookup';
    const defaultOp = isFirstLookup
      ? 'equals'
      : getOpsForDataType(first?.dataType ?? 'string')[0]?.value ?? 'contains';
    setAdvConditions((prev) => [
      ...prev,
      { id: newId(), field: first?.fieldName ?? '', operator: defaultOp, value: '', displayLabel: '' },
    ]);
  }, [filterControls]);

  const removeCondition = useCallback((id: string) => {
    setAdvConditions((prev) => prev.filter((c) => c.id !== id));
  }, []);

  const updateCondition = useCallback(
    (id: string, patch: Partial<Omit<AdvCondition, 'id'>>) => {
      setAdvConditions((prev) =>
        prev.map((c) => {
          if (c.id !== id) return c;
          const updated = { ...c, ...patch };
          // Reset operator, value, and displayLabel when field changes
          if (patch.field && patch.field !== c.field) {
            const fc = filterControls.find((x) => x.fieldName === patch.field);
            const isNextLookup = fc?.inputType === 'lookup';
            updated.operator = isNextLookup
              ? 'equals'
              : getOpsForDataType(fc?.dataType ?? 'string')[0]?.value ?? 'contains';
            updated.value = '';
            updated.displayLabel = '';
          }
          return updated;
        }),
      );
    },
    [filterControls],
  );

  const handleAdvToggle = useCallback(() => {
    const nextOpen = !advOpen;
    setAdvOpen(nextOpen);

    if (nextOpen) {
      // Switching to advanced mode → clear basic filters
      setFilterValues({});
      setStatusFilter('all');
      // Auto-add first condition when opening empty panel
      if (advConditions.length === 0) {
        const first = filterControls[0];
        const isFirstLookup = first?.inputType === 'lookup';
        const defaultOp = isFirstLookup
          ? 'equals'
          : getOpsForDataType(first?.dataType ?? 'string')[0]?.value ?? 'contains';
        setAdvConditions([{ id: newId(), field: first?.fieldName ?? '', operator: defaultOp, value: '', displayLabel: '' }]);
      }
    } else {
      // Switching to basic mode → clear advanced conditions
      setAdvConditions([]);
      setConnector('AND');
    }
  }, [advOpen, advConditions.length, filterControls]);

  const activeAdvCount = advConditions.filter((c) => c.value.trim()).length;

  // ── Buscar / Limpiar ─────────────────────────────────────────────────────

  const handleBuscar = useCallback(() => {
    const statusActiveFilter: ActiveFilter[] =
      statusFilter !== 'all'
        ? [{ field: '__status', operator: 'equals', value: statusFilter }]
        : [];

    const basicFilters: ActiveFilter[] = filterControls
      .map((fc): ActiveFilter | null => {
        const fv = filterValues[fc.fieldName];
        if (!fv) return null;
        if (fc.dataType === 'boolean') {
          if (fv.booleanValue === null || fv.booleanValue === undefined) return null;
          return { field: fc.fieldName, operator: 'equals', value: fv.booleanValue };
        }
        if (!fv.value && !fv.valueTo) return null;
        return { field: fc.fieldName, operator: fv.operator ?? 'contains', value: fv.value };
      })
      .filter((f): f is ActiveFilter => f !== null);

    const activeAdv = advConditions.filter((c) => c.value.trim());
    const connectorFilter: ActiveFilter[] =
      activeAdv.length > 0
        ? [{ field: '__connector', operator: 'equals', value: connector }]
        : [];
    const advFilters: ActiveFilter[] = activeAdv.map((c) => ({
      field: c.field,
      operator: c.operator,
      value: c.value,
    }));

    const isAdvancedActive = advOpen || activeAdv.length > 0;
    setAdvOpen(false);
    onSearch([
      ...statusActiveFilter,
      ...(isAdvancedActive ? [] : basicFilters),
      ...connectorFilter,
      ...advFilters,
    ]);
  }, [filterControls, filterValues, statusFilter, connector, advConditions, advOpen, onSearch]);

  const handleLimpiar = useCallback(() => {
    setStatusFilter('all');
    setFilterValues({});
    setAdvConditions([]);
    setConnector('AND');
    setAdvOpen(false);
    onClear();
  }, [onClear]);

  // ── Static options ───────────────────────────────────────────────────────

  const STATUS_OPTS = [
    { value: 'all',      label: 'Todos',    icon: <Square size={16} /> },
    { value: 'active',   label: 'Activo',   icon: <SquareCheck size={16} /> },
    { value: 'inactive', label: 'Inactivo', icon: <SquareX size={16} /> },
  ];

  // ── Render ───────────────────────────────────────────────────────────────

  return (
    <div className="px-5 py-3.5 bg-background-secondary dark:bg-dark-bg-secondary border-b border-border-primary dark:border-dark-border-primary" data-testid="filter-panel">
      <style dangerouslySetInnerHTML={{ __html: LOOKUP_COMPACT_CSS }} />

      {/* ── Basic filter fields row ──────────────────────────────────────── */}
      <div
        {...((advOpen || activeAdvCount > 0) ? { inert: true } : {})}
        className={`flex flex-wrap items-end gap-3 transition-opacity duration-200 ${(advOpen || activeAdvCount > 0) ? 'opacity-50' : ''}`}
      >
        {filterControls.filter((fc) => fc.dataType !== 'boolean').map((fc) => {
          const fv = getFieldValue(fc.fieldName);

          if (fc.dataType === 'date') {
            return (
              <div key={fc.fieldName} className="flex flex-col gap-1" data-testid={`filter-${fc.fieldName}`}>
                <span className={labelClass}>{fc.label} desde</span>
                <input
                  type="date"
                  value={fv.value}
                  onChange={(e) => setFieldValue(fc.fieldName, e.target.value)}
                  className={inputClass}
                />
              </div>
            );
          }

          if (fc.inputType === 'select') {
            const field = getAllFields(definition).find((f) => f.fieldName === fc.fieldName);
            return (
              <div key={fc.fieldName} className="flex flex-col gap-1" data-testid={`filter-${fc.fieldName}`}>
                <span className={labelClass}>{fc.label}</span>
                <select
                  value={fv.value}
                  onChange={(e) => setFieldValue(fc.fieldName, e.target.value)}
                  className={`${inputClass} pr-6`}
                >
                  <option value="">Todos</option>
                  {(field?.options ?? []).map((opt) => (
                    <option key={opt.value} value={String(opt.value)}>{opt.label}</option>
                  ))}
                </select>
              </div>
            );
          }

          if (fc.dataType === 'number' || fc.dataType === 'decimal') {
            return (
              <div key={fc.fieldName} className="flex flex-col gap-1" data-testid={`filter-${fc.fieldName}`}>
                <span className={labelClass}>{fc.label}</span>
                <input
                  type="number"
                  value={fv.value}
                  onChange={(e) => setFieldValue(fc.fieldName, e.target.value)}
                  placeholder={fc.label}
                  className={`${inputClass} w-28`}
                />
              </div>
            );
          }

          // Lookup: render LookupField in the basic filter bar
          if (fc.inputType === 'lookup') {
            const fieldDef = getAllFields(definition).find((f) => f.fieldName === fc.fieldName);
            if (fieldDef?.lookupConfig) {
              return (
                <div key={fc.fieldName} className="flex flex-col gap-1" data-testid={`filter-${fc.fieldName}`}>
                  <span className={labelClass}>{fc.label}</span>
                  <div style={{ width: 200 }}>
                    <LookupField
                      entity={fieldDef.lookupConfig.entity}
                      fetcher={fieldDef.lookupConfig.fetcher}
                      displayFields={fieldDef.lookupConfig.displayFields}
                      displayTemplate={fieldDef.lookupConfig.displayTemplate}
                      displayValue={fieldDef.lookupConfig.displayValue}
                      filters={
                        fieldDef.lookupConfig.getFilters
                          ? fieldDef.lookupConfig.getFilters(
                              Object.fromEntries(
                                Object.entries(filterValues).map(([k, v]) => [k, v.value]),
                              ),
                            )
                          : fieldDef.lookupConfig.filters
                      }
                      minChars={fieldDef.lookupConfig.minChars}
                      value={fv.value || null}
                      onChange={(rec: LookupRecord | null) => {
                        setFieldValue(fc.fieldName, rec?.Id ?? '');
                        if (rec && fieldDef.lookupConfig?.onFilterSelect) {
                          fieldDef.lookupConfig.onFilterSelect(
                            rec as Record<string, unknown>,
                            (fieldName: string, val: unknown) =>
                              setFieldValue(fieldName, String(val ?? '')),
                          );
                        }
                      }}
                    />
                  </div>
                </div>
              );
            }
          }

          // Default: text
          return (
            <div key={fc.fieldName} className="flex flex-col gap-1" data-testid={`filter-${fc.fieldName}`}>
              <span className={labelClass}>{fc.label}</span>
              <input
                type="text"
                value={fv.value}
                onChange={(e) => setFieldValue(fc.fieldName, e.target.value)}
                placeholder={fc.label}
                className={`${inputClass} w-40`}
                data-testid={`filter-${fc.fieldName}-value`}
              />
            </div>
          );
        })}

        {/* Estado — always present, icon-only ButtonGroup */}
        <div className="flex flex-col gap-1" data-testid="filter-status">
          <span className={labelClass}>Estado</span>
          <div className="inline-flex">
            {STATUS_OPTS.map((opt, i) => (
              <button
                key={opt.value}
                type="button"
                role="radio"
                aria-checked={statusFilter === opt.value}
                title={opt.label}
                onClick={() => setStatusFilter(opt.value)}
                className={[
                  'flex items-center justify-center border transition-all',
                  i === 0 ? 'rounded-l-[4px]' : '',
                  i === STATUS_OPTS.length - 1 ? 'rounded-r-[4px] -ml-px' : '-ml-px',
                  statusFilter === opt.value
                    ? 'bg-[#0e79fd] border-[#3c9bf6] text-[#eff8ff] font-medium z-[1] relative'
                    : 'bg-bg-primary dark:bg-dark-bg-primary border-[#93d1fd] text-[#0e79fd] hover:bg-[#dbeefe]',
                ].join(' ')}
                style={{ padding: '6px 8px' }}
                data-testid={`filter-status-${opt.value}`}
              >
                {opt.icon}
              </button>
            ))}
          </div>
        </div>

      </div>

      {/* ── Action row ──────────────────────────────────────────────────────── */}
      <div className="flex items-center gap-2 mt-2.5">
        {/* Filtros avanzados toggle — only when there are filterable fields */}
        {hasFilterableFields && (
          <button
            type="button"
            onClick={handleAdvToggle}
            className={`inline-flex items-center gap-1.5 text-xs font-semibold cursor-pointer border-none transition-all ${
              advOpen
                ? 'text-[#0e79fd] bg-[#eff8ff] rounded-md px-2 py-1'
                : 'text-[#1355b7] hover:text-[#0c5ea6] bg-transparent p-0'
            }`}
            data-testid="filter-adv-toggle"
          >
            <ChevronDown
              size={13}
              className={`transition-transform duration-150 ${advOpen ? 'rotate-180' : ''}`}
            />
            Filtros avanzados
            {activeAdvCount > 0 && (
              <span className="bg-[#0e79fd] text-[#eff8ff] rounded-[10px] px-1.5 text-[10px] font-bold leading-[18px]">
                {activeAdvCount}
              </span>
            )}
          </button>
        )}

        <div className="flex-1" />

        <Button
          type="outline"
          size="l"
          leftIcon={<Eraser size={13} />}
          onClick={handleLimpiar}
          data-testid="filter-panel-clear"
        >
          Limpiar
        </Button>
        <Button
          type="default"
          size="l"
          leftIcon={<Search size={13} />}
          onClick={handleBuscar}
          data-testid="filter-panel-search"
        >
          Buscar
        </Button>
      </div>

      {/* ── Advanced filters panel (collapsible) ────────────────────────────── */}
      {advOpen && (
        <div
          className="mt-3 border border-border-primary dark:border-dark-border-primary rounded-lg overflow-hidden shadow-[0_1px_2px_rgba(0,0,0,0.04)]"
          data-testid="adv-filters-panel"
        >
          {/* Header */}
          <div className="bg-background-secondary dark:bg-dark-bg-secondary px-4 py-2 text-[11px] font-bold text-[#1355b7] border-b border-border-primary dark:border-dark-border-primary tracking-[0.4px] uppercase">
            Filtros avanzados
          </div>

          {/* Body */}
          <div className="bg-bg-primary dark:bg-dark-bg-primary px-4 py-3 flex flex-col gap-2.5">
            {/* Connector */}
            <div className="flex items-center gap-3 text-[11px] text-content-tertiary dark:text-dark-content-tertiary mb-1">
              <span className="font-semibold">Conector:</span>
              <label className="flex items-center gap-1 cursor-pointer">
                <input
                  type="radio"
                  name={`adv-connector-${definition.name}`}
                  value="AND"
                  checked={connector === 'AND'}
                  onChange={() => setConnector('AND')}
                />
                Y (todas las condiciones)
              </label>
              <label className="flex items-center gap-1 cursor-pointer">
                <input
                  type="radio"
                  name={`adv-connector-${definition.name}`}
                  value="OR"
                  checked={connector === 'OR'}
                  onChange={() => setConnector('OR')}
                />
                O (cualquier condición)
              </label>
            </div>

            {/* Condition rows */}
            {advConditions.map((cond, idx) => {
              const fc = filterControls.find((c) => c.fieldName === cond.field);
              const isLookup = fc?.inputType === 'lookup';
              const ops = isLookup ? LOOKUP_OPS : getOpsForDataType(fc?.dataType ?? 'string');
              const fieldDef = getAllFields(definition).find((f) => f.fieldName === cond.field);
              const isSelect = fc?.inputType === 'select';
              const isBoolean = fc?.dataType === 'boolean';
              const isDate = fc?.dataType === 'date';
              const isNumber = fc?.dataType === 'number' || fc?.dataType === 'decimal';

              return (
                <div
                  key={cond.id}
                  className="flex items-center gap-2"
                  data-testid={`adv-condition-${idx}`}
                >
                  {/* Row number */}
                  <span className="text-[11px] text-content-secondary dark:text-dark-content-secondary w-5 text-right flex-shrink-0 select-none">
                    #{idx + 1}
                  </span>

                  {/* Campo */}
                  <select
                    value={cond.field}
                    onChange={(e) => updateCondition(cond.id, { field: e.target.value })}
                    className={`${selectClass} w-[170px]`}
                    data-testid={`adv-condition-${idx}-field`}
                  >
                    {filterControls.map((f) => (
                      <option key={f.fieldName} value={f.fieldName}>{f.label}</option>
                    ))}
                  </select>

                  {/* Operador */}
                  <select
                    value={cond.operator}
                    onChange={(e) => updateCondition(cond.id, { operator: e.target.value })}
                    className={`${selectClass} w-[130px]`}
                    data-testid={`adv-condition-${idx}-operator`}
                  >
                    {ops.map((op) => (
                      <option key={op.value} value={op.value}>{op.label}</option>
                    ))}
                  </select>

                  {/* Valor */}
                  {isLookup && fieldDef?.lookupConfig ? (
                    <div style={{ width: 200 }} data-testid={`adv-condition-${idx}-value`}>
                      <LookupField
                        entity={fieldDef.lookupConfig.entity}
                        fetcher={fieldDef.lookupConfig.fetcher}
                        displayFields={fieldDef.lookupConfig.displayFields}
                        displayTemplate={fieldDef.lookupConfig.displayTemplate}
                        displayValue={fieldDef.lookupConfig.displayValue}
                        filters={
                          fieldDef.lookupConfig.getFilters
                            ? fieldDef.lookupConfig.getFilters(
                                Object.fromEntries(
                                  advConditions
                                    .filter((c) => c.value)
                                    .map((c) => [c.field, c.value]),
                                ),
                              )
                            : fieldDef.lookupConfig.filters
                        }
                        minChars={fieldDef.lookupConfig.minChars}
                        value={cond.value || null}
                        onChange={(rec: LookupRecord | null) => updateCondition(cond.id, {
                          value: rec?.Id ?? '',
                          displayLabel: rec && fieldDef.lookupConfig
                            ? resolveDisplay(rec, fieldDef.lookupConfig)
                            : '',
                        })}
                      />
                    </div>
                  ) : isSelect ? (
                    <select
                      value={cond.value}
                      onChange={(e) => updateCondition(cond.id, { value: e.target.value })}
                      className={`${selectClass} w-[140px]`}
                      data-testid={`adv-condition-${idx}-value`}
                    >
                      <option value="">Seleccionar...</option>
                      {(fieldDef?.options ?? []).map((opt) => (
                        <option key={opt.value} value={String(opt.value)}>{opt.label}</option>
                      ))}
                    </select>
                  ) : isBoolean ? (
                    <select
                      value={cond.value}
                      onChange={(e) => updateCondition(cond.id, { value: e.target.value })}
                      className={`${selectClass} w-[140px]`}
                      data-testid={`adv-condition-${idx}-value`}
                    >
                      <option value="">Seleccionar...</option>
                      <option value="true">Sí</option>
                      <option value="false">No</option>
                    </select>
                  ) : (
                    <input
                      type={isDate ? 'date' : isNumber ? 'number' : 'text'}
                      value={cond.value}
                      onChange={(e) => updateCondition(cond.id, { value: e.target.value })}
                      placeholder="Valor..."
                      className={selectClass}
                      style={{ width: 140 }}
                      data-testid={`adv-condition-${idx}-value`}
                    />
                  )}

                  {/* Remove */}
                  <button
                    type="button"
                    onClick={() => removeCondition(cond.id)}
                    title="Eliminar condición"
                    className="flex-shrink-0 text-content-secondary dark:text-dark-content-secondary hover:text-[#dc2626] bg-transparent border-none cursor-pointer p-0 transition-colors"
                    data-testid={`adv-condition-${idx}-remove`}
                  >
                    <X size={13} />
                  </button>
                </div>
              );
            })}

            {/* Add condition */}
            <button
              type="button"
              onClick={addCondition}
              className="inline-flex items-center gap-1 text-xs font-semibold text-[#0e79fd] hover:underline cursor-pointer bg-transparent border-none p-0 mt-1 self-start"
              data-testid="adv-add-condition"
            >
              <Plus size={13} />
              Agregar condición
            </button>
          </div>
        </div>
      )}

      {/* ── Chips: active advanced conditions when panel is closed ─────────── */}
      {!advOpen && activeAdvCount > 0 && (
        <div className="flex items-center flex-wrap gap-1.5 pt-2" data-testid="adv-chips">
          <span className="text-[11px] text-content-tertiary dark:text-dark-content-tertiary font-semibold">Filtros activos:</span>
          {advConditions
            .filter((c) => c.value.trim())
            .map((c) => {
              const fc = filterControls.find((x) => x.fieldName === c.field);
              return (
                <span
                  key={c.id}
                  className="inline-flex items-center gap-1.5 bg-[#eff8ff] border border-[#93d1fd] rounded-md px-2.5 py-0.5 text-[11px] text-[#1355b7]"
                >
                  {fc?.label ?? c.field}:{' '}
                  {fc?.inputType === 'lookup'
                    ? (c.displayLabel || c.value)
                    : fc?.dataType === 'boolean'
                      ? (c.value === 'true' ? 'Sí' : c.value === 'false' ? 'No' : c.value)
                      : c.value}
                </span>
              );
            })}
          <button
            type="button"
            onClick={handleLimpiar}
            className="text-[11px] text-content-tertiary dark:text-dark-content-tertiary underline cursor-pointer bg-transparent border-none p-0"
          >
            Limpiar filtros avanzados
          </button>
        </div>
      )}
    </div>
  );
}
