import React, { useState, useEffect, useMemo, useRef, useImperativeHandle } from 'react';
import { RuleEngine } from '../core/logic/RuleEngine';
import type { RuleEffects } from '../core/logic/RuleEngine';
import { useDynamicDefinition } from '../core/hooks/useDynamicDefinition';
import { DynamicFieldRenderer } from './DynamicFieldRenderer';
import { DynamicEntitiesApi } from '../core/api/DynamicEntitiesApi';
import { useDynamicEntitiesContext } from '../core/DynamicEntitiesProvider';


export interface DynamicEntitiesProps {
    featureCode: string;
    entityCode: string;
    recordId?: string;
    idEntityMultiple?: string;
    onSaved?: () => void;
    className?: string;
    hideSubmitButton?: boolean;
    hideTitle?: boolean;
}

export interface DynamicEntitiesRef {
    save: (overrideRecordId?: string) => Promise<boolean>;
}

export const DynamicEntities = React.forwardRef<DynamicEntitiesRef, DynamicEntitiesProps>(({
    featureCode,
    entityCode,
    recordId,
    idEntityMultiple,
    onSaved,
    className,
    hideSubmitButton,
    hideTitle
}, ref) => {
    const { baseUrl, onError } = useDynamicEntitiesContext();
    const { definition, loading, error } = useDynamicDefinition(featureCode, entityCode);

    const [values, setValues] = useState<Record<string, any>>({});
    const [errors, setErrors] = useState<Record<string, string>>({});
    const [saving, setSaving] = useState(false);

    // Referencia para evitar cierres obsoletos en la función save()
    const valuesRef = useRef(values);

    useEffect(() => {
        valuesRef.current = values;
    }, [values]);

    useEffect(() => {
        if (recordId && !loading && definition) {
            // For multi-record creation, if idEntityMultiple is provided but it's new, we shouldn't fetch unless we know it exists.
            // But usually we just attempt fetch.
            DynamicEntitiesApi.getValues(baseUrl, featureCode, entityCode, recordId, idEntityMultiple)
                .then(data => setValues(data.values))
                .catch(err => {
                    console.warn("Could not fetch values, assuming new or error", err);
                });
        }
    }, [recordId, idEntityMultiple, loading, definition, baseUrl, featureCode, entityCode]);

    // Rule Engine Integration
    const ruleEffects: RuleEffects = useMemo(() => {
        if (!definition || !definition.rules || definition.rules.length === 0) {
            return { hiddenFields: new Set(), disabledFields: new Set(), requiredFields: new Set() };
        }
        return RuleEngine.evaluate(definition, values);
    }, [definition, values]);

    const validate = (valuesToValidate: Record<string, any> = values) => {
        if (!definition) return true;
        const newErrors: Record<string, string> = {};

        definition.fields.forEach(field => {
            const val = valuesToValidate[field.code];
            // Apply Rule Effects
            if (ruleEffects.hiddenFields.has(field.code)) return; // Don't validate hidden fields

            if (!field.visible) return; // Base visibility
            if (field.disabled || ruleEffects.disabledFields.has(field.code)) return; // Don't validate disabled fields? Usually yes.

            const isRequired = field.required || ruleEffects.requiredFields.has(field.code);

            // Required check
            if (isRequired && (val === undefined || val === null || val === '')) {
                newErrors[field.code] = 'Este campo es obligatorio';
            }

            // Regex check
            if (val && field.regex) {
                try {
                    const regex = new RegExp(field.regex);
                    if (!regex.test(String(val))) {
                        newErrors[field.code] = 'El formato no es válido';
                    }
                } catch (e) {
                    console.warn(`Invalid regex for field ${field.code}`, field.regex);
                }
            }

            // Min/Max check (Numbers & Currency)
            if (val !== undefined && val !== null &&
                (field.type === 'NumberInteger' || field.type === 'NumberDecimal' || field.type === 'Currency')) {
                const num = Number(val);
                if (field.minValue !== undefined && field.minValue !== null && num < field.minValue) {
                    newErrors[field.code] = `El valor mínimo es ${field.minValue}`;
                }
                if (field.maxValue !== undefined && field.maxValue !== null && num > field.maxValue) {
                    newErrors[field.code] = `El valor máximo es ${field.maxValue}`;
                }
            }
        });

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const save = async (overrideRecordId?: string): Promise<boolean> => {
        const currentValues = valuesRef.current;

        if (!validate(currentValues)) return false;

        const finalRecordId = overrideRecordId || recordId;
        if (!finalRecordId) {
            console.error("No record ID provided for dynamic entities save");
            return false;
        }

        setSaving(true);
        try {
            await DynamicEntitiesApi.saveValues(baseUrl, featureCode, entityCode, finalRecordId, { values: currentValues }, idEntityMultiple);
            if (onSaved) onSaved();
            return true;
        } catch (err) {
            if (onError) onError(err as Error);
            return false;
        } finally {
            setSaving(false);
        }
    };

    useImperativeHandle(ref, () => ({
        save
    }));

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        await save();
    };

    if (loading) return <div>Cargando definición...</div>;
    if (error) return <div>Error cargando la definición: {error.message}</div>;
    if (!definition) return <div>No se encontró definición.</div>;

    return (
        <div className={`space-y-4 p-0 rounded-lg bg-white ${className || ''}`}>
            {!hideTitle && (
                <h2 className="text-xl font-bold mb-4">{definition.description || definition.entityCode}</h2>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {definition.fields
                    .filter(f => !ruleEffects.hiddenFields.has(f.code) && f.visible) // Filter hidden
                    .sort((a, b) => a.order - b.order)
                    .map(field => {
                        // Resolve Options from Definition Lists
                        let options: { label: string, value: string | number }[] = [];
                        if (field.genericListId) {
                            const list = definition.lists?.find(l => l.id === field.genericListId);
                            if (list) {
                                options = list.items
                                    .sort((a, b) => a.order - b.order)
                                    .map(item => ({ label: item.label, value: item.value }));
                            }
                        }

                        const colSpan = field.layouts?.find(l => l.breakpoint === 'md')?.colSpan || 1;
                        const isFullWidthDefault = field.type === 'TextArea';
                        const spanClass = isFullWidthDefault ? 'col-span-full md:col-span-full' :
                            colSpan === 2 ? 'col-span-1 md:col-span-2' :
                                colSpan === 3 ? 'col-span-1 md:col-span-3' :
                                    colSpan === 4 ? 'col-span-1 md:col-span-4' :
                                        'col-span-1 md:col-span-1';

                        return (
                            <div key={field.id} className={spanClass}>
                                <DynamicFieldRenderer
                                    field={{
                                        ...field,
                                        disabled: field.disabled || ruleEffects.disabledFields.has(field.code),
                                        required: field.required || ruleEffects.requiredFields.has(field.code)
                                    }}
                                    value={values[field.code]}
                                    error={errors[field.code]}
                                    onChange={(val) => {
                                        setValues(prev => ({ ...prev, [field.code]: val }));
                                        // Clear error on change
                                        if (errors[field.code]) setErrors(prev => ({ ...prev, [field.code]: '' }));
                                    }}
                                    options={options}
                                />
                            </div>
                        );
                    })}
            </div>

            {!hideSubmitButton && (
                <div className="flex justify-end pt-4">
                    <button
                        type="button"
                        onClick={handleSubmit}
                        disabled={saving}
                        className="px-3 py-1.5 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
                    >
                        {saving ? 'Guardando...' : 'Guardar Registro'}
                    </button>
                </div>
            )}
        </div>
    );
});
