import { createContext, useContext, useMemo, type ReactNode } from 'react';
import type { IMasterDocumentAdapter, DocumentState } from '../adapter/MasterDocumentAdapter.types';
import type { ApiService } from '../adapter/ApiService.types';
import type { MasterDocumentTemplate } from '../template/MasterDocumentTemplate.types';
import { createDefaultAdapter } from '../adapter/createDefaultAdapter';
import { DEFAULT_ICON_REGISTRY, type IconComponent } from './iconRegistry';
import { LookupResolveCacheProvider } from '../LookupReadonlyValue';
import { MasterDocumentPrintProvider } from '../printing/MasterDocumentPrintProvider';
import type { MasterDocumentPrintConfig } from '../printing/MasterDocumentPrinting.types';

// ════════════════════════════════════════════════════════════
// FACTBOX WIDGETS — registro de widgets custom
// ════════════════════════════════════════════════════════════

/**
 * Contexto en vivo que recibe un widget FactBox custom (`type: 'custom'`)
 * cuando se registra como función. Permite acceder al estado del documento y
 * al adapter para cablear widgets que dependen de datos en runtime
 * (ej: AdvanceApplicationsPanel necesita documentId, docState, headerValues).
 */
export interface FactBoxWidgetRenderContext {
  documentId: string;
  docState: string;
  mode: DocumentState['mode'];
  headerValues: Record<string, unknown>;
  /** Datos resueltos de la sección (según `dataSource`). */
  data: Record<string, unknown>;
  adapter: IMasterDocumentAdapter;
}

/**
 * Valor registrable en `factBoxWidgets`. Puede ser un nodo estático o una
 * función que recibe el contexto en vivo del documento y retorna el nodo.
 */
export type FactBoxWidget = ReactNode | ((ctx: FactBoxWidgetRenderContext) => ReactNode);

// ════════════════════════════════════════════════════════════
// CONTEXTS
// ════════════════════════════════════════════════════════════

const AdapterContext = createContext<IMasterDocumentAdapter | null>(null);
const TemplateContext = createContext<MasterDocumentTemplate | null>(null);
const IconContext = createContext<Record<string, IconComponent>>(DEFAULT_ICON_REGISTRY);
const FactBoxWidgetContext = createContext<Record<string, FactBoxWidget>>({});
// null = sistema de permisos no activo → mostrar y habilitar todo (fallback permisivo)
const PermissionsContext = createContext<string[] | null>(null);

// ════════════════════════════════════════════════════════════
// HOOKS
// ════════════════════════════════════════════════════════════

export function useMasterDocumentAdapter(): IMasterDocumentAdapter {
  const adapter = useContext(AdapterContext);
  if (!adapter) {
    throw new Error(
      'useMasterDocumentAdapter debe usarse dentro de un <MasterDocumentProvider>',
    );
  }
  return adapter;
}

export function useMasterDocumentTemplate(): MasterDocumentTemplate {
  const template = useContext(TemplateContext);
  if (!template) {
    throw new Error(
      'useMasterDocumentTemplate debe usarse dentro de un <MasterDocumentProvider>',
    );
  }
  return template;
}

export function useIconRegistry(): Record<string, IconComponent> {
  return useContext(IconContext);
}

export function useFactBoxWidgets(): Record<string, FactBoxWidget> {
  return useContext(FactBoxWidgetContext);
}

/**
 * Retorna los permisos del usuario activo, o `null` si el sistema de permisos
 * no está configurado en el provider (fallback permisivo: todo visible y editable).
 */
export function useUserPermissions(): string[] | null {
  return useContext(PermissionsContext);
}

// ════════════════════════════════════════════════════════════
// PROVIDER PROPS — Dos modos de uso
// ════════════════════════════════════════════════════════════

interface BaseProviderProps {
  template: MasterDocumentTemplate;
  icons?: Record<string, IconComponent>;
  factBoxWidgets?: Record<string, FactBoxWidget>;
  /**
   * Permisos del usuario activo. Cada string es una clave de permiso
   * (e.g. "view.cedula", "edit.precio").
   *
   * - Ausente / null → sistema de permisos no activo: todos los campos visibles y editables.
   * - [] → sistema activo pero sin permisos: campos restringidos quedan ocultos/deshabilitados.
   */
  userPermissions?: string[] | null;
  /**
   * Configuración de impresión nativa (opcional). Cuando se provee, el kit
   * muestra "Imprimir" en el menú de cada fila del listado y como botón en la
   * cabecera del detalle, abriendo un modal de vista previa con el visor que el
   * host inyecta. Sin esta prop, el comportamiento es idéntico al actual
   * (sin impresión) → retrocompatibilidad total.
   *
   * @see MasterDocumentPrintConfig
   */
  printing?: MasterDocumentPrintConfig;
  children: ReactNode;
}

/**
 * Modo manual: el consumidor provee su propio adapter.
 */
interface ManualAdapterProps extends BaseProviderProps {
  endpointAuto?: false;
  adapter: IMasterDocumentAdapter;
  apiService?: never;
}

/**
 * Modo auto: usa los endpoints estándar del contrato.
 * El consumidor solo entrega un apiService con baseUrl y headers.
 */
interface AutoEndpointProps extends BaseProviderProps {
  endpointAuto: true;
  apiService: ApiService;
  adapter?: never;
}

export type MasterDocumentProviderProps = ManualAdapterProps | AutoEndpointProps;

// ════════════════════════════════════════════════════════════
// PROVIDER
// ════════════════════════════════════════════════════════════

export function MasterDocumentProvider(props: MasterDocumentProviderProps) {
  const {
    template,
    icons,
    factBoxWidgets,
    userPermissions = null,
    printing,
    children,
  } = props;

  // Resolver el adapter según el modo
  const adapter = useMemo<IMasterDocumentAdapter>(() => {
    if (props.endpointAuto) {
      return createDefaultAdapter(props.apiService, template);
    }
    return props.adapter;
  }, [
    props.endpointAuto,
    // eslint-disable-next-line react-hooks/exhaustive-deps
    props.endpointAuto ? props.apiService : props.adapter,
    template,
  ]);

  const mergedIcons = useMemo(
    () => (icons ? { ...DEFAULT_ICON_REGISTRY, ...icons } : DEFAULT_ICON_REGISTRY),
    [icons],
  );

  const widgets = useMemo(
    () => factBoxWidgets ?? {},
    [factBoxWidgets],
  );

  return (
    <AdapterContext.Provider value={adapter}>
      <TemplateContext.Provider value={template}>
        <IconContext.Provider value={mergedIcons}>
          <FactBoxWidgetContext.Provider value={widgets}>
            <PermissionsContext.Provider value={userPermissions}>
              <LookupResolveCacheProvider>
                <MasterDocumentPrintProvider
                  printing={printing}
                  documentLabel={template.identity.label}
                >
                  {children}
                </MasterDocumentPrintProvider>
              </LookupResolveCacheProvider>
            </PermissionsContext.Provider>
          </FactBoxWidgetContext.Provider>
        </IconContext.Provider>
      </TemplateContext.Provider>
    </AdapterContext.Provider>
  );
}
