/**
 * FieldRenderer — resolves inputType and renders the appropriate field component.
 *
 * Wraps in a responsive grid cell based on colSize.
 * Renders readOnly text span in view mode.
 *
 * @module components/form/fields/FieldRenderer
 * @see FMPV-MVWC-E003-S002 I-001
 */
import React from 'react';
import { Input } from '../../../../Input/Input';
import { Textarea } from '../../../../Textarea/Textarea';
import { Select } from '../../../../Select/Select';
import { LookupField } from '../../../../LookupField/LookupField';
import { FileUploader } from '../../../../FileUploader/FileUploader';
import type { UploadedFile } from '../../../../FileUploader/FileUploader.types';
import { SquareCheck, SquareX, AlertTriangle } from 'lucide-react';
import { inferInputType, computeColSpanClass } from '../../../engine/fieldEngine';
import type { MasterPatternViewFieldDefinition, MasterPatternViewFileConfig } from '../../../types/definition.types';

type InitialFile = { id: string; url: string; name: string; size?: number; type?: string };
const EMPTY_FILES: InitialFile[] = [];

/**
 * Stable wrapper for FileUploader that avoids infinite re-render loops.
 * The initialFiles prop is memoized, and onFilesChange skips no-op updates.
 */
function FileField({ field, value, onChange, isDisabled, cfg }: {
  field: MasterPatternViewFieldDefinition;
  value: unknown;
  onChange: (v: unknown) => void;
  isDisabled: boolean;
  cfg: MasterPatternViewFileConfig;
}) {
  const initialFiles = React.useMemo((): InitialFile[] => {
    if (Array.isArray(value) && value.length > 0) {
      return value as InitialFile[];
    }
    return EMPTY_FILES;
  }, [value]);

  const handleFilesChange = React.useCallback((files: UploadedFile[]) => {
    // Only propagate when files actually changed (has completed uploads or was cleared)
    const completed = files.filter(f => f.status === 'completed' || (f as { id?: string }).id);
    if (completed.length > 0 || (Array.isArray(value) && (value as unknown[]).length > 0 && files.length === 0)) {
      onChange(files);
    }
  }, [onChange, value]);

  // Use compact padding override when field has rowSpan (image beside short inputs)
  const compactClass = field.rowSpan ? '[&>div]:p-3 [&>div]:space-y-1' : undefined;

  return (
    <FileUploader
      data-testid={`field-input-${field.fieldName}`}
      uploadFunction={cfg.uploadFunction}
      accept={cfg.accept}
      maxSize={cfg.maxSize}
      multiple={cfg.multiple}
      variant={cfg.variant}
      autoUpload={cfg.autoUpload}
      initialFiles={initialFiles}
      onFilesChange={handleFilesChange}
      disabled={isDisabled}
      className={compactClass}
    />
  );
}

export interface FieldRendererProps {
  field: MasterPatternViewFieldDefinition;
  value: unknown;
  onChange: (value: unknown) => void;
  error?: string;
  disabled?: boolean;
  readOnly?: boolean;
  /** All current form values — passed to renderFormField for derived/computed fields */
  allValues?: Record<string, unknown>;
  /** Current form mode — passed as context to renderFormField */
  formMode?: 'create' | 'edit' | 'view';
  /** Multi-field setter forwarded to lookupConfig.onFormSelect for cascade updates */
  setFormValue?: (field: string, value: unknown) => void;
}

export function FieldRenderer({
  field,
  value,
  onChange,
  error,
  disabled = false,
  readOnly = false,
  allValues = {},
  formMode,
  setFormValue,
}: FieldRendererProps) {
  const inputType = field.inputType ?? inferInputType(field);
  const colSpanClass = computeColSpanClass(field);
  const rowSpanClass = field.rowSpan && field.rowSpan > 1 ? `row-span-${field.rowSpan}` : '';
  const strValue = value !== null && value !== undefined ? String(value) : '';

  // Memoize select options to avoid passing a new array reference on every render,
  // which would defeat Select's internal stability guarantees.
  const selectOptions = React.useMemo(
    () => (field.options ?? []).map((o) => ({ value: o.value, label: o.label })),
    [field.options]
  );

  const label = (
    <label className="block text-sm font-bold text-content-primary dark:text-dark-content-primary mb-2 leading-5" data-testid={`field-label-${field.fieldName}`}>
      {field.label}
      {field.isRequired && <span className="text-red-500 ml-1">*</span>}
    </label>
  );

  const errorEl = error ? (
    <p className="flex items-center gap-[3px] text-xs text-[#dc2626] mt-1" data-testid={`field-error-${field.fieldName}`}>
      <AlertTriangle size={11} className="flex-shrink-0" />
      {error}
    </p>
  ) : null;

  // In readOnly mode fields are rendered as disabled controls (identical layout to edit mode)
  const isDisabled = disabled || readOnly;

  // renderFormField escape hatch — consumer controls the entire input element
  if (field.renderFormField) {
    const resolvedMode = formMode ?? (readOnly ? 'view' : 'edit');
    return (
      <div data-testid={`field-wrapper-${field.fieldName}`} className={`${colSpanClass} ${rowSpanClass}`.trim()}>
        {label}
        {field.renderFormField(value, onChange, allValues, { readOnly, mode: resolvedMode })}
        {errorEl}
      </div>
    );
  }

  let inputEl: React.ReactNode;

  switch (inputType) {
    case 'boolean': {
      // Native connected button group — replicates mock sk-btngroup exactly
      // (siesa-ui-kit ButtonGroup styles are overridden by Tailwind base reset)
      // If field has `options`, use option labels as text instead of icons.
      const btnBase = 'flex items-center justify-center cursor-pointer transition-all relative disabled:opacity-50 disabled:cursor-not-allowed';
      const hasCustomLabels = field.options && field.options.length >= 2;
      const trueLabel = hasCustomLabels ? field.options![0].label : null;
      const falseLabel = hasCustomLabels ? field.options![1].label : null;
      // Tooltip: use custom label if available, otherwise default "Activo"/"Inactivo"
      const trueTooltip = trueLabel ?? 'Activo';
      const falseTooltip = falseLabel ?? 'Inactivo';
      inputEl = (
        <div className="inline-flex" role="group" aria-label={field.label} data-testid={`field-input-${field.fieldName}`}>
          <button
            type="button"
            role="radio"
            aria-checked={value === true}
            title={trueTooltip}
            data-testid={`field-bool-yes-${field.fieldName}`}
            onClick={() => !isDisabled && onChange(true)}
            disabled={isDisabled}
            className={`${btnBase} rounded-l-md border`}
            style={{
              padding: hasCustomLabels ? '6px 12px' : '6px 8px',
              borderColor: value === true ? 'var(--border-color-primary-inverse-border)' : 'var(--border-color-primary-300)',
              background: value === true ? 'var(--text-color-primary-600)' : 'var(--mpv-surface)',
              color: value === true ? 'var(--text-color-primary-inverse-content)' : 'var(--text-color-primary-600)',
              fontWeight: value === true ? 500 : 400,
              fontSize: hasCustomLabels ? '0.75rem' : undefined,
              zIndex: value === true ? 1 : 'auto',
            }}
          >
            {trueLabel ?? <SquareCheck size={16} />}
          </button>
          <button
            type="button"
            role="radio"
            aria-checked={value === false}
            title={falseTooltip}
            data-testid={`field-bool-no-${field.fieldName}`}
            onClick={() => !isDisabled && onChange(false)}
            disabled={isDisabled}
            className={`${btnBase} rounded-r-md border -ml-px`}
            style={{
              padding: hasCustomLabels ? '6px 12px' : '6px 8px',
              borderColor: value === false ? 'var(--border-color-primary-inverse-border)' : 'var(--border-color-primary-300)',
              background: value === false ? 'var(--text-color-primary-600)' : 'var(--mpv-surface)',
              color: value === false ? 'var(--text-color-primary-inverse-content)' : 'var(--text-color-primary-600)',
              fontWeight: value === false ? 500 : 400,
              fontSize: hasCustomLabels ? '0.75rem' : undefined,
              zIndex: value === false ? 1 : 'auto',
            }}
          >
            {falseLabel ?? <SquareX size={16} />}
          </button>
        </div>
      );
      break;
    }

    case 'select':
      inputEl = (
        <Select
          data-testid={`field-input-${field.fieldName}`}
          options={selectOptions}
          value={value as string | number}
          onChange={onChange as (v: string | number) => void}
          disabled={isDisabled}
          selectSize="sm"
        />
      );
      break;

    case 'textarea':
      inputEl = (
        <Textarea
          data-testid={`field-input-${field.fieldName}`}
          value={strValue}
          onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => onChange(e.target.value)}
          disabled={isDisabled}
          fullWidth
        />
      );
      break;

    case 'date':
      inputEl = (
        <input
          type="date"
          data-testid={`field-input-${field.fieldName}`}
          value={strValue}
          onChange={(e) => onChange(e.target.value)}
          disabled={isDisabled}
          className="w-full border border-border-primary dark:border-dark-border-primary rounded px-2 py-1 text-sm disabled:bg-background-secondary dark:disabled:bg-dark-bg-secondary disabled:text-content-tertiary dark:disabled:text-dark-content-tertiary disabled:cursor-not-allowed"
        />
      );
      break;

    case 'number':
    case 'decimal':
      inputEl = (
        <Input
          type="number"
          data-testid={`field-input-${field.fieldName}`}
          value={strValue}
          step={inputType === 'decimal' ? 'any' : '1'}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => onChange(inputType === 'decimal' ? parseFloat(e.target.value) : parseInt(e.target.value, 10))}
          disabled={isDisabled}
        />
      );
      break;

    case 'lookup': {
      const cfg = field.lookupConfig;
      if (!cfg) {
        inputEl = (
          <Input
            data-testid={`field-input-${field.fieldName}`}
            value="[lookupConfig required]"
            disabled
          />
        );
      } else {
        // Wrap in a div that hides LookupField's internal empty label (which has display:block
        // and takes up ~20px even when empty, pushing the trigger below other inputs).
        inputEl = (
          <div className="[&_.lookup-field__label]:hidden">
            <LookupField
              data-testid={`field-input-${field.fieldName}`}
              entity={cfg.entity}
              fetcher={cfg.fetcher}
              displayFields={cfg.displayFields}
              displayTemplate={cfg.displayTemplate}
              displayValue={cfg.displayValue}
              filters={cfg.getFilters ? cfg.getFilters(allValues) : cfg.filters}
              minChars={cfg.minChars}
              value={strValue || null}
              onChange={(rec, prevRec) => {
                onChange(rec?.Id ?? null);
                if (cfg.onFormSelect && setFormValue) {
                  cfg.onFormSelect(rec ?? null, setFormValue, {
                    previousRecord: prevRec ?? null,
                    revert: () => onChange(prevRec?.Id ?? null),
                  });
                }
              }}
              readOnly={readOnly}
              disabled={disabled}
              // Do NOT pass required — the label above already renders the asterisk.
              // Passing required here causes LookupField to render a second asterisk.
            />
          </div>
        );
      }
      break;
    }

    case 'email':
    case 'password':
      inputEl = (
        <Input
          data-testid={`field-input-${field.fieldName}`}
          type={inputType}
          value={strValue}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => onChange(e.target.value)}
          readOnly={readOnly}
          disabled={disabled}
          required={field.isRequired}
          maxLength={field.maxLength}
        />
      );
      break;

    case 'file': {
      const cfg = field.fileConfig;
      if (!cfg) {
        inputEl = (
          <Input
            data-testid={`field-input-${field.fieldName}`}
            value="[fileConfig required]"
            disabled
          />
        );
      } else {
        inputEl = (
          <FileField
            field={field}
            value={value}
            onChange={onChange}
            isDisabled={isDisabled}
            cfg={cfg}
          />
        );
      }
      break;
    }

    default: // 'text'
      inputEl = (
        <Input
          data-testid={`field-input-${field.fieldName}`}
          value={strValue}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => onChange(e.target.value)}
          disabled={isDisabled}
          maxLength={field.maxLength}
        />
      );
  }

  return (
    <div data-testid={`field-wrapper-${field.fieldName}`} className={`${colSpanClass} ${rowSpanClass}`.trim()}>
      {label}
      {inputEl}
      {errorEl}
    </div>
  );
}

