import React, { useEffect, useCallback, useRef, useMemo, useState } from 'react';
import { useForm, useWatch } from 'react-hook-form';
import { clsx } from 'clsx';
import { FieldRenderer } from './FieldRenderer';
import type { MasterDocumentFormModalProps, MasterDocumentFormModalSection, ComputedRule, FieldError } from './MasterDocument.types';
import type { ServerRuleConfig } from './template/MasterDocumentTemplate.types';
import { evaluateCondition, extractDependencyFields } from './fieldCondition';
import type { FieldCondition } from './fieldCondition';

// ─── Icons ─────────────────────────────────────────────────

