/**
 * RowActions — per-row action buttons: Visualizar, Editar, Cambiar Estado.
 * All buttons always rendered and enabled; toast shown when permission absent (NEVER-HIDE).
 *
 * @module components/list/RowActions
 * @see FMPV-MVWC-E002-S003 I-005
 */
import React, { useCallback } from 'react';
import { Eye, Pencil, Power } from 'lucide-react';
import type { MasterPatternViewPermissions } from '../../types/permissions.types';
import type { MasterPatternViewEntity } from '../../types/service.types';
import type { MasterPatternViewCustomAction, MasterPatternViewDefaultActions } from '../../types/props.types';
import { isActionAllowed, getDisabledToastMessage } from '../../engine/permissionEngine';
import { useToast, type ToastCallback } from '../../hooks/useToast';

export interface RowActionsProps<T extends MasterPatternViewEntity = MasterPatternViewEntity> {
  row: T;
  permissions?: MasterPatternViewPermissions;
  onOpenView: (row: T) => void;
  onOpenEdit: (row: T) => void;
  onChangeStatus?: (row: T) => void;
  actions?: MasterPatternViewCustomAction<T>[];
  rowActions?: (row: T) => React.ReactNode;
  toast?: ToastCallback;
  defaultActions?: MasterPatternViewDefaultActions<T>;
}

function resolveActionConfig<T>(
  value: boolean | ((row: T) => boolean) | undefined,
  row: T,
  defaultValue: boolean,
): boolean {
  if (value === undefined) return defaultValue;
  if (typeof value === 'function') return value(row);
  return value;
}

export function RowActions<T extends MasterPatternViewEntity = MasterPatternViewEntity>({
  row,
  permissions,
  onOpenView,
  onOpenEdit,
  onChangeStatus,
  actions = [],
  rowActions,
  toast: toastProp,
  defaultActions,
}: RowActionsProps<T>) {
  const { showWarning } = useToast(toastProp);
  const canRead = isActionAllowed(permissions, 'READ', 'UNIVERSAL');
  const canUpdate = isActionAllowed(permissions, 'UPDATE', 'UNIVERSAL');
  const canChangeStatus = isActionAllowed(permissions, 'CHANGE_STATUS', 'UNIVERSAL');

  const showView = resolveActionConfig(defaultActions?.view?.show, row, true);
  const disabledView = resolveActionConfig(defaultActions?.view?.disabled, row, false);
  const showEdit = resolveActionConfig(defaultActions?.edit?.show, row, true);
  const disabledEdit = resolveActionConfig(defaultActions?.edit?.disabled, row, false);
  const showChangeStatus = resolveActionConfig(defaultActions?.changeStatus?.show, row, true);
  const disabledChangeStatus = resolveActionConfig(defaultActions?.changeStatus?.disabled, row, false);

  const handleView = useCallback(() => {
    if (!canRead) {
      showWarning(getDisabledToastMessage('READ'));
      return;
    }
    onOpenView(row);
  }, [canRead, showWarning, onOpenView, row]);

  const handleEdit = useCallback(() => {
    if (!canUpdate) {
      showWarning(getDisabledToastMessage('UPDATE'));
      return;
    }
    onOpenEdit(row);
  }, [canUpdate, showWarning, onOpenEdit, row]);

  const handleChangeStatus = useCallback(() => {
    if (!canChangeStatus) {
      showWarning(getDisabledToastMessage('CHANGE_STATUS'));
      return;
    }
    onChangeStatus?.(row);
  }, [canChangeStatus, showWarning, onChangeStatus, row]);

  const actionBtnClass =
    'inline-flex items-center justify-center w-7 h-7 bg-bg-primary dark:bg-dark-bg-primary border border-border-primary dark:border-dark-border-primary text-[#0e79fd] rounded-md shadow-[0_1px_2px_rgba(0,0,0,0.04)] cursor-pointer transition-all hover:bg-[#eff8ff] hover:border-[#93d1fd] disabled:opacity-50 disabled:cursor-not-allowed';

  return (
    <div className="flex items-center gap-1" data-testid={`row-actions-${row.id}`}>
      {/* Visualizar — toast when no permission; hidden or disabled via defaultActions */}
      {showView && (
        <button
          type="button"
          onClick={handleView}
          disabled={disabledView}
          data-testid="row-action-view"
          aria-label="Visualizar"
          className={actionBtnClass}
        >
          <Eye size={15} />
        </button>
      )}

      {/* Editar — toast when no permission; hidden or disabled via defaultActions */}
      {showEdit && (
        <button
          type="button"
          onClick={handleEdit}
          disabled={disabledEdit}
          data-testid="row-action-edit"
          aria-label="Editar"
          className={actionBtnClass}
        >
          <Pencil size={15} />
        </button>
      )}

      {/* Cambiar estado — toast when no permission; hidden or disabled via defaultActions */}
      {showChangeStatus && (
        <button
          type="button"
          onClick={handleChangeStatus}
          disabled={disabledChangeStatus}
          data-testid="row-action-change-status"
          aria-label="Cambiar estado"
          className={actionBtnClass}
        >
          <Power size={15} />
        </button>
      )}

      {/* Custom actions */}
      {actions
        .filter((a) => !a.position || a.position === 'row')
        .map((action) => {
          const isDisabled = action.isDisabled?.(row) ?? false;
          return (
            <button
              key={action.key}
              type="button"
              onClick={() => !isDisabled && action.onExecute(row)}
              disabled={isDisabled}
              data-testid={`row-action-${action.key}`}
              aria-label={action.label}
              className={actionBtnClass}
            >
              {action.icon}
            </button>
          );
        })}

      {/* rowActions escape hatch */}
      {rowActions?.(row)}
    </div>
  );
}
