import { isToday, formatDistanceToNow, format } from 'date-fns';
import { es } from 'date-fns/locale';

/**
 * Formatea un timestamp ISO 8601 para mostrar en la timeline:
 * - Mismo día → tiempo relativo: "hace 2 horas"
 * - Día anterior o más antiguo → fecha: "17/04/2026"
 */
export function formatAuditTimestamp(isoTimestamp: string): string {
  const date = new Date(isoTimestamp);
  if (isToday(date)) {
    return formatDistanceToNow(date, { addSuffix: true, locale: es });
  }
  return format(date, 'dd/MM/yyyy', { locale: es });
}

/**
 * Formatea un timestamp con fecha y hora exactas para el atributo `title` (tooltip on hover).
 * Ejemplo: "17/04/2026 14:30:05"
 */
export function formatAuditTimestampExact(isoTimestamp: string): string {
  return format(new Date(isoTimestamp), 'dd/MM/yyyy HH:mm:ss', { locale: es });
}
