import React from 'react';
import { formatAuditTimestamp, formatAuditTimestampExact } from '../utils/formatAuditTimestamp';
import type { AuditTimestampProps } from './AuditTimestamp.types';

/**
 * Muestra un timestamp de auditoría de forma adaptativa:
 * - Mismo día: tiempo relativo ("hace 2 horas")
 * - Días anteriores: fecha completa ("17/04/2026")
 * - Hover: fecha y hora exacta vía atributo `title`
 */
export const AuditTimestamp: React.FC<AuditTimestampProps> = ({ timestamp, className = '' }) => {
  const classes = ['text-sm text-slate-500 dark:text-slate-400', className]
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();

  return (
    <time dateTime={timestamp} title={formatAuditTimestampExact(timestamp)} className={classes}>
      {formatAuditTimestamp(timestamp)}
    </time>
  );
};

AuditTimestamp.displayName = 'AuditTimestamp';
