import { clsx } from 'clsx';
import { LockClosedIcon } from '@heroicons/react/24/outline';
import { LookupField } from '../LookupField';
import type { Fetcher } from '../LookupField/services/api.types';
import { LookupReadonlyValue } from './LookupReadonlyValue';
import type { FieldRendererProps, ControlType, LookupFieldConfig } from './MasterDocument.types';

// ─── Estilos base (alineados con Input del UI Kit) ─────────

const inputBase = clsx(
  'w-full rounded-md border border-border-primary bg-bg-primary px-3 py-1.5 text-sm text-content-primary',
  'placeholder:text-content-tertiary',
  'hover:border-primary-600',
  'focus:outline-hidden focus:border-primary-600 focus:ring-2 focus:ring-primary-400 focus:ring-offset-2',
  'disabled:opacity-50 disabled:cursor-not-allowed',
  'transition-all duration-150',
  'dark:bg-dark-bg-primary dark:border-dark-border-primary dark:text-dark-content-primary',
  'dark:placeholder:text-dark-content-tertiary',
  'dark:hover:border-dark-border-custom',
  'dark:focus:border-dark-border-custom dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary',
);

const inputError = 'border-error-border focus:border-error-border focus:ring-error-border/30 dark:border-error-border dark:focus:border-error-border dark:focus:ring-error-border/30';

// Controles "con valor" sobre los que aplica el resaltado de requerido-vacío.
// Se excluyen toggle/checkbox (un booleano nunca está "vacío" de forma útil) y
// los de solo lectura (readonly/display).
const REQUIRED_HIGHLIGHT_CONTROLS: ControlType[] = [
  'text', 'number', 'currency', 'percentage',
  'date', 'select', 'searcher', 'autocomplete', 'textarea',
];

function isEmptyValue(value: unknown): boolean {
  return value === null || value === undefined || (typeof value === 'string' && value.trim() === '');
}

const readonlyBase = clsx(
  'w-full rounded-md bg-background-secondary px-3 py-1.5 text-sm text-content-primary select-none',
  'dark:bg-dark-bg-secondary dark:text-dark-content-primary',
);

const labelBase = clsx(
  'block text-xs font-bold text-content-secondary mb-1 uppercase tracking-wide',
  'dark:text-dark-content-secondary',
);

// ─── ReadonlyField ─────────────────────────────────────────

function ReadonlyField({ value, isMono }: { value: unknown; isMono?: boolean }) {
  const displayValue = value == null || value === '' ? '—' : String(value);
  return (
    <div className={clsx(readonlyBase, isMono && 'tabular-nums')}>
      {displayValue}
    </div>
  );
}

// ─── Controles individuales ────────────────────────────────

function TextInput({
  value,
  onChange,
  placeholder,
  hasError,
}: {
  value: unknown;
  onChange: (v: unknown) => void;
  placeholder?: string;
  hasError: boolean;
}) {
  return (
    <input
      type="text"
      className={clsx(inputBase, hasError && inputError)}
      value={value == null ? '' : String(value)}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
    />
  );
}

function NumberInput({
  value,
  onChange,
  placeholder,
  hasError,
  prefix,
  suffix,
}: {
  value: unknown;
  onChange: (v: unknown) => void;
  placeholder?: string;
  hasError: boolean;
  prefix?: string;
  suffix?: string;
}) {
  return (
    <div className="relative">
      {prefix && (
        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-sm text-content-secondary dark:text-dark-content-secondary pointer-events-none select-none">
          {prefix}
        </span>
      )}
      <input
        type="number"
        className={clsx(
          inputBase,
          hasError && inputError,
          'tabular-nums',
          prefix && 'pl-7',
          suffix && 'pr-7',
        )}
        value={value == null ? '' : String(value)}
        onChange={(e) => {
          const raw = e.target.value;
          onChange(raw === '' ? null : Number(raw));
        }}
        placeholder={placeholder}
      />
      {suffix && (
        <span className="absolute right-3 top-1/2 -translate-y-1/2 text-sm text-content-secondary dark:text-dark-content-secondary pointer-events-none select-none">
          {suffix}
        </span>
      )}
    </div>
  );
}

function DateInput({
  value,
  onChange,
  hasError,
}: {
  value: unknown;
  onChange: (v: unknown) => void;
  hasError: boolean;
}) {
  return (
    <input
      type="date"
      className={clsx(inputBase, hasError && inputError, 'tabular-nums')}
      value={value == null ? '' : String(value)}
      onChange={(e) => onChange(e.target.value)}
    />
  );
}

function SelectInput({
  value,
  onChange,
  options,
  placeholder,
  hasError,
}: {
  value: unknown;
  onChange: (v: unknown) => void;
  options?: Array<{ label: string; value: string | number }>;
  placeholder?: string;
  hasError: boolean;
}) {
  return (
    <select
      className={clsx(inputBase, hasError && inputError, 'cursor-pointer')}
      value={value == null ? '' : String(value)}
      onChange={(e) => onChange(e.target.value)}
    >
      {placeholder && (
        <option value="" disabled>
          {placeholder}
        </option>
      )}
      {options?.map((opt) => (
        <option key={opt.value} value={opt.value}>
          {opt.label}
        </option>
      ))}
    </select>
  );
}

// ─── SearcherInput — LookupField real o fallback ──────────

function SearcherControl({
  value,
  onChange,
  placeholder,
  hasError,
  lookupConfig,
  fetcher,
  onRecordSelect,
  getLookupFilters,
  lookupDependencies,
  disabled,
}: {
  value: unknown;
  onChange: (v: unknown) => void;
  placeholder?: string;
  hasError: boolean;
  lookupConfig?: LookupFieldConfig;
  fetcher?: unknown;
  onRecordSelect?: (record: Record<string, unknown> | null) => void;
  getLookupFilters?: () => unknown;
  lookupDependencies?: unknown[];
  disabled?: boolean;
}) {
  // Si hay lookupConfig y fetcher, renderizar LookupField real
  if (lookupConfig && fetcher) {
    // Campos de ETIQUETA del dropdown: se derivan del displayTemplate cuando
    // existe (p.ej. "{code} - {name}" → ["code", "name"]); si no hay template
    // se mantienen los displayFields configurados (sin regresión).
    const labelFields = lookupConfig.displayTemplate
      ? [...lookupConfig.displayTemplate.matchAll(/\{(\w+)\}/g)].map((m) => m[1])
      : lookupConfig.displayFields;
    // Campos que SÍ deben traerse del backend: los displayFields originales más
    // los campos de origen del bindFields (Record formulario→registro), para no
    // romper el autollenado en endpoints genéricos que solo devuelven lo pedido.
    // Se pasan como `bindFields` del LookupField (se piden pero NO se muestran).
    const fetchFields = [
      ...new Set([
        ...lookupConfig.displayFields,
        ...Object.values(lookupConfig.bindFields ?? {}),
      ]),
    ];
    return (
      <LookupField
        entity={lookupConfig.entity}
        displayFields={labelFields}
        bindFields={fetchFields}
        searchFields={lookupConfig.searchFields}
        displayTemplate={lookupConfig.displayTemplate}
        fetcher={fetcher as Fetcher}
        value={value ? String(value) : null}
        onChange={(record: Record<string, unknown> | null) => {
          if (!record) {
            onChange(null);
            onRecordSelect?.(null);
            return;
          }
          const valField = lookupConfig.valueField ?? 'Id';
          let newValue = record[valField];
          // Fallback Id → id
          if (newValue === undefined && valField === 'Id' && record['id'] !== undefined) {
            newValue = record['id'];
          }
          onChange(newValue ?? null);
          onRecordSelect?.(record);
        }}
        placeholder={placeholder ?? 'Buscar...'}
        pageSize={lookupConfig.pageSize ?? 10}
        filters={lookupConfig.filters as never}
        getFilters={getLookupFilters as never}
        dependencies={lookupDependencies}
        disabled={disabled}
        error={hasError}
      />
    );
  }

  // Fallback: input de texto simple con icono de búsqueda
  return (
    <div className="relative">
      <svg
        className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-content-secondary dark:text-dark-content-secondary pointer-events-none"
        fill="none"
        viewBox="0 0 24 24"
        stroke="currentColor"
        strokeWidth={2}
        aria-hidden="true"
      >
        <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
      </svg>
      <input
        type="text"
        className={clsx(inputBase, hasError && inputError, 'pl-9')}
        value={value == null ? '' : String(value)}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder ?? 'Buscar...'}
        aria-label="Buscar"
        disabled={disabled}
      />
    </div>
  );
}

function TextareaInput({
  value,
  onChange,
  placeholder,
  hasError,
}: {
  value: unknown;
  onChange: (v: unknown) => void;
  placeholder?: string;
  hasError: boolean;
}) {
  return (
    <textarea
      className={clsx(inputBase, hasError && inputError, 'min-h-[72px] resize-y')}
      value={value == null ? '' : String(value)}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      rows={3}
    />
  );
}

function ToggleInput({
  value,
  onChange,
}: {
  value: unknown;
  onChange: (v: unknown) => void;
}) {
  const checked = Boolean(value);
  return (
    <button
      type="button"
      role="switch"
      aria-checked={checked}
      className={clsx(
        'relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-all duration-150',
        'focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2',
        'dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary',
        checked ? 'bg-primary-inverse-background dark:bg-dark-bg-inverse' : 'bg-border-primary dark:bg-dark-border-primary',
      )}
      onClick={() => onChange(!checked)}
    >
      <span
        className={clsx(
          'pointer-events-none inline-block h-5 w-5 transform rounded-full bg-bg-primary dark:bg-dark-content-primary shadow-sm transition-transform duration-150',
          checked ? 'translate-x-5' : 'translate-x-0',
        )}
      />
    </button>
  );
}

function CheckboxInput({
  value,
  onChange,
}: {
  value: unknown;
  onChange: (v: unknown) => void;
}) {
  const checked = Boolean(value);
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={checked}
      className={clsx(
        'flex h-[18px] w-[18px] items-center justify-center rounded-sm border-2 transition-all duration-150 cursor-pointer',
        'focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2',
        'dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary',
        checked
          ? 'border-primary-600 bg-primary-inverse-background dark:bg-dark-bg-inverse'
          : 'border-border-primary bg-bg-primary dark:border-dark-border-primary dark:bg-dark-bg-primary',
      )}
      onClick={() => onChange(!checked)}
    >
      {checked && (
        <svg className="h-3 w-3 text-primary-inverse-content dark:text-dark-content-inverse" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
        </svg>
      )}
    </button>
  );
}

// ─── FieldRenderer ─────────────────────────────────────────

/**
 * Renderizador genérico de campos del documento maestro.
 *
 * Selecciona el control apropiado (text, number, currency, select, toggle, etc.)
 * según `fieldDef.control` y aplica el estado de solo lectura, error y accesibilidad.
 * Compatible con LookupField cuando se provee `lookupConfig` y `fetcher`.
 *
 * @see docs/colors.md - Sistema de tokens de color
 * @see MasterDocument.types - FieldRendererProps, FieldDescriptor, ControlType
 *
 * @example
 * ```tsx
 * <FieldRenderer
 *   fieldDef={{ key: 'cliente', label: 'Cliente', control: 'searcher', order: 1, span: 1, editableOn: ['DRAFT'] }}
 *   value="CLI-001"
 *   onChange={(v) => updateField('cliente', v)}
 *   editable={true}
 * />
 * ```
 */
export function FieldRenderer({
  fieldDef,
  value,
  onChange,
  editable,
  error,
  readOnly,
  className,
  lookupConfig,
  fetcher,
  onRecordSelect,
  getLookupFilters,
  lookupDependencies,
  disabled,
  locked,
  lockTooltip,
}: FieldRendererProps) {
  // Un campo bloqueado siempre se muestra como solo-lectura, independientemente
  // de su editabilidad por estado.
  const isReadOnly =
    locked ||
    !editable ||
    readOnly ||
    fieldDef.control === 'readonly' ||
    fieldDef.control === 'display';

  const lockTooltipText =
    lockTooltip ?? 'Elimine las líneas para poder cambiar este campo.';

  const isMono = ['number', 'currency', 'percentage', 'date'].includes(fieldDef.control);
  const hasError = !!error && error.severity === 'error';
  const hasWarning = !!error && error.severity === 'warning';
  const errorId = error ? `field-error-${fieldDef.key}` : undefined;

  // Validación en vivo (solo cliente): un campo obligatorio editable y sin valor
  // se resalta con borde rojo para que se note que falta llenarlo. No emite
  // mensaje propio (el asterisco ya indica que es requerido); el mensaje queda
  // reservado para los errores explícitos de `error` (validación/servidor).
  const isRequiredEmpty =
    !!fieldDef.required &&
    !isReadOnly &&
    !disabled &&
    REQUIRED_HIGHLIGHT_CONTROLS.includes(fieldDef.control) &&
    isEmptyValue(value);

  // El borde rojo se prende tanto por un error explícito como por requerido-vacío.
  const showErrorBorder = hasError || isRequiredEmpty;

  // Render control
  function renderControl(control: ControlType) {
    const placeholder = fieldDef.placeholder;
    const options = fieldDef.options;

    switch (control) {
      case 'text':
        return <TextInput value={value} onChange={onChange} placeholder={placeholder} hasError={showErrorBorder} />;
      case 'number':
        return <NumberInput value={value} onChange={onChange} placeholder={placeholder} hasError={showErrorBorder} />;
      case 'currency':
        return <NumberInput value={value} onChange={onChange} placeholder={placeholder} hasError={showErrorBorder} prefix="$" />;
      case 'percentage':
        return <NumberInput value={value} onChange={onChange} placeholder={placeholder} hasError={showErrorBorder} suffix="%" />;
      case 'date':
        return <DateInput value={value} onChange={onChange} hasError={showErrorBorder} />;
      case 'select':
        return <SelectInput value={value} onChange={onChange} options={options} placeholder={placeholder} hasError={showErrorBorder} />;
      case 'searcher':
      case 'autocomplete':
        return (
          <SearcherControl
            value={value}
            onChange={onChange}
            placeholder={placeholder}
            hasError={showErrorBorder}
            lookupConfig={lookupConfig}
            fetcher={fetcher}
            onRecordSelect={onRecordSelect}
            getLookupFilters={getLookupFilters}
            lookupDependencies={lookupDependencies}
            disabled={disabled}
          />
        );
      case 'textarea':
        return <TextareaInput value={value} onChange={onChange} placeholder={placeholder} hasError={showErrorBorder} />;
      case 'toggle':
        return <ToggleInput value={value} onChange={onChange} />;
      case 'checkbox':
        return <CheckboxInput value={value} onChange={onChange} />;
      case 'readonly':
      case 'display':
        return <ReadonlyField value={value} />;
      default: {
        const _exhaustive: never = control;
        return <ReadonlyField value={_exhaustive} />;
      }
    }
  }

  // Render solo-lectura: para searcher/autocomplete resuelve el id a su etiqueta
  // ("código - nombre") reutilizando fetcher + lookupConfig; para select resuelve
  // el value crudo a la etiqueta de su opción (mismas options que en edición); el
  // resto de controles mantienen el render plano del valor crudo (sin regresión).
  function renderReadonly() {
    const control = fieldDef.control;
    if ((control === 'searcher' || control === 'autocomplete') && lookupConfig && fetcher) {
      return <LookupReadonlyValue id={value} lookupConfig={lookupConfig} fetcher={fetcher} isMono={isMono} />;
    }
    if (control === 'select') {
      // Buscar la opción cuyo value coincide con el valor del campo y mostrar su
      // label. Si las opciones no cargaron o no hay match, fallback al value crudo.
      const match = fieldDef.options?.find((opt) => String(opt.value) === String(value));
      return <ReadonlyField value={match ? match.label : value} isMono={isMono} />;
    }
    return <ReadonlyField value={value} isMono={isMono} />;
  }

  return (
    <div className={clsx('flex flex-col gap-1', className)}>
      {/* Label */}
      <label className={clsx(labelBase, 'flex items-center gap-1')}>
        <span>{fieldDef.label}</span>
        {fieldDef.required && !isReadOnly && (
          <span className="text-error-content ml-0.5">*</span>
        )}
        {locked && (
          <span
            className="inline-flex cursor-not-allowed text-content-tertiary dark:text-dark-content-tertiary"
            title={lockTooltipText}
            aria-label={lockTooltipText}
          >
            <LockClosedIcon className="h-3.5 w-3.5" aria-hidden="true" />
          </span>
        )}
      </label>

      {/* Control */}
      {locked ? (
        <div className="cursor-not-allowed" title={lockTooltipText}>
          {renderReadonly()}
        </div>
      ) : isReadOnly ? (
        renderReadonly()
      ) : (
        <div className="relative" aria-invalid={showErrorBorder || undefined} aria-describedby={errorId}>
          {renderControl(fieldDef.control)}
          {hasWarning && (
            <svg
              className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-amber-600 dark:text-amber-400"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
              strokeWidth={2}
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4.5c-.77-.833-2.694-.833-3.464 0L3.34 16.5c-.77.833.192 2.5 1.732 2.5z"
              />
            </svg>
          )}
        </div>
      )}

      {/* Error / Warning message */}
      {error && (
        <span
          id={errorId}
          role="alert"
          className={clsx(
            'text-xs leading-tight',
            error.severity === 'error' ? 'text-error-content' : 'text-amber-600 dark:text-amber-400',
          )}
        >
          {error.message}
        </span>
      )}
    </div>
  );
}
