import { useTranslationInternal } from '../core/TranslationProvider';

/**
 * Hook para obtener la función de traducción
 * Uso: const { translate, t } = useTranslation();
 */
export const useTranslation = () => {
  const { translate, t, isReady, error } = useTranslationInternal();
  return { translate, t, isReady, error };
};
