import { useState, useCallback, useEffect, useMemo } from 'react';
import { clsx } from 'clsx';
import { FieldRenderer } from './FieldRenderer';
import { isFieldLocked } from './fieldLock';
import { buildDependentLookupProps, buildDependentsByParent, isFilterValueEmpty } from './lookupFilters';
import type {
  HeaderRendererProps,
  SectionConfig,
  FieldDescriptor,
  FieldErrorMap,
  DocumentHeaderData,
  LookupFieldConfig,
} from './MasterDocument.types';

// ─── Chevron icon ──────────────────────────────────────────

function ChevronIcon({ open, className }: { open: boolean; className?: string }) {
  return (
    <svg
      className={clsx(
        'w-4 h-4 transition-transform duration-150',
        open ? 'rotate-90' : 'rotate-0',
        className,
      )}
      viewBox="0 0 20 20"
      fill="currentColor"
    >
      <path fillRule="evenodd" d="M7.21 14.77a.75.75 0 01.02-1.06L11.168 10 7.23 6.29a.75.75 0 111.04-1.08l4.5 4.25a.75.75 0 010 1.08l-4.5 4.25a.75.75 0 01-1.06-.02z" clipRule="evenodd" />
    </svg>
  );
}

// ─── Fields Grid ───────────────────────────────────────────

function FieldsGrid({
  fields,
  values,
  errors,
  onFieldChange,
  docState,
  modeForm,
  hasLines,
  gridColumns,
  lookupConfigs,
  fetcher,
  onRecordSelect,
}: {
  fields: FieldDescriptor[];
  values: DocumentHeaderData;
  errors?: FieldErrorMap;
  onFieldChange: (key: string, value: unknown) => void;
  docState: string;
  modeForm: 'create' | 'edit' | 'view';
  hasLines: boolean;
  gridColumns: 1 | 2 | 3 | 4;
  lookupConfigs?: Record<string, LookupFieldConfig>;
  fetcher?: unknown;
  onRecordSelect?: (fieldKey: string, record: Record<string, unknown> | null) => void;
}) {
  const sorted = [...fields].sort((a, b) => a.order - b.order);

  const gridClass = {
    1: 'grid-cols-1',
    2: 'grid-cols-1 sm:grid-cols-2',
    3: 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3',
    4: 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-4',
  }[gridColumns];

  return (
    <div className={clsx('grid gap-4 px-4 py-4', gridClass)}>
      {sorted.map((field) => {
        const isEditable = field.editableOn.includes(docState) && modeForm !== 'view';
        const locked = isFieldLocked(field, docState, hasLines);
        const spanClass = {
          1: '',
          2: 'sm:col-span-2',
          3: 'sm:col-span-2 lg:col-span-3',
          4: 'sm:col-span-2 lg:col-span-4',
        }[field.span];

        const isSearcher = field.control === 'searcher' || field.control === 'autocomplete';
        const lookupCfg = isSearcher ? lookupConfigs?.[field.key] : undefined;
        // Cascading lookups: resuelve cada padre contra los valores de cabecera.
        const depProps = buildDependentLookupProps(lookupCfg, (k) => values[k]);

        return (
          <div key={field.key} className={clsx(spanClass)}>
            <FieldRenderer
              fieldDef={field}
              value={values[field.key]}
              onChange={(v) => onFieldChange(field.key, v)}
              editable={isEditable}
              error={errors?.[field.key]}
              readOnly={modeForm === 'view'}
              lookupConfig={lookupCfg}
              fetcher={isSearcher ? fetcher : undefined}
              onRecordSelect={isSearcher ? (rec) => onRecordSelect?.(field.key, rec) : undefined}
              getLookupFilters={depProps?.getFilters}
              lookupDependencies={depProps?.dependencies}
              disabled={depProps?.parentMissing}
              locked={locked}
              lockTooltip={field.lockTooltip}
            />
          </div>
        );
      })}
    </div>
  );
}

// ─── Accordion Mode ────────────────────────────────────────

function AccordionSection({
  section,
  fields,
  values,
  errors,
  onFieldChange,
  docState,
  modeForm,
  hasLines,
  gridColumns,
  lookupConfigs,
  fetcher,
  onRecordSelect,
}: {
  section: SectionConfig;
  fields: FieldDescriptor[];
  values: DocumentHeaderData;
  errors?: FieldErrorMap;
  onFieldChange: (key: string, value: unknown) => void;
  docState: string;
  modeForm: 'create' | 'edit' | 'view';
  hasLines: boolean;
  gridColumns: 1 | 2 | 3 | 4;
  lookupConfigs?: Record<string, LookupFieldConfig>;
  fetcher?: unknown;
  onRecordSelect?: (fieldKey: string, record: Record<string, unknown> | null) => void;
}) {
  const [open, setOpen] = useState(section.defaultOpen);

  return (
    <div className="overflow-hidden">
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className={clsx(
          'flex items-center justify-between w-full px-4 py-3',
          'hover:bg-background-secondary transition-all duration-150',
          'dark:hover:bg-dark-bg-secondary',
          'focus:outline-hidden focus:ring-2 focus:ring-inset focus:ring-primary-400',
          'dark:focus:ring-dark-border-custom',
          open && section.accent && 'border-b-2',
        )}
        style={open && section.accent ? { borderBottomColor: section.accent } : undefined}
        aria-expanded={open}
      >
        <div className="flex items-center gap-2">
          <ChevronIcon open={open} className="text-content-secondary dark:text-dark-content-secondary" />
          <span className="text-sm font-bold text-content-primary dark:text-dark-content-primary">
            {section.label}
          </span>
          {section.subtitle && (
            <span className="text-xs text-content-secondary dark:text-dark-content-secondary">
              {section.subtitle}
            </span>
          )}
        </div>
      </button>

      {open && (
        <FieldsGrid
          fields={fields}
          values={values}
          errors={errors}
          onFieldChange={onFieldChange}
          docState={docState}
          modeForm={modeForm}
          hasLines={hasLines}
          gridColumns={gridColumns}
          lookupConfigs={lookupConfigs}
          fetcher={fetcher}
          onRecordSelect={onRecordSelect}
        />
      )}
    </div>
  );
}

// ─── Tabs Mode ─────────────────────────────────────────────

function TabsRenderer({
  sections,
  fieldsBySection,
  values,
  errors,
  onFieldChange,
  docState,
  modeForm,
  hasLines,
  gridColumns,
  lookupConfigs,
  fetcher,
  onRecordSelect,
}: {
  sections: SectionConfig[];
  fieldsBySection: Record<string, FieldDescriptor[]>;
  values: DocumentHeaderData;
  errors?: FieldErrorMap;
  onFieldChange: (key: string, value: unknown) => void;
  docState: string;
  modeForm: 'create' | 'edit' | 'view';
  hasLines: boolean;
  gridColumns: 1 | 2 | 3 | 4;
  lookupConfigs?: Record<string, LookupFieldConfig>;
  fetcher?: unknown;
  onRecordSelect?: (fieldKey: string, record: Record<string, unknown> | null) => void;
}) {
  const [activeTab, setActiveTab] = useState(sections[0]?.key ?? '');

  useEffect(() => {
    if (sections.length > 0 && !sections.find((s) => s.key === activeTab)) {
      setActiveTab(sections[0].key);
    }
  }, [sections, activeTab]);

  const activeSection = sections.find((s) => s.key === activeTab);
  const activeFields = fieldsBySection[activeTab] ?? [];

  return (
    <div>
      <div className="flex border-b border-border-secondary dark:border-dark-border-primary overflow-x-auto" role="tablist" aria-label="Secciones del encabezado">
        {sections.map((section) => {
          const isActive = section.key === activeTab;
          return (
            <button
              key={section.key}
              type="button"
              role="tab"
              aria-selected={isActive}
              onClick={() => setActiveTab(section.key)}
              className={clsx(
                'px-4 py-2.5 text-sm font-semibold whitespace-nowrap transition-all duration-150 shrink-0',
                'focus:outline-hidden focus:ring-2 focus:ring-inset focus:ring-primary-400',
                'dark:focus:ring-dark-border-custom',
                isActive
                  ? [
                      'text-content-primary bg-bg-primary dark:text-dark-content-primary dark:bg-dark-bg-primary',
                      'border-b-2',
                      activeSection?.accent ? '' : 'border-primary-600 dark:border-primary-400',
                    ]
                  : 'text-content-secondary bg-background-secondary hover:text-content-tertiary dark:text-dark-content-secondary dark:bg-dark-bg-secondary dark:hover:text-dark-content-primary',
              )}
              style={isActive && activeSection?.accent ? { borderBottomColor: activeSection.accent } : undefined}
            >
              {section.label}
            </button>
          );
        })}
      </div>

      <FieldsGrid
        fields={activeFields}
        values={values}
        errors={errors}
        onFieldChange={onFieldChange}
        docState={docState}
        modeForm={modeForm}
        hasLines={hasLines}
        gridColumns={gridColumns}
        lookupConfigs={lookupConfigs}
        fetcher={fetcher}
        onRecordSelect={onRecordSelect}
      />
    </div>
  );
}

// ─── HeaderRenderer ────────────────────────────────────────

/**
 * Renderizador del encabezado del documento maestro.
 *
 * Soporta dos modos de visualización: `accordion` (secciones colapsables)
 * y `tabs` (pestañas horizontales). Cada sección agrupa campos renderizados
 * por `FieldRenderer` en un grid responsivo configurable.
 *
 * @see docs/colors.md - Sistema de tokens de color
 * @see MasterDocument.types - HeaderRendererProps, SectionConfig
 *
 * @example
 * ```tsx
 * <HeaderRenderer
 *   mode="accordion"
 *   columns={3}
 *   sections={[{ key: 'general', label: 'Información general', defaultOpen: true }]}
 *   fieldsBySection={{ general: fields }}
 *   values={headerData}
 *   onFieldChange={(key, value) => updateHeader(key, value)}
 *   docState="DRAFT"
 *   mode_form="edit"
 * />
 * ```
 */
export function HeaderRenderer({
  mode,
  columns,
  sections,
  fieldsBySection,
  values,
  errors,
  onFieldChange,
  docState,
  mode_form,
  hasLines = false,
  className,
  lookupConfigs,
  fetcher,
  onRecordSelect,
}: HeaderRendererProps) {
  // Mapa padre → dependientes para limpiar el dependiente al cambiar un padre.
  const dependentsByParent = useMemo(
    () => buildDependentsByParent(lookupConfigs),
    [lookupConfigs],
  );

  const handleFieldChange = useCallback(
    (key: string, value: unknown) => {
      onFieldChange(key, value);
      // Al cambiar un padre, resetea los searchers dependientes (sólo si tienen
      // valor) para no dejar un valor inválido del padre anterior. Sólo ocurre en
      // cambios del usuario, no en la carga programática (get-by-id).
      const dependents = dependentsByParent[key];
      if (dependents) {
        dependents.forEach((depKey) => {
          if (!isFilterValueEmpty(values[depKey])) onFieldChange(depKey, null);
        });
      }
    },
    [onFieldChange, dependentsByParent, values],
  );

  // Errores cuya key no coincide con ningún campo → banner form-level
  const allFieldKeys = new Set(
    Object.values(fieldsBySection).flat().map((f) => f.key),
  );
  const formLevelErrors = errors
    ? Object.entries(errors).filter(([key]) => !allFieldKeys.has(key))
    : [];

  return (
    <div
      className={clsx(
        'bg-bg-primary rounded-xl shadow-[0_1px_3px_rgba(60,64,67,.15),0_1px_2px_rgba(60,64,67,.10)]',
        'dark:bg-dark-bg-primary dark:shadow-none dark:border dark:border-dark-border-primary',
        className,
      )}
    >
      {formLevelErrors.length > 0 && (
        <div
          role="alert"
          className="mx-4 mt-4 rounded-md border border-red-200 bg-red-50 px-4 py-3 dark:border-red-800 dark:bg-red-950/20"
        >
          {formLevelErrors.map(([key, err]) => (
            <p key={key} className="text-sm text-red-700 dark:text-red-400">
              {err.message}
            </p>
          ))}
        </div>
      )}
      {mode === 'accordion' ? (
        sections.map((section) => (
          <AccordionSection
            key={section.key}
            section={section}
            fields={fieldsBySection[section.key] ?? []}
            values={values}
            errors={errors}
            onFieldChange={handleFieldChange}
            docState={docState}
            modeForm={mode_form}
            hasLines={hasLines}
            gridColumns={columns}
            lookupConfigs={lookupConfigs}
            fetcher={fetcher}
            onRecordSelect={onRecordSelect}
          />
        ))
      ) : (
        <TabsRenderer
          sections={sections}
          fieldsBySection={fieldsBySection}
          values={values}
          errors={errors}
          onFieldChange={handleFieldChange}
          docState={docState}
          modeForm={mode_form}
          hasLines={hasLines}
          gridColumns={columns}
          lookupConfigs={lookupConfigs}
          fetcher={fetcher}
          onRecordSelect={onRecordSelect}
        />
      )}
    </div>
  );
}
