import React, { useState, useMemo, useEffect } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { LayoutTemplate, Loader2, Layers, Columns, Trash2, AlertTriangle, Pencil } from 'lucide-react';
import { useWidgetEngine } from './hooks/useWidgetEngine';
import { useDashboardLayout } from './hooks/useDashboardLayout';
import { DashboardGrid } from './DashboardGrid';
import { WidgetManagerPanel } from './components/WidgetManagerPanel';
import { CustomizationWithSchema } from './components/WidgetCustomizationPanel';
import { findFirstAvailablePosition } from '../components/DashboardEngine/utils/gridEngine';
import { deleteWidget as deleteWidgetAPI } from './api/dashboardCatalog';
import type { DashboardPeriod, WidgetDefinition, UserWidgetPreference, DashboardFetcher } from './types';
import { LazyWidget } from './components/LazyWidget';
import type { WidgetRegistry } from './components/LazyWidget';
import { DashboardProvider, useDashboardContext } from './DashboardContext';

interface DashboardPageProps {
  /** Fetcher del host con autenticación y headers incluidos. */
  fetcher: DashboardFetcher;
  /** ID del usuario autenticado (del JWT del host). */
  userId: string;
  /** Roles del usuario autenticado (del JWT del host). */
  userRoles: string[];
  /** Muestra el selector de periodo (Hoy/Semana/Mes). Default false. */
  showPeriodSelector?: boolean;
  /** Permite crear widgets con endpoints externos en el Builder. Default false. */
  showExternalEndpoints?: boolean;
  /** Registro custom del host: mapea widget_id → componente React para widgets específicos. */
  customWidgetRegistry?: WidgetRegistry;
  /** Orden preferido de categorías en la vista cascada. Las no listadas van al final alfabéticamente. */
  categoryOrder?: string[];
}

export const DashboardPage: React.FC<DashboardPageProps> = ({
  fetcher,
  userId,
  userRoles,
  showPeriodSelector = false,
  showExternalEndpoints = false,
  customWidgetRegistry,
  categoryOrder,
}) => {
  // 1. Motor Global (Catálogo, Perfil, Filtros)
  const engine = useWidgetEngine({ userId, userRoles, fetcher });

  // 2. Layout Local (Sincronizado con BD vía Debounce)
  const layoutManager = useDashboardLayout({
    userId,
    initialLayout: engine.initialLayout,
    period: engine.period,
    fetcher,
  });

  const [isManagerOpen, setIsManagerOpen] = useState(false);
  const [customizingWidget, setCustomizingWidget] = useState<{
    widget: WidgetDefinition;
    preference?: UserWidgetPreference;
  } | null>(null);
  const [viewMode, setViewMode] = useState<'cascade' | 'tabs'>('cascade');
  const [activeTab, setActiveTab] = useState<string>('Ventas');
  const [pendingRemoveId, setPendingRemoveId] = useState<string | null>(null);

  // --- Lógica de Agrupación por Categorías ---
  const layoutByCategory = useMemo(() => {
    const groups: Record<string, UserWidgetPreference[]> = {};
    
    layoutManager.layout.forEach(pref => {
      const def = engine.catalog.find(c => c.widget_id === pref.widget_id);
      if (def) {
        const cat = def.categoria || 'Otros';
        if (!groups[cat]) groups[cat] = [];
        groups[cat].push(pref);
      }
    });
    
    return groups;
  }, [layoutManager.layout, engine.catalog]);

  const sortedCategories = useMemo(() => {
    const categories = Object.keys(layoutByCategory);
    const prioritized = (categoryOrder ?? ['Ventas', 'Compras', 'Inventario']).filter(c => categories.includes(c));
    categories.sort().forEach(c => { if (!prioritized.includes(c)) prioritized.push(c); });
    return prioritized;
  }, [layoutByCategory, categoryOrder]);

  // Categorías únicas del catálogo completo (para el panel de personalización)
  const catalogCategories = useMemo(() =>
    [...new Set(engine.catalog.map(w => w.categoria).filter(Boolean))].sort(),
    [engine.catalog]
  );

  useEffect(() => {
    if (sortedCategories.length > 0 && !sortedCategories.includes(activeTab)) {
      setActiveTab(sortedCategories[0]);
    }
  }, [sortedCategories, activeTab]);

  const handleCategoryLayoutChange = (category: string, newCategoryLayout: UserWidgetPreference[]) => {
    const otherCategoriesLayout = layoutManager.layout.filter(pref => {
      const def = engine.catalog.find(c => c.widget_id === pref.widget_id);
      const cat = def ? (def.categoria || 'Otros') : 'Otros';
      return cat !== category;
    });
    layoutManager.updateLayout([...otherCategoriesLayout, ...newCategoryLayout]);
  };

  // Manejador para quitar un widget — solicita confirmación antes de eliminar
  const handleRemoveWidget = (instanceId: string) => {
    setPendingRemoveId(instanceId);
  };

  const confirmRemove = () => {
    if (pendingRemoveId) {
      layoutManager.updateLayout(layoutManager.layout.filter(w => w.id !== pendingRemoveId));
      setPendingRemoveId(null);
    }
  };


  if (engine.isLoading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-[#F4F6F8]">
        <Loader2 className="w-8 h-8 text-blue-600 animate-spin mb-4" />
        <p className="text-gray-600 font-medium">Cargando perfil comercial...</p>
      </div>
    );
  }

  if (engine.initError) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-[#F4F6F8] p-8">
        <AlertTriangle className="w-12 h-12 text-red-400 mb-4" />
        <h2 className="text-lg font-semibold text-gray-800 mb-2">No se pudo cargar el dashboard</h2>
        <p className="text-sm text-gray-500 text-center max-w-md">{engine.initError}</p>
        <button
          onClick={() => window.location.reload()}
          className="mt-6 px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700"
        >
          Reintentar
        </button>
      </div>
    );
  }

  return (
    <DashboardProvider fetcher={fetcher}>
    <div className="min-h-screen bg-[#F4F6F8] text-[#1A202C] overflow-x-hidden relative">
      {/* 1. Topbar Estricta según PRD */}
      <header className="sticky top-0 z-40 bg-white border-b border-[#E2E8F0] shadow-sm h-[64px] px-6 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
            <LayoutTemplate className="w-5 h-5 text-white" />
          </div>
          <h1 className="text-xl font-bold tracking-tight">Dashboard Comercial</h1>
          
          {layoutManager.isSaving && (
            <span className="ml-4 flex items-center gap-1.5 text-xs font-medium text-gray-500 bg-gray-100 px-2 py-1 rounded-full">
              <Loader2 className="w-3 h-3 animate-spin" /> Guardando...
            </span>
          )}
        </div>

        <div className="flex items-center gap-4">
          {/* Selector de Vista (Cascada vs Tabs) */}
          <div className="flex items-center bg-gray-100 p-1 rounded-lg">
            <button 
              onClick={() => setViewMode('cascade')} 
              className={`p-1.5 rounded transition-all ${viewMode === 'cascade' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
              title="Vista Cascada"
            >
              <Layers className="w-4 h-4" />
            </button>
            <button 
              onClick={() => setViewMode('tabs')} 
              className={`p-1.5 rounded transition-all ${viewMode === 'tabs' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
              title="Vista Pestañas"
            >
              <Columns className="w-4 h-4" />
            </button>
          </div>

          <div className="w-px h-8 bg-gray-200 mx-1"></div>

          {/* Selector de Tiempo (Filtro Global) */}
          {showPeriodSelector && (
            <div className="bg-gray-100 p-1 rounded-lg flex items-center">
              {(['Hoy', 'Semana', 'Mes'] as DashboardPeriod[]).map(p => (
                <button
                  key={p}
                  onClick={() => engine.setPeriod(p)}
                  className={`px-4 py-1.5 text-sm font-medium rounded-md transition-all ${
                    engine.period === p
                      ? 'bg-white text-blue-600 shadow-sm'
                      : 'text-gray-500 hover:text-gray-700'
                  }`}
                >
                  {p}
                </button>
              ))}
            </div>
          )}

          <div className="w-px h-8 bg-gray-200 mx-2"></div>

          {/* Botón Editar — abre sidebar (= activa edit mode) */}
          <button
            onClick={() => setIsManagerOpen(true)}
            className={`
              flex items-center gap-2 px-4 py-2 rounded-lg font-semibold text-sm transition-colors
              ${isManagerOpen
                ? 'bg-blue-600 text-white hover:bg-blue-700'
                : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-50'}
            `}
          >
            <Pencil className="w-4 h-4" /> Editar
          </button>
        </div>
      </header>

      {/* Banner de Modo Edición — visible cuando el sidebar está abierto */}
      {isManagerOpen && (
        <div className="bg-blue-50 border-b border-blue-200 px-6 py-2 flex items-center justify-center">
          <p className="text-sm font-medium text-blue-800">
            Modo edición activo — arrastra y redimensiona los widgets. Cierra el panel para salir.
          </p>
        </div>
      )}

      {/* Menú de Pestañas (SubHeader) */}
      {viewMode === 'tabs' && sortedCategories.length > 0 && (
        <div className="px-6 pt-4 bg-white border-b border-gray-200 flex gap-6">
          {sortedCategories.map(cat => (
            <button
              key={cat}
              onClick={() => setActiveTab(cat)}
              className={`pb-3 font-bold text-sm tracking-wide transition-colors border-b-2 ${
                activeTab === cat 
                  ? 'border-blue-600 text-blue-600' 
                  : 'border-transparent text-gray-500 hover:text-gray-800'
              }`}
            >
              {cat.toUpperCase()}
            </button>
          ))}
        </div>
      )}

      {/* 2. Contenido Principal (Grid) */}
      <main className={`p-6 transition-all duration-300 ${isManagerOpen ? 'mr-[348px]' : ''}`}>
        {sortedCategories.map(category => {
          // Si estamos en modo tabs y no es la activa, no renderizamos su grid
          if (viewMode === 'tabs' && category !== activeTab) return null;

          const categoryLayout = layoutByCategory[category];

          return (
            <div key={category} className="mb-10">
              {viewMode === 'cascade' && (
                <h2 className="text-sm font-bold text-blue-600 mb-4 uppercase tracking-wider pl-3 border-l-4 border-blue-600 flex items-center gap-2">
                  <span className="text-gray-400 font-normal">|</span> {category}
                </h2>
              )}
              
              <DashboardGrid
                layout={categoryLayout}
                catalog={engine.catalog}
                isEditMode={isManagerOpen}
                globalFilters={{ period: engine.period }}
                onLayoutChange={(newLayout) => handleCategoryLayoutChange(category, newLayout)}
                onRemoveWidget={handleRemoveWidget}
                renderWidget={(pref, def, editMode, filters, onRemove) => (
                  <LazyWidget
                    preference={pref}
                    definition={def}
                    isEditMode={editMode}
                    period={filters.period as DashboardPeriod}
                    onRemove={onRemove}
                    customWidgetRegistry={customWidgetRegistry}
                  />
                )}
              />
            </div>
          );
        })}

        {sortedCategories.length === 0 && (
          <div className="flex flex-col items-center justify-center text-gray-500 mt-20 p-8 bg-white border border-dashed rounded-xl max-w-md mx-auto">
            <LayoutTemplate className="w-12 h-12 text-gray-300 mb-4" />
            <h3 className="font-semibold text-gray-700 mb-1">Dashboard Vacío</h3>
            <p className="text-center text-sm">No tienes widgets agregados a tu pantalla. Haz clic en "Personalizar" para configurar tu vista.</p>
          </div>
        )}
      </main>

      {/* 3. Panel Lateral (Catálogo) */}
      <WidgetManagerPanel
        isOpen={isManagerOpen}
        catalog={engine.catalog}
        currentLayout={layoutManager.layout}
        isAdmin={userRoles.some(r => r.toLowerCase() === 'admin')}
        userId={userId}
        showExternalEndpoints={showExternalEndpoints}
        onClose={() => setIsManagerOpen(false)}
        onRequestAdd={(widget) => {
          setCustomizingWidget({ widget, preference: undefined });
          setIsManagerOpen(false);
        }}
        onRequestModify={(widget, preference) => {
          setCustomizingWidget({ widget, preference });
          setIsManagerOpen(false);
        }}
        onRemoveWidget={handleRemoveWidget}
        onWidgetCreated={(newDef) => {
          engine.addToCatalog(newDef);
          // Si es privado, agregar directamente al layout del usuario
          if (newDef.es_privado) {
            const pos = findFirstAvailablePosition(
              layoutByCategory[newDef.categoria] ?? [],
              newDef.cols_default,
              newDef.altura_default
            );
            layoutManager.updateLayout([...layoutManager.layout, {
              id: `inst_${crypto.randomUUID()}`,
              user_id: userId,
              widget_id: newDef.widget_id,
              activo: true,
              orden: layoutManager.layout.length + 1,
              col_span: newDef.cols_default,
              row_span: newDef.altura_default,
              pos_x: pos.x,
              pos_y: pos.y,
              modificado_en: new Date().toISOString(),
            }]);
          }
        }}
        onWidgetUpdated={(updatedDef) => {
          engine.updateInCatalog(updatedDef);
        }}
        onDeleteWidget={async (widgetId) => {
          await deleteWidgetAPI(widgetId, fetcher);
          engine.removeFromCatalog(widgetId);
          const cleaned = layoutManager.layout.filter(p => p.widget_id !== widgetId);
          if (cleaned.length !== layoutManager.layout.length) {
            layoutManager.updateLayout(cleaned);
          }
        }}
      />

      {/* 4. Panel de Personalización unificado (agregar o modificar) */}
      {customizingWidget && (
        <CustomizationWithSchema
          widget={customizingWidget.widget}
          preference={customizingWidget.preference}
          availableCategories={catalogCategories}
          period={engine.period}
          onConfirm={(overrides) => {
            if (customizingWidget.preference) {
              // Modo personalize: actualizar config_json de la preferencia existente
              const updated = layoutManager.layout.map(p =>
                p.id === customizingWidget.preference!.id
                  ? { ...p, config_json: Object.keys(overrides).length > 0 ? overrides : undefined }
                  : p
              );
              layoutManager.updateLayout(updated);
              setCustomizingWidget(null);
            } else {
              // Modo add: crear nueva instancia en el layout
              const def = customizingWidget.widget;
              const cols = (overrides.cols_default as number) ?? def.cols_default;
              const pos = findFirstAvailablePosition(
                layoutByCategory[def.categoria] ?? [],
                cols,
                def.altura_default
              );
              layoutManager.updateLayout([...layoutManager.layout, {
                id: `inst_${crypto.randomUUID()}`,
                user_id: userId,
                widget_id: def.widget_id,
                activo: true,
                orden: layoutManager.layout.length + 1,
                col_span: cols,
                row_span: def.altura_default,
                pos_x: pos.x,
                pos_y: pos.y,
                config_json: Object.keys(overrides).length > 0 ? overrides : undefined,
                modificado_en: new Date().toISOString(),
              }]);
              setCustomizingWidget(null);
              setIsManagerOpen(true);   // volver al catálogo para seguir agregando
            }
          }}
          onRestore={customizingWidget.preference ? () => {
            const restored = layoutManager.layout.map(p =>
              p.id === customizingWidget.preference!.id
                ? { ...p, config_json: undefined }
                : p
            );
            layoutManager.updateLayout(restored);
            setCustomizingWidget(null);
          } : undefined}
          onClose={() => {
            const wasAdd = !customizingWidget.preference;
            setCustomizingWidget(null);
            if (wasAdd) setIsManagerOpen(true);  // volver al catálogo si era modo add
          }}
        />
      )}

      {/* 5. Dialog de Confirmación — Eliminar Widget */}
      {pendingRemoveId && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-gray-900/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm p-6 animate-in fade-in zoom-in duration-150">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 rounded-full bg-red-100 flex items-center justify-center flex-shrink-0">
                <AlertTriangle className="w-5 h-5 text-red-600" />
              </div>
              <div>
                <h3 className="font-semibold text-gray-900">Quitar widget</h3>
                <p className="text-sm text-gray-500">Esta acción no se puede deshacer desde el grid.</p>
              </div>
            </div>
            <p className="text-sm text-gray-600 mb-6">
              ¿Confirmas que quieres quitar este widget de tu dashboard? Podrás volver a agregarlo desde el catálogo.
            </p>
            <div className="flex items-center justify-end gap-3">
              <button
                onClick={() => setPendingRemoveId(null)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 hover:bg-gray-200 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button
                onClick={confirmRemove}
                className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-red-600 hover:bg-red-700 rounded-lg transition-colors"
              >
                <Trash2 className="w-4 h-4" />
                Quitar widget
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
    </DashboardProvider>
  );
};

