import React from 'react';
import { Table } from '../Table/Table';
import { Button } from '../Button/Button';
import { Dropdown } from '../Dropdown/Dropdown';
import { Checkbox } from '../Checkbox/Checkbox';
import type { TableColumn } from '../Table/Table.types';
import type { MasterCrudTableProps, MasterCrudField } from './MasterCrud.types';
import { Bars3Icon } from './icons';

/**
 * MasterCrudTable - Adaptador de tabla para MasterCrud
 */
export const MasterCrudTable = <T extends Record<string, any>>({
  fields,
  data,
  loading = false,
  emptyMessage,
  onSort,
  sortColumn,
  sortDirection,
  pagination,
  showRowActions = true,
  actions = [],
  rowActions,
  className = '',
  locale = 'es',
  enableMultiSelect = false,
  selectedIds = [],
  onSelectionChange,
  t,
}: MasterCrudTableProps<T>) => {
  const finalEmptyMessage = emptyMessage || t('empty', 'No hay registros disponibles');
  // ===== CONVERTIR FIELDS A COLUMNS =====
  const columns: TableColumn<T>[] = fields
    .filter((field) => {
      if (field.config?.showInList !== undefined) return field.config.showInList;
      if (field.config?.visibleInTable !== undefined) return field.config.visibleInTable;
      return true;
    })
    .map((field) => ({
      header: t(field.accessorKey as string, field.header),
      accessor: field.accessorKey as keyof T,
      sortable: field.config?.sortable ?? false,
      align: field.config?.align ?? 'left',
      width: field.config?.columnWidth,
      render: field.renderCell
        ? (value: any, row: T, index: number) => field.renderCell!(value, row, index)
        : (value: any) => renderCellByType(value, field),
    }));

  // ===== AGREGAR COLUMNA DE SELECCIÓN =====
  if (enableMultiSelect) {
    columns.unshift({
      header: (
        <Checkbox
          checked={data.length > 0 && selectedIds.length === data.length}
          onChange={(e) => {
            if (e.target.checked) {
              onSelectionChange?.(data.map((r: any) => r.id || r.Id || r.codigo));
            } else {
              onSelectionChange?.([]);
            }
          }}
          aria-label={t('selectAll', 'Seleccionar todos')}
        />
      ),
      accessor: (() => null) as any,
      align: 'center',
      width: '100px', // Aumentado para visibilidad completa
      render: (_: any, row: T) => {
        const id = row.id || row.Id || row.codigo;
        const isSelected = selectedIds.includes(id);
        return (
          <div className="flex justify-center items-center">
            <Checkbox
              checked={isSelected}
              onChange={(e) => {
                if (e.target.checked) {
                  onSelectionChange?.([...selectedIds, id]);
                } else {
                  onSelectionChange?.(selectedIds.filter(item => item !== id));
                }
              }}
              aria-label={t('selectRecord', 'Seleccionar registro')}
            />
          </div>
        );
      },
    });
  }

  // ===== AGREGAR COLUMNA DE ACCIONES =====
  if (showRowActions) {
    columns.push({
      header: t('actions', 'Acciones'),
      accessor: (() => null) as any,
      align: 'center',
      stickyRight: true,
      width: '180px',
      render: (_: any, row: T, index: number) => {
        // 1. Clasificar acciones: 
        // - Editar/Eliminar/Vincular son 'core' y se intentan mostrar siempre.
        // - Se permiten hasta 2 acciones adicionales directas. El resto va al menú.
        
        const coreActions = actions.filter(a => a.id === 'edit' || a.id === 'delete' || a.id === 'link');
        const otherActions = actions.filter(a => a.id !== 'edit' && a.id !== 'desc' && a.id !== 'delete' && a.id !== 'link');

        // Las primeras 2 acciones "adicionales" que pidan ser directas (o por defecto) se quedan fuera.
        const directOtherActions = otherActions.slice(0, 2);
        const menuActions = otherActions.slice(2);

        const allDirectActions = [...coreActions, ...directOtherActions];

        // Filtrar acciones visibles
        const directActions = allDirectActions.filter(action => {
          if (typeof action.visible === 'function') return action.visible(row);
          return action.visible !== false;
        });

        const dropdownItems = menuActions
          .filter(action => {
            if (typeof action.visible === 'function') return action.visible(row);
            return action.visible !== false;
          })
          .map((action) => {
            const isDisabled = typeof action.disabled === 'function' ? action.disabled(row) : action.disabled;
          const actionName = typeof action.name === 'function' ? action.name(row) : action.name;
          const actionIcon = typeof action.icon === 'function' ? action.icon(row) : action.icon;
          
          return {
            children: actionName,
            icon: actionIcon,
            disabled: isDisabled,
            onClick: () => action.action?.(row),
            className: action.id === 'delete' || actionName.toLowerCase().includes('eliminar') || actionName.toLowerCase().includes('delete')
              ? 'text-error-content hover:text-error-content dark:text-error-content'
              : '',
          };
        });
        
        return (
          <div className="flex items-center justify-center gap-2 py-1.5">
            {/* Acciones personalizadas legacy */}
            {rowActions && rowActions(row, index)}

            {/* Acciones directas (Editar, Eliminar, Vincular y hasta 2 adicionales) */}
            {directActions.map((action) => {
              const actionName = typeof action.name === 'function' ? action.name(row) : action.name;
              const actionIcon = typeof action.icon === 'function' ? action.icon(row) : action.icon;
              const isDelete = action.id === 'delete' || actionName.toLowerCase().includes('eliminar') || actionName.toLowerCase().includes('delete');
              
              return (
                <Button
                  key={action.id || actionName}
                  type="outline"
                  size="base"
                  iconOnly
                  leftIcon={actionIcon}
                  ariaLabel={actionName}
                  title={actionName} // Tooltip nativo
                  onClick={() => action.action?.(row)}
                  className={`shrink-0 ${isDelete
                    ? 'text-error-content hover:text-error-content border-error-content hover:border-error-content'
                    : ''
                  }`}
                  disabled={typeof action.disabled === 'function' ? action.disabled(row) : action.disabled}
                />
              );
            })}

            {/* Dropdown de Más Opciones */}
            {dropdownItems.length > 0 && (
              <div className="shrink-0">
                <Dropdown
                  menuClassName="w-48"
                  renderTrigger={() => (
                    <Button 
                      type="outline" 
                      size="base" 
                      iconOnly 
                      leftIcon={<Bars3Icon />} 
                      ariaLabel={t('moreOptions', 'Más opciones')} 
                    />
                  )}
                  items={dropdownItems}
                />
              </div>
            )}
          </div>
        );
      },
    });
  }

  const renderCellByType = (value: any, field: MasterCrudField<T>): React.ReactNode => {
    if (value === null || value === undefined) return <span className="text-content-tertiary dark:text-content-tertiary">—</span>;
    switch (field.type) {
      case 'boolean': {
        const trueLabel = field.config?.trueLabel || t('active', 'Activo');
        const falseLabel = field.config?.falseLabel || t('inactive', 'Inactivo');
        return (
          <span className={`inline-flex items-center px-2 py-0.5 rounded-md text-xs font-bold ${value ? 'bg-lime-100 text-lime-700 dark:bg-lime-900/30 dark:text-lime-400' : 'bg-zinc-100 text-zinc-600 dark:bg-zinc-800/30 dark:text-zinc-400'}`}>
            {value ? trueLabel : falseLabel}
          </span>
        );
      }
      case 'date': try { return new Date(value).toLocaleDateString(locale, { year: 'numeric', month: '2-digit', day: '2-digit' }); } catch { return String(value); }
      case 'number': return <span className="tabular-nums">{typeof value === 'number' ? value.toLocaleString(locale) : value}</span>;
      case 'select': return field.options?.find((opt) => opt.value === value)?.label ?? String(value);
      case 'email': return <a href={`mailto:${value}`} className="text-primary-600 hover:underline dark:text-primary-600">{value}</a>;
      case 'lookup': if (field.lookupConfig && typeof value === 'object' && value !== null) { return field.lookupConfig.displayFields.map(k => (value as any)[k]).filter(v => v !== undefined && v !== null).join(' - ') || String(value); } return String(value);
      default: return String(value);
    }
  };

  const handleSort = (column: keyof T | string, direction: 'asc' | 'desc' | null) => { if (onSort) onSort(String(column), direction); };

  return (
    <Table
      columns={columns} data={data} loading={loading} emptyMessage={finalEmptyMessage}
      variant="basic" showBorder={false} showShadow={false} showPadding={false} fullWidth
      onSort={handleSort} sortColumn={sortColumn} sortDirection={sortDirection}
      pagination={pagination} className={`${className} !bg-transparent !shadow-none !rounded-none !p-0`}
      isRowSelected={(row) => {
        const id = row.id || row.Id || row.codigo;
        return selectedIds.includes(id);
      }}
    />
  );
};
