/**
 * EmptyState — renders pre-search and post-search empty state variants.
 *
 * Pre-search  : nodata illustration + search icon + "Ingresa criterios y presiona Buscar"
 * Post-search : nodata illustration + info icon  + "Sin resultados"
 *
 * Visual design matches the HTML mocks (input-specs/Mocks).
 *
 * @module components/list/EmptyState
 * @see FMPV-MVWC-E002-S004 I-004
 */
import React from 'react';
import nodataImg from '../../assets/nodata.svg';

export interface EmptyStateProps {
  hasSearched: boolean;
  /**
   * compact=true: removes outer padding — for use inside siesa-ui-kit Table whose
   * empty-state wrapper already provides py-12 (48px) spacing on each side.
   */
  compact?: boolean;
}

export function EmptyState({ hasSearched, compact = false }: EmptyStateProps) {
  return (
    <div
      data-testid={hasSearched ? 'empty-state-post-search' : 'empty-state-pre-search'}
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: 16,
        padding: compact ? 0 : '48px 40px',
      }}
    >
      {/* Shared illustration */}
      <img
        src={nodataImg}
        alt={hasSearched ? 'Sin resultados' : 'Ingresa criterios'}
        style={{ width: 180, height: 180, objectFit: 'contain' }}
      />

      {/* Alert box */}
      <div
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          gap: 10,
          background: '#dbeefe',
          border: '1px solid #93d1fd',
          borderRadius: 8,
          padding: '14px 16px',
          maxWidth: 420,
          width: '100%',
        }}
      >
        {/* Icon */}
        {hasSearched ? (
          /* Info circle */
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width={20}
            height={20}
            fill="none"
            viewBox="0 0 24 24"
            stroke="#0e79fd"
            strokeWidth={1.5}
            style={{ flexShrink: 0, marginTop: 1 }}
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M11.25 11.25l.041-.02a.75.75 0 011.063.852l-.708 2.836a.75.75 0 001.063.853l.041-.021M21 12a9 9 0 11-18 0 9 9 0 0118 0zm-9-3.75h.008v.008H12V8.25z"
            />
          </svg>
        ) : (
          /* Search / magnifying glass */
          <svg
            width={18}
            height={18}
            fill="none"
            stroke="#0e79fd"
            strokeWidth={2}
            viewBox="0 0 24 24"
            style={{ flexShrink: 0, marginTop: 1 }}
          >
            <circle cx={11} cy={11} r={8} />
            <path d="m21 21-4.35-4.35" />
          </svg>
        )}

        {/* Text */}
        <div>
          <strong style={{ display: 'block', fontSize: 14, color: '#0e79fd' }}>
            {hasSearched ? 'Sin resultados' : 'Ingresa criterios y presiona Buscar'}
          </strong>
          <span style={{ display: 'block', fontSize: 12, color: '#1355b7', marginTop: 2 }}>
            {hasSearched
              ? 'No hay registros que coincidan con los filtros.'
              : 'Usa los filtros del panel superior para encontrar registros.'}
          </span>
        </div>
      </div>
    </div>
  );
}
