/**
 * PaginationBar — uses siesa-ui-kit Pagination component for page navigation.
 * Left: page buttons (Pagination). Right: range info + optional page-size Select.
 *
 * @module components/list/PaginationBar
 * @see FMPV-MVWC-E002-S004 I-002
 */
import React from 'react';
import { Pagination } from '../../../Pagination/Pagination';
import { Select } from '../../../Select/Select';

export interface PaginationBarProps {
  currentPage: number;
  totalPages: number;
  totalRecords: number;
  pageSize: number;
  pageSizeOptions: number[];
  onPageChange: (page: number) => void;
  onPageSizeChange: (pageSize: number) => void;
}

export function PaginationBar({
  currentPage,
  totalPages,
  totalRecords,
  pageSize,
  pageSizeOptions,
  onPageChange,
  onPageSizeChange,
}: PaginationBarProps) {
  const start = totalRecords === 0 ? 0 : (currentPage - 1) * pageSize + 1;
  const end = Math.min(currentPage * pageSize, totalRecords);

  const sizeOptions = pageSizeOptions.map((n) => ({ value: n, label: String(n) }));

  return (
    <div className="flex items-center justify-between gap-4 px-4 py-2 border-t border-border-primary dark:border-dark-border-primary">
      {/* Left: siesa-ui-kit Pagination (numbered page buttons + prev/next) */}
      <Pagination
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={onPageChange}
        siblingCount={1}
        backText="Ant."
        nextText="Sig."
        data-testid="pagination"
      />

      {/* Right: range info + page-size selector */}
      <div className="flex items-center gap-3 flex-shrink-0">
        <span className="text-sm text-content-tertiary dark:text-dark-content-tertiary whitespace-nowrap">
          {start}–{end} / {totalRecords}
        </span>
        <Select
          showLabel={false}
          showDescription={false}
          options={sizeOptions}
          value={pageSize}
          onChange={(v: string | number) => onPageSizeChange(Number(v))}
          selectSize="sm"
        />
      </div>
    </div>
  );
}
