/**
 * Paleta de colores centralizada para todos los widgets de gráficas del dashboard.
 * Usar DEFAULT_CHART_COLORS para la mayoría de los casos.
 * Reemplaza los arrays hardcodeados dispersos en ChartLine, ChartVentasMensual,
 * ChartBarHorizontal, ChartDonut y FieldMappingPanel.
 */

export const CHART_COLORS = {
  /** Azules — paleta principal para series y barras */
  primary:   ['#3182CE', '#90CDF4', '#2B6CB0', '#63B3ED', '#4299E1'],
  /** Líneas — mayor contraste para series temporales */
  lines:     ['#0066FF', '#F59E0B', '#10B981', '#EF4444', '#8B5CF6'],
  /** Verde esmeralda — para indicadores positivos */
  emerald:   ['#38A169', '#9AE6B4', '#276749', '#68D391', '#48BB78'],
  /** Cálidos — para distribuciones y donuts */
  warm:      ['#DD6B20', '#FBD38D', '#C05621', '#F6AD55', '#ED8936'],
};

/** Paleta por defecto para barras (horizontales y verticales) */
export const DEFAULT_CHART_COLORS = CHART_COLORS.primary;

/** Paleta para gráficas de líneas (mayor contraste entre series) */
export const LINE_CHART_COLORS = CHART_COLORS.lines;

/** Colores para chips de campos en FieldMappingPanel */
export const FIELD_MAPPING_COLORS = CHART_COLORS.primary;
