/** Diccionarios de respaldo por idioma, listos para registrar en el host si se desea. */
export const FINANCIAL_INSTRUMENT_TRANSLATIONS = {
  es: FINANCIAL_INSTRUMENT_TRANSLATIONS_ES,
  en: FINANCIAL_INSTRUMENT_TRANSLATIONS_EN,
} as const;

/** Función de traducción con interpolación `{var}`. */
export type FinancialInstrumentT = (key: string, vars?: Record<string, string | number>) => string;

/**
 * Hook de traducción del widget.
 *
 * Usa `useTranslation` del kit; si la clave no está registrada en el host
 * (el motor devuelve la propia clave), cae al diccionario local en español.
 */
export function useFinancialInstrumentTranslation(): { t: FinancialInstrumentT } {
  const { t: baseT } = useTranslation();

  const t = useMemo<FinancialInstrumentT>(
    () => (key, vars) => {
      let value = baseT(key);
      if (value === key) {
        value = FINANCIAL_INSTRUMENT_TRANSLATIONS_ES[key] ?? key;
      }
      if (vars) {
        for (const [name, replacement] of Object.entries(vars)) {
          value = value.replace(`{${name}}`, String(replacement));
        }
      }
      return value;
    },
    [baseT],
  );

  return { t };
}
