/**
 * ListTable — data table for master entity list.
 * Uses siesa-ui-kit Table with columns derived from fieldEngine.
 * Renders RowActions as last column. Shows loading skeleton when isLoading=true.
 * Column headers with filterable fields show an inline per-column filter input
 * toggled by a small Filter icon button (matches mock .th-filter pattern).
 *
 * @module components/list/ListTable
 * @see FMPV-MVWC-E002-S003 I-002
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Table } from '../../../Table/Table';
import type { TableColumn } from '../../../Table/Table.types';
import { ChevronsUpDown, ChevronUp, ChevronDown, Filter, Globe, Building2 } from 'lucide-react';
import type { MasterPatternViewDefinition } from '../../types/definition.types';
import type { MasterPatternViewEntity } from '../../types/service.types';
import type { MasterPatternViewPermissions } from '../../types/permissions.types';
import type { MasterPatternViewCustomAction, MasterPatternViewDefaultActions } from '../../types/props.types';
import { useFieldEngine } from '../../hooks/useFieldEngine';
import { getAllFields } from '../../engine/fieldEngine';
import { useMasterViewStore } from '../../store/MasterViewContext';
import { EmptyState } from './EmptyState';
import { RowActions } from './RowActions';
import type { ToastCallback } from '../../hooks/useToast';

export interface ListTableProps<T extends MasterPatternViewEntity = MasterPatternViewEntity> {
  definition: MasterPatternViewDefinition;
  data: T[];
  sortBy: string;
  sortOrder: 'asc' | 'desc';
  onSort: (field: string, direction: 'asc' | 'desc') => void;
  onOpenView: (row: T) => void;
  onOpenEdit: (row: T) => void;
  onChangeStatus?: (row: T) => void;
  isLoading?: boolean;
  permissions?: MasterPatternViewPermissions;
  actions?: MasterPatternViewCustomAction<T>[];
  rowActions?: (row: T) => React.ReactNode;
  toast?: ToastCallback;
  /** Active company context — undefined or 'global' means global view */
  activeCompanyContext?: string;
  /** When true, disables pointer events on the sticky actions column to prevent interaction through modal overlays */
  modalOpen?: boolean;
  defaultActions?: MasterPatternViewDefaultActions<T>;
}

// Shared class for the inline column filter input / select
const colFilterInputClass =
  'w-full border border-border-primary dark:border-dark-border-primary rounded-[5px] px-1.5 py-[3px] text-[11px] text-content-primary dark:text-dark-content-primary bg-bg-primary dark:bg-dark-bg-primary outline-none focus:border-[#93d1fd] focus:ring-[2px] focus:ring-[rgba(14,121,253,0.1)]';

function SortIcon({ field, sortBy, sortOrder }: { field: string; sortBy: string; sortOrder: 'asc' | 'desc' }) {
  if (sortBy !== field) return <ChevronsUpDown size={12} data-testid="icon-chevrons-up-down" className="text-[#d4d4d8] flex-shrink-0" />;
  if (sortOrder === 'asc') return <ChevronUp size={12} data-testid="icon-chevron-up" className="text-[#0e79fd] flex-shrink-0" />;
  return <ChevronDown size={12} data-testid="icon-chevron-down" className="text-[#0e79fd] flex-shrink-0" />;
}

export function ListTable<T extends MasterPatternViewEntity = MasterPatternViewEntity>({
  definition,
  data,
  sortBy,
  sortOrder,
  onSort,
  onOpenView,
  onOpenEdit,
  onChangeStatus,
  isLoading = false,
  permissions,
  actions,
  rowActions,
  toast: toastProp,
  activeCompanyContext,
  modalOpen = false,
  defaultActions,
}: ListTableProps<T>) {
  const isCompanyCtx = !!activeCompanyContext && activeCompanyContext !== 'global';
  const { listColumns } = useFieldEngine(definition);

  // Store — column filters live in their own slice, independent of FilterPanel filters.
  // Both are merged in useMasterList before calling service.getAll().
  const storeColumnFilters = useMasterViewStore((s) => s.columnFilters);
  const setStoreColumnFilters = useMasterViewStore((s) => s.setColumnFilters);
  const setSearchParams = useMasterViewStore((s) => s.setSearchParams);

  // Local state: controls the input display value (immediate feedback while typing)
  const [openColumnFilter, setOpenColumnFilter] = useState<string | null>(null);
  const [columnFilters, setColumnFilters] = useState<Record<string, string>>({});

  // Ref to avoid stale closure inside the debounce timeout
  const filtersRef = useRef(storeColumnFilters);
  useEffect(() => { filtersRef.current = storeColumnFilters; }, [storeColumnFilters]);

  // Debounce timers per field
  const debounceRef = useRef<Record<string, ReturnType<typeof setTimeout>>>({});

  // Sync local input state when column filters are cleared externally (e.g. "Limpiar filtros")
  useEffect(() => {
    setColumnFilters((prev) => {
      const next = { ...prev };
      let changed = false;
      for (const field of Object.keys(prev)) {
        if (prev[field] && !storeColumnFilters.some((f) => f.field === field)) {
          next[field] = '';
          changed = true;
        }
      }
      return changed ? next : prev;
    });
  }, [storeColumnFilters]);

  // Sends the column filter to the backend via the store.
  // Text fields are debounced 350 ms; boolean selects fire immediately.
  const handleColumnFilter = useCallback(
    (field: string, value: string, isBooleanField: boolean) => {
      setColumnFilters((prev) => ({ ...prev, [field]: value }));

      const commit = () => {
        const filterValue: unknown = isBooleanField
          ? value === 'true' ? true : value === 'false' ? false : undefined
          : value;
        const operator = isBooleanField ? 'equals' : 'contains';
        const next = [
          ...filtersRef.current.filter((f) => f.field !== field),
          ...(value ? [{ field, operator, value: filterValue }] : []),
        ];
        setStoreColumnFilters(next);
        setSearchParams({ page: 1 });
      };

      if (isBooleanField) {
        commit();
      } else {
        clearTimeout(debounceRef.current[field]);
        debounceRef.current[field] = setTimeout(commit, 350);
      }
    },
    [setSearchParams],
  );

  const columns = useMemo((): TableColumn<T>[] => {
    const fieldMap = new Map(getAllFields(definition).map((f) => [f.fieldName, f]));

    const dataColumns: TableColumn<T>[] = listColumns.map((col, colIdx) => {
      const fieldDef = fieldMap.get(col.fieldName);
      const isFilterable = !!(fieldDef?.filterable || fieldDef?.quickFilter);
      // Lookup fields are filterable in the advanced panel but cannot be filtered inline
      // (free-text input against a relational field would silently produce no results).
      const isLookupField = fieldDef?.inputType === 'lookup';
      const isBooleanField = fieldDef?.dataType === 'boolean' || fieldDef?.inputType === 'boolean';
      const isFirstCol = colIdx === 0;
      const isOverridable = !!(fieldDef?.isOverridable);

      let renderFn: ((value: unknown, row: T) => React.ReactNode) | undefined;
      if (fieldDef?.renderCell) {
        const baseRender = (value: unknown, row: T) => fieldDef.renderCell!(value, row) as React.ReactNode;
        renderFn = (value: unknown, row: T) => {
          const base = baseRender(value, row);
          if (!isCompanyCtx) return base;
          const r = row as Record<string, unknown>;
          const assignedBadge = isFirstCol && r['isAssigned'] === true
            ? <span title="Habilitado para esta compañía" className="inline-flex items-center justify-center w-5 h-5 rounded-[4px] bg-[#eff8ff] border border-[#93d1fd] text-[#1355b7] ml-1.5 flex-shrink-0 cursor-help"><Building2 size={12} /></span>
            : null;
          const overrides = r['_overrides'] as Record<string, unknown> | undefined;
          const overrideBadge = isOverridable
            ? overrides?.[col.fieldName] !== undefined
              ? <span title="Valor sobreescrito por la compañía" className="inline-flex items-center justify-center w-5 h-5 rounded-[4px] bg-[#eff8ff] border border-[#93d1fd] text-[#1355b7] ml-1 flex-shrink-0 cursor-help"><Building2 size={12} /></span>
              : <span title="Valor global" className="inline-flex items-center justify-center w-5 h-5 rounded-[4px] bg-background-secondary dark:bg-dark-bg-secondary border border-border-primary dark:border-dark-border-primary text-content-tertiary dark:text-dark-content-tertiary ml-1 flex-shrink-0 cursor-help"><Globe size={12} /></span>
            : null;
          return <span className="inline-flex items-center">{base}{assignedBadge}{overrideBadge}</span>;
        };
      } else if (isBooleanField) {
        renderFn = (value: unknown, row: T) => {
          const base = value ? (
            <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-semibold bg-[#ecfccb] text-[#4d7c0f]">
              Activo
            </span>
          ) : (
            <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-semibold bg-background-secondary dark:bg-dark-bg-secondary text-content-tertiary dark:text-dark-content-tertiary">
              Inactivo
            </span>
          );
          if (!isCompanyCtx) return base;
          const r = row as Record<string, unknown>;
          const assignedBadge = isFirstCol && r['isAssigned'] === true
            ? <span title="Habilitado para esta compañía" className="inline-flex items-center justify-center w-5 h-5 rounded-[4px] bg-[#eff8ff] border border-[#93d1fd] text-[#1355b7] ml-1.5 flex-shrink-0 cursor-help"><Building2 size={12} /></span>
            : null;
          const overrides = r['_overrides'] as Record<string, unknown> | undefined;
          const overrideBadge = isOverridable
            ? overrides?.[col.fieldName] !== undefined
              ? <span title="Valor sobreescrito por la compañía" className="inline-flex items-center justify-center w-5 h-5 rounded-[4px] bg-[#eff8ff] border border-[#93d1fd] text-[#1355b7] ml-1 flex-shrink-0 cursor-help"><Building2 size={12} /></span>
              : <span title="Valor global" className="inline-flex items-center justify-center w-5 h-5 rounded-[4px] bg-background-secondary dark:bg-dark-bg-secondary border border-border-primary dark:border-dark-border-primary text-content-tertiary dark:text-dark-content-tertiary ml-1 flex-shrink-0 cursor-help"><Globe size={12} /></span>
            : null;
          return <span className="inline-flex items-center">{base}{assignedBadge}{overrideBadge}</span>;
        };
      } else if (isCompanyCtx && (isFirstCol || isOverridable)) {
        renderFn = (value: unknown, row: T) => {
          const base = value !== undefined && value !== null ? String(value) : '';
          const r = row as Record<string, unknown>;
          const assignedBadge = isFirstCol && r['isAssigned'] === true
            ? <span title="Habilitado para esta compañía" className="inline-flex items-center justify-center w-5 h-5 rounded-[4px] bg-[#eff8ff] border border-[#93d1fd] text-[#1355b7] ml-1.5 flex-shrink-0 cursor-help"><Building2 size={12} /></span>
            : null;
          const overrides = r['_overrides'] as Record<string, unknown> | undefined;
          const overrideBadge = isOverridable
            ? overrides?.[col.fieldName] !== undefined
              ? <span title="Valor sobreescrito por la compañía" className="inline-flex items-center justify-center w-5 h-5 rounded-[4px] bg-[#eff8ff] border border-[#93d1fd] text-[#1355b7] ml-1 flex-shrink-0 cursor-help"><Building2 size={12} /></span>
              : <span title="Valor global" className="inline-flex items-center justify-center w-5 h-5 rounded-[4px] bg-background-secondary dark:bg-dark-bg-secondary border border-border-primary dark:border-dark-border-primary text-content-tertiary dark:text-dark-content-tertiary ml-1 flex-shrink-0 cursor-help"><Globe size={12} /></span>
            : null;
          return <span className="inline-flex items-center">{base}{assignedBadge}{overrideBadge}</span>;
        };
      }

      const isFilterOpen = openColumnFilter === col.fieldName;
      // hasActiveFilter reflects the store (backend filter active), not just the input
      const hasActiveFilter = storeColumnFilters.some((f) => f.field === col.fieldName);

      return {
        header: (
          <div data-testid={`sort-header-${col.fieldName}`}>
            {/* Label row: label on left | filter + sort icons on right */}
            <div
              className="flex items-center justify-between w-full gap-1 cursor-pointer select-none"
              onClick={() => {
                const nextDir = sortBy === col.fieldName && sortOrder === 'asc' ? 'desc' : 'asc';
                onSort(col.fieldName, nextDir);
              }}
            >
              <span className="truncate min-w-0">{col.label}</span>
              <span className="flex items-center gap-0.5 flex-shrink-0">
                {isFilterable && !isLookupField && (
                  <button
                    type="button"
                    data-testid={`filter-icon-${col.fieldName}`}
                    className={`p-0.5 rounded border-0 bg-transparent leading-none transition-colors ${
                      isFilterOpen || hasActiveFilter
                        ? 'text-[#0e79fd]'
                        : 'text-[#a1a1aa] hover:text-[#0e79fd] hover:bg-[#eff8ff]'
                    }`}
                    onClick={(e) => {
                      e.stopPropagation();
                      setOpenColumnFilter((prev) =>
                        prev === col.fieldName ? null : col.fieldName,
                      );
                    }}
                  >
                    <Filter size={11} />
                  </button>
                )}
                <SortIcon field={col.fieldName} sortBy={sortBy} sortOrder={sortOrder} />
              </span>
            </div>

            {/* Inline filter row — shown when toggled */}
            {isFilterable && !isLookupField && isFilterOpen && (
              <div className="mt-1" onClick={(e) => e.stopPropagation()}>
                {isBooleanField ? (
                  <select
                    autoFocus
                    value={columnFilters[col.fieldName] ?? ''}
                    onChange={(e) => handleColumnFilter(col.fieldName, e.target.value, true)}
                    className={colFilterInputClass}
                    data-testid={`col-filter-${col.fieldName}`}
                  >
                    <option value="">Todos</option>
                    <option value="true">Activo</option>
                    <option value="false">Inactivo</option>
                  </select>
                ) : (
                  <input
                    autoFocus
                    type="text"
                    value={columnFilters[col.fieldName] ?? ''}
                    onChange={(e) => handleColumnFilter(col.fieldName, e.target.value, false)}
                    placeholder="Filtrar..."
                    className={colFilterInputClass}
                    data-testid={`col-filter-${col.fieldName}`}
                  />
                )}
              </div>
            )}
          </div>
        ),
        accessor: col.fieldName as keyof T,
        render: renderFn,
      };
    });

    const actionsColumn: TableColumn<T> = {
      header: (
        // The xy header wrapper has `sticky right-0` (position:sticky) → it's a containing block.
        // An absolute child with top:0/bottom:0 fills the full header cell height without negative-margin hacks.
        <div className="w-full text-center">
          <div
            aria-hidden="true"
            style={{
              position: 'absolute',
              left: 0,
              top: 0,
              bottom: 0,
              width: '1px',
              backgroundColor: 'var(--color-border-primary)',
              pointerEvents: 'none',
            }}
          />
          Acciones
        </div>
      ),
      accessor: 'id' as keyof T,
      align: 'center',
      stickyRight: true,
      render: (_value: unknown, row: T) => (
        // The md cell wrapper has `sticky right-0` (position:sticky) → it's a containing block.
        // The absolute border div fills top-to-bottom of the cell regardless of row height,
        // eliminating white gaps when rows grow taller than min-h-[56px].
        <>
          <div
            aria-hidden="true"
            style={{
              position: 'absolute',
              left: 0,
              top: 0,
              bottom: 0,
              width: '1px',
              backgroundColor: 'var(--color-border-primary)',
              pointerEvents: 'none',
            }}
          />
          <div style={modalOpen ? { pointerEvents: 'none' } : undefined}>
            <RowActions
              row={row}
              permissions={permissions}
              onOpenView={onOpenView}
              onOpenEdit={onOpenEdit}
              onChangeStatus={onChangeStatus}
              actions={actions}
              rowActions={rowActions}
              toast={toastProp}
              defaultActions={defaultActions}
            />
          </div>
        </>
      ),
    };

    return [...dataColumns, actionsColumn];
  }, [
    listColumns,
    sortBy,
    sortOrder,
    onSort,
    permissions,
    onOpenView,
    onOpenEdit,
    onChangeStatus,
    actions,
    rowActions,
    toastProp,
    definition,
    openColumnFilter,
    columnFilters,
    storeColumnFilters,
    handleColumnFilter,
    isCompanyCtx,
    modalOpen,
    defaultActions,
  ]);

  // Pass a styled EmptyState as emptyMessage — the Table's empty-state wrapper (py-12)
  // provides the outer spacing, so compact=true removes EmptyState's own padding.
  // Cast needed because siesa-ui-kit types emptyMessage as string, but React renders
  // any ReactNode correctly.
  const emptyContent = (
    <EmptyState hasSearched compact />
  ) as unknown as string;

  return (
    <div className="mpv-list-table">
      <Table<T>
        columns={columns}
        data={data}
        loading={isLoading}
        loadingRows={5}
        onRowClick={(row) => onOpenView(row)}
        variant="fullWidth"
        showBorder={false}
        showShadow={false}
        showPadding={false}
        emptyMessage={emptyContent}
        data-testid="list-table"
      />
    </div>
  );
}
