// ════════════════════════════════════════════════════════════
// PERMISSIONS HELPER — Filtra campos según permisos del usuario
// ════════════════════════════════════════════════════════════

import type { FieldDescriptor } from '../MasterDocument.types';

/**
 * Aplica RBAC declarativo sobre un array de campos.
 *
 * - `permissions === null` → sistema no activo → devuelve campos sin cambios.
 * - `permissionVisibility` ausente → campo siempre visible.
 * - `permissionEnable` ausente → editabilidad controlada solo por editableOn/docState.
 */
function applyPermissions(
  fields: FieldDescriptor[],
  permissions: string[] | null,
): FieldDescriptor[] {
  if (permissions === null) return fields;

  return fields
    .filter((f) => !f.permissionVisibility || permissions.includes(f.permissionVisibility))
    .map((f) => {
      if (!f.permissionEnable || permissions.includes(f.permissionEnable)) return f;
      return { ...f, editableOn: [] };
    });
}

// ════════════════════════════════════════════════════════════
// LINE WIDGET PANEL — Sidebar panel que se carga vía adapter
// ════════════════════════════════════════════════════════════

function LineWidgetPanel({
  config,
  formValues,
  documentId,
  adapter,
}: {
  config: LineModalWidgetConfig;
  formValues: Record<string, unknown>;
  documentId: string | undefined;
  adapter: IMasterDocumentAdapter;
}) {
  const [data, setData] = useState<Record<string, unknown>>({});
  const [loading, setLoading] = useState(false);
  const generationRef = useRef(0);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Build a snapshot of only the watched fields to avoid unnecessary fetches
  const watchSnapshot = useMemo(() => {
    const snap: Record<string, unknown> = {};
    config.watchFields.forEach((k) => { snap[k] = formValues[k]; });
    return snap;
  }, [config.watchFields, formValues]);

  useEffect(() => {
    if (!adapter.getLineWidgetData) return;

    if (timerRef.current) clearTimeout(timerRef.current);

    const delay = config.debounceMs ?? 300;
    timerRef.current = setTimeout(async () => {
      const gen = ++generationRef.current;
      setLoading(true);
      try {
        const result = await adapter.getLineWidgetData!(config.widgetKey, watchSnapshot, documentId);
        if (generationRef.current === gen) setData(result);
      } catch {
        // Leave previous data on error
      } finally {
        if (generationRef.current === gen) setLoading(false);
      }
    }, delay);

    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [watchSnapshot]); // eslint-disable-line react-hooks/exhaustive-deps

  const entries = Object.entries(data);

  return (
    <div className="flex flex-col h-full">
      {/* Panel header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border-secondary dark:border-dark-border-primary shrink-0">
        <span className="text-xs font-semibold uppercase tracking-wide text-content-secondary dark:text-dark-content-secondary">
          {config.title}
        </span>
        {loading && (
          <svg className="w-3.5 h-3.5 animate-spin text-primary-custom-500 dark:text-dark-border-custom" viewBox="0 0 24 24" fill="none">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" />
            <path className="opacity-80" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z" />
          </svg>
        )}
      </div>

      {/* KV list */}
      <div className="flex-1 overflow-y-auto px-4 py-3 space-y-2.5">
        {entries.length === 0 && !loading && (
          <p className="text-xs text-content-secondary dark:text-dark-content-secondary italic">
            Sin datos
          </p>
        )}
        {entries.map(([key, value]) => (
          <div key={key} className="flex flex-col gap-0.5">
            <span className="text-[10px] font-medium uppercase tracking-wide text-content-secondary dark:text-dark-content-secondary">
              {key}
            </span>
            <span className="text-sm font-medium text-content-primary dark:text-dark-content-primary break-words">
              {String(value ?? '—')}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

