export interface SmartMasterDocumentProps {
  /**
   * UUID (v7) del documento a cargar. Es la PK de document_headers.id.
   * Si no se pasa, entra en modo 'create'.
   *
   * NO es el document_number legible ("PV-2026-004821"), sino el UUID
   * globalmente único que identifica el registro sin ambigüedad,
   * independiente de compañía, centro de operación o tipo de documento.
   */
  documentId?: string;

  /**
   * Estado inicial pre-poblado por el backend via GET /documents/new.
   * Cuando se provee, el documento arranca en modo 'create' con los
   * headerValues ya resueltos (compañía, CO, tipo). No hay ID todavía;
   * el POST se hace al guardar por primera vez.
   */
  initialState?: import('../adapter/MasterDocumentAdapter.types').DocumentState;

  /** Llamado tras un guardado exitoso. Usado por MasterDocumentPage para volver al listado. */
  onSaved?: () => void;

  /**
   * Llamado cuando una acción elimina el documento y devuelve
   * `{ success: true, navigateToList: true }`. Usado por MasterDocumentPage
   * para volver al listado tras borrar/anular el documento desde el detalle.
   */
  onNavigateToList?: () => void;

  /**
   * Fuerza el modo 'view' (solo lectura) independiente de lo que retorne el adapter.
   * Usado por "Ver detalle" en el listado.
   */
  viewOnly?: boolean;

  /**
   * Adapter alternativo. Si se pasa, toma precedencia sobre el del contexto.
   * Usado por MasterDocumentPage para inyectar un adapter con navegación interceptada.
   */
  adapterOverride?: IMasterDocumentAdapter;
}

