// ════════════════════════════════════════════════════════════
// COMPONENT
// ════════════════════════════════════════════════════════════

/**
 * SmartMasterDocument — componente inteligente que conecta el template JSON
 * con el adaptador de datos para renderizar un documento maestro completo.
 *
 * Orquesta el ciclo de vida del documento:
 * - Carga y mutación de estado vía `useMasterDocumentReducer`
 * - Carga asíncrona de datos del FactBox vía `useFactBoxData`
 * - Conflicto de concurrencia duro derivado del 409 del servidor (`state.conflict`)
 * - Construcción de transiciones, acciones y secciones del FactBox
 *   a partir del template declarativo
 *
 * @see MasterDocumentProvider — proveedor que inyecta el template y el adaptador
 * @see MasterDocument — componente de presentación pura que recibe los datos
 *
 * @example
 * ```tsx
 * <MasterDocumentProvider template={invoiceTemplate} adapter={myAdapter}>
 *   <SmartMasterDocument documentId="FA-001" />
 * </MasterDocumentProvider>
 * ```
 */
export function SmartMasterDocument({ documentId, initialState, onSaved, viewOnly, adapterOverride, onNavigateToList }: SmartMasterDocumentProps) {
  const contextAdapter = useMasterDocumentAdapter();
  const adapter = adapterOverride ?? contextAdapter;
  const template = useMasterDocumentTemplate();
  const iconRegistry = useIconRegistry();
  const userPermissions = useUserPermissions();
  const factBoxWidgets = useFactBoxWidgets();
  const print = useMasterDocumentPrint();

  const {
    state,
    dispatch,
    handleHeaderFieldChange,
    handleLineSave,
    handleDeleteLine,
    handleDuplicateLine,
    handleTransition,
    handleAction,
  } = useMasterDocumentReducer(template, adapter, documentId, initialState, onSaved, viewOnly, onNavigateToList);

  // ── Error toast ───────────────────────────────────
  useEffect(() => {
    if (!state.error) return;
    toast.error('Error', { description: state.error });
    dispatch({ type: 'SET_ERROR', error: undefined });
  }, [state.error]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── FactBox data loading ──────────────────────────
  useFactBoxData(
    template.factBox.sections,
    adapter,
    state,
    dispatch,
  );

  // ── Conflict detection ────────────────────────────
  // La fuente de verdad de un conflicto es el 409 del servidor
  // (`OPTIMISTIC_LOCK_VIOLATION`) en cualquier mutación, persistido por el reducer
  // en `state.conflict` con `hard: true`. Se eliminó el polling blando
  // (`useConflictDetection`): llegaba segundos tarde y era descartable, permitiendo
  // guardar con un token viejo. Ahora el conflicto es duro y no descartable.

  // ── Dynamic document states (from API) ───────────────────
  // GET /api/v1/documents/{documentClass}/states
  // Allows adding/modifying states in the DB without touching the template.
  // Falls back to template.stateMachine.states when the endpoint is unavailable.
  const [dynamicStates, setDynamicStates] = useState<import('../adapter/MasterDocumentAdapter.types').DocumentStatesResponse | null>(null);

  useEffect(() => {
    if (!adapter.getDocumentStates) return;
    let cancelled = false;
    adapter.getDocumentStates(template.identity.documentClass)
      .then((s) => { if (!cancelled) setDynamicStates(s); })
      .catch(() => { if (!cancelled) setDynamicStates(null); });
    return () => { cancelled = true; };
  }, [adapter, template.identity.documentClass]);

  // ── Available actions (from DocumentProcess endpoint) ────
  // GET /api/v1/documents/{id}/available-actions?state={docState}
  // Returns the keys of actions enabled for the current user/state/role.
  // When null (method not implemented), falls back to template's visibleOn.
  const [availableActionKeys, setAvailableActionKeys] = useState<string[] | null>(null);

  useEffect(() => {
    if (!adapter.getAvailableActions) {
      setAvailableActionKeys(null);
      return;
    }
    const docId = state.documentId ?? '';
    let cancelled = false;
    adapter.getAvailableActions(docId, state.docState)
      .then((keys) => { if (!cancelled) setAvailableActionKeys(keys); })
      .catch(() => { if (!cancelled) setAvailableActionKeys(null); });
    return () => { cancelled = true; };
  }, [adapter, state.documentId, state.docState]);

  // ── Resolve icon string → ReactNode ───────────────
  const resolveIcon = useCallback(
    (iconName?: string): ReactNode => {
      if (!iconName) return undefined;
      const Icon = iconRegistry[iconName];
      if (!Icon) return undefined;
      return <Icon className="w-4 h-4" />;
    },
    [iconRegistry],
  );

  // ── Map serializable transitions → TransitionConfig[]
  // API transitions take priority; fall back to template-embedded transitions.
  const transitions = useMemo<TransitionConfig[]>(() => {
    // API transitions: use when getDocumentStates returned them
    if (dynamicStates?.transitions && dynamicStates.transitions.length > 0) {
      const seen = new Set<string>();
      return dynamicStates.transitions
        .filter((t) => t.from === state.docState)
        .filter((t) => {
          // Deduplicate by actionKey — show only the first transition per action.
          if (seen.has(t.actionKey)) return false;
          seen.add(t.actionKey);
          return true;
        })
        .map((t) => {
          // Look up action metadata (label, icon, style):
          // 1. Inline in transition (backend-provided) → 2. actionRegistry (v1.1) → 3. actions[] (v1.0) → 4. raw key
          const registryEntry: ActionRegistryEntry | undefined = template.actionRegistry?.[t.actionKey];
          const legacyMeta = registryEntry ? undefined : template.actions?.find((a: SerializableActionConfig) => a.key === t.actionKey);
          const label = t.label ?? registryEntry?.label ?? legacyMeta?.label ?? t.actionKey;
          const icon = resolveIcon(t.icon ?? registryEntry?.icon ?? legacyMeta?.icon);
          const style = (t.variant ?? registryEntry?.variant ?? legacyMeta?.variant ?? 'secondary') as import('../MasterDocument.types').ActionVariant;
          // Gating in-flight (Caso B): mientras hay una mutación en curso, las
          // transiciones (aprobar/anular) se deshabilitan para evitar doble disparo.
          return { to: t.to, actionKey: t.actionKey, label, icon, style, hasGuard: t.hasGuard, disabled: state.saving };
        });
    }
    // Template fallback (v1.0 format with embedded transitions)
    const templateTransitions = template.stateMachine.transitions ?? [];
    return templateTransitions
      .filter((t: SerializableTransitionConfig) => t.from.includes(state.docState))
      .map((t: SerializableTransitionConfig) => ({
        to: t.to,
        label: t.label,
        icon: resolveIcon(t.icon),
        style: t.style,
        hasGuard: t.hasGuard,
        shortcut: t.shortcut,
        disabled: state.saving,
      }));
  }, [template.stateMachine.transitions, template.actions, template.actionRegistry, dynamicStates, state.docState, state.saving, resolveIcon]);

  // ── Map serializable actions → ActionConfig[] ─────
  // Priority: API (availableActionKeys) > template visibleOn
  // When the API returns a list, it acts as the whitelist — only those keys are shown.
  // When null (endpoint not implemented), falls back to template's visibleOn logic.
  const actions = useMemo<ActionConfig[]>(() => {
    // Keys for the current state that are already rendered as transition buttons.
    // These must NOT also appear as action buttons (would create visible duplicates).
    const activeTransitionKeys = new Set(
      (dynamicStates?.transitions ?? [])
        .filter((t) => t.from === state.docState)
        .map((t) => t.actionKey),
    );

    // v1.1: use actionRegistry only when the API provides availableActionKeys.
    // Without that whitelist every registry entry would render as a button,
    // including transition-label entries that are only used for key→label resolution.
    if (template.actionRegistry && availableActionKeys !== null) {
      return Object.entries(template.actionRegistry)
        .filter(([key, entry]) => {
          if (activeTransitionKeys.has(key)) return false;
          if (entry.permissionVisibility && userPermissions !== null && !userPermissions.includes(entry.permissionVisibility)) return false;
          // Una acción con `disabledStates` que incluya el estado actual se
          // muestra (deshabilitada) aunque no venga en availableActionKeys.
          const { disabled } = resolveActionDisabledState(entry, state.docState);
          return availableActionKeys.includes(key) || (entry.alwaysVisible && !!state.documentId) || disabled;
        })
        .map(([key, entry]: [string, ActionRegistryEntry]) => {
          const { disabled, disabledReason } = resolveActionDisabledState(entry, state.docState);
          return {
            key,
            label: entry.label,
            icon: resolveIcon(entry.icon),
            variant: entry.variant,
            // Una acción deshabilitada no ejecuta nada (ni abre confirmación).
            onClick: disabled
              ? () => {}
              : entry.actionType === 'modalList' && entry.modalList
                ? () => {
                    setActiveModalListConfig(entry.modalList!);
                    setModalListLineId(undefined);
                    setModalListOpen(true);
                  }
                : () => handleAction(key),
            // Gating in-flight (Caso B): además de su estado declarativo, la acción
            // se deshabilita mientras haya una mutación en curso.
            disabled: disabled || state.saving,
            disabledReason,
            position: entry.position,
            requiresConfirmation: disabled ? false : (entry.actionType === 'modalList' ? false : entry.requiresConfirmation),
            confirmationMessage: disabled ? undefined : (entry.actionType === 'modalList' ? undefined : entry.confirmationMessage),
          };
        });
    }

    // v1.0 fallback: actions array with visibleOn
    return (template.actions ?? [])
      .filter((a: SerializableActionConfig) => {
        if (a.permissionVisibility && userPermissions !== null && !userPermissions.includes(a.permissionVisibility)) return false;
        if (availableActionKeys !== null) {
          return availableActionKeys.includes(a.key) && !activeTransitionKeys.has(a.key);
        }
        if (a.visibleOn && a.visibleOn.length > 0) {
          return a.visibleOn.includes(state.docState) || a.visibleOn.includes('*');
        }
        return true;
      })
      .map((a: SerializableActionConfig) => {
        // Even in v1.0 mode, check if this key has a modalList config in actionRegistry
        const registryEntry = template.actionRegistry?.[a.key];
        const isModalList = registryEntry?.actionType === 'modalList' && !!registryEntry.modalList;
        return {
          key: a.key,
          label: a.label,
          icon: resolveIcon(a.icon),
          variant: a.variant,
          onClick: isModalList
            ? () => {
                setActiveModalListConfig(registryEntry!.modalList!);
                setModalListLineId(undefined);
                setModalListOpen(true);
              }
            : () => handleAction(a.key),
          disabled: (a.disabledOn?.includes(state.docState) ?? false) || state.saving,
          position: a.position,
        };
      });
  }, [template.actions, template.actionRegistry, state.docState, state.saving, resolveIcon, handleAction, availableActionKeys, dynamicStates]);

  // ── Impresión nativa (botón en la barra del detalle) ──
  // Acción de presentación: NO pasa por adapter.executeAction ni por el
  // actionRegistry. Se anexa al array de acciones cuando la impresión está
  // disponible para el documento guardado (regla §4.3-a).
  const actionsWithPrint = useMemo<ActionConfig[]>(() => {
    if (!print) return actions;
    const ctx: PrintContext = {
      source: 'detail',
      documentId: state.documentId ?? '',
      documentNumber: (state.headerValues['_documentNumber'] as string | undefined) ?? null,
      docState: state.docState || null,
    };
    if (!print.isPrintAvailable(ctx)) return actions;
    return [
      ...actions,
      {
        key: 'print',
        label: print.label,
        icon: <PrintIcon className="w-4 h-4" />,
        // 'ghost' por defecto → texto primary-600 legible (SPEC §5.2), no compite
        // con la primaria. Configurable vía printing.buttonVariant.
        variant: print.buttonVariant,
        onClick: () => print.openPrint(ctx),
      },
    ];
  }, [print, actions, state.documentId, state.headerValues, state.docState]);

  // ── Context strip items ───────────────────────────
  const contextItems = useMemo<ContextStripItem[]>(() => {
    return template.contextStrip.map((m) => ({
      label: m.label,
      value: String(state.headerValues[m.field] ?? ''),
      mono: m.mono,
      accent: m.accent,
    }));
  }, [template.contextStrip, state.headerValues]);

  // ── Currency code (resolved from headerValues or defaultCode) ──
  const currencyCode = useMemo(() => {
    const cfg = template.currency;
    if (!cfg) return '';
    return String(state.headerValues[cfg.codeField] ?? '') || cfg.defaultCode || '';
  }, [template.currency, state.headerValues]);

  // ── Fetch exchange rate from backend ──────────────
  const [exchangeRate, setExchangeRate] = useState<{ rate: number; label: string } | null>(null);

  useEffect(() => {
    if (!currencyCode || !adapter.getExchangeRate) {
      setExchangeRate(null);
      return;
    }
    let cancelled = false;
    adapter.getExchangeRate(currencyCode)
      .then((result) => { if (!cancelled) setExchangeRate(result); })
      .catch(() => { if (!cancelled) setExchangeRate(null); });
    return () => { cancelled = true; };
  }, [currencyCode, adapter]);

  // ── DocumentModalList state ───────────────────────
  const [modalListOpen, setModalListOpen] = useState(false);
  const [activeModalListConfig, setActiveModalListConfig] = useState<DocumentModalListConfig | null>(null);
  const [modalListLineId, setModalListLineId] = useState<string | undefined>(undefined);

  // ── Currency selector modal ───────────────────────
  const [currencyModalOpen, setCurrencyModalOpen] = useState(false);
  const [availableCurrencies, setAvailableCurrencies] = useState<CurrencyInfo[]>([]);
  const [currenciesLoading, setCurrenciesLoading] = useState(false);

  const handleOpenCurrencyModal = useCallback(() => {
    setCurrencyModalOpen(true);
    if (availableCurrencies.length === 0 && adapter.listCurrencies) {
      setCurrenciesLoading(true);
      adapter.listCurrencies(true)
        .then((list) => setAvailableCurrencies(list))
        .catch(() => {})
        .finally(() => setCurrenciesLoading(false));
    }
  }, [adapter, availableCurrencies.length]);

  const handleCurrencySelect = useCallback(
    (currency: CurrencyInfo) => {
      setCurrencyModalOpen(false);
      // Actualización optimista: el panel cambia de inmediato
      const cfg = template.currency;
      if (cfg) handleHeaderFieldChange(cfg.codeField, currency.code);
      // Persiste en backend en background (si el adapter lo soporta)
      adapter.changeCurrency?.(state.documentId ?? '', currency.code);
    },
    [adapter, state.documentId, template.currency, handleHeaderFieldChange],
  );

  // ── Currency panel ────────────────────────────────
  const currencyPanel = useMemo<ReactNode>(() => {
    const cfg = template.currency;
    if (!cfg || !currencyCode) return undefined;

    const rate = exchangeRate?.rate ?? (cfg.rateField ? state.headerValues[cfg.rateField] : undefined);
    const rateLabel = exchangeRate?.label ?? cfg.rateLabel;
    const canEdit = cfg.editable && state.mode !== 'view';

    return (
      <CurrencyPanel
        code={currencyCode}
        rate={rate as string | number | undefined}
        rateLabel={rateLabel}
        onClick={canEdit ? handleOpenCurrencyModal : undefined}
      />
    );
  }, [template.currency, currencyCode, exchangeRate, state.headerValues, state.mode, handleOpenCurrencyModal]);

  // ── Computed rules → bridge to function-based ─────
  const lineComputedRules = useMemo<ComputedRule[]>(() => {
    return template.computedRules
      .filter((r) => {
        const field = template.fields.find((f) => f.key === r.targetField);
        return field?.context === 'line';
      })
      .map((r) => ({
        targetField: r.targetField,
        watch: r.watch,
        compute: (formData: Record<string, unknown>) =>
          evaluateExpression(r.expression, formData, adapter.evaluateCustomRule?.bind(adapter)),
      }));
  }, [template.computedRules, template.fields, adapter]);

  // ── Adapter con formatCurrency ajustado a la moneda activa ──
  const factBoxAdapter = useMemo(() => {
    if (!currencyCode) return adapter;
    try {
      const fmt = new Intl.NumberFormat('es-CO', {
        style: 'currency',
        currency: currencyCode,
        minimumFractionDigits: 0,
      });
      return { ...adapter, formatCurrency: (v: number) => fmt.format(v) };
    } catch {
      return adapter;
    }
  }, [adapter, currencyCode]);

  // ── FactBox sections → ReactNode children ─────────
  const factBoxSections = useMemo(
    () => buildFactBoxSections(template.factBox.sections, state, factBoxAdapter, userPermissions, factBoxWidgets),
    [template.factBox.sections, state, factBoxAdapter, userPermissions, factBoxWidgets],
  );

  // ── Conflict config ───────────────────────────────
  // Único origen: el 409 del servidor (`state.conflict`, `hard: true`). El modal
  // duro no es descartable: la única acción es "Recargar documento", que descarta
  // la edición en vuelo, re-obtiene el documento + row_version y reconcilia.
  const conflictProp = useMemo(() => {
    const active = state.conflict;
    if (!active) return undefined;
    const clear = () => dispatch({ type: 'CLEAR_CONFLICT' });
    return {
      modifiedBy: active.modifiedBy,
      modifiedAgo: active.modifiedAgo,
      message: active.message,
      // hard ⇒ no descartable (sin "seguir con mis cambios"); blando ⇒ descartable.
      dismissable: !active.hard,
      onReload: () => {
        clear();
        if (state.documentId) {
          adapter.getDocument(state.documentId).then((doc) => {
            dispatch({ type: 'LOAD_SUCCESS', payload: doc });
          });
        }
      },
      // En el conflicto duro no se permite seguir editando con el token viejo.
      onKeepEditing: active.hard ? undefined : clear,
    };
  }, [state.conflict, state.documentId, adapter, dispatch]);

  // ── Forbidden / 403 banner ────────────────────────
  const forbiddenProp = useMemo(() => {
    if (!state.forbidden) return undefined;
    return {
      message: state.forbidden.message,
      onDismiss: () => dispatch({ type: 'CLEAR_FORBIDDEN' }),
    };
  }, [state.forbidden, dispatch]);

  // Resolved badge: API overrides template for the current state
  const resolvedStateBadge = useMemo(() => {
    if (dynamicStates) {
      const entry = dynamicStates.states.find((s) => s.key === state.docState);
      if (entry) return { label: entry.label, bg: entry.bg, color: entry.color };
    }
    // Fallback to template (old record format)
    return template.stateMachine.states?.[state.docState];
  }, [dynamicStates, state.docState, template.stateMachine.states]);

  // ── Field rules (from API) ────────────────────────────────
  // GET /api/v1/documents/{documentClass}/field-rules?state={docState}
  // Overrides editableOn/visibleOn from the template for the current state.
  // When null (method not implemented), falls back to template field arrays.
  const [fieldRules, setFieldRules] = useState<Record<string, { editable: boolean; visible: boolean }> | null>(null);

  useEffect(() => {
    if (!adapter.getFieldRules) {
      setFieldRules(null);
      return;
    }
    let cancelled = false;
    adapter.getFieldRules(template.identity.documentClass, state.docState)
      .then((rules) => { if (!cancelled) setFieldRules(rules); })
      .catch(() => { if (!cancelled) setFieldRules(null); });
    return () => { cancelled = true; };
  }, [adapter, template.identity.documentClass, state.docState]);

  // ── Dynamic select options (optionsSource) ───────────────
  // For fields with optionsSource, fetch options from API once per companyId/coId change.
  // Stored as Record<fieldKey, SelectOption[]> — merged into the field's options array.
  const [dynamicOptions, setDynamicOptions] = useState<Record<string, Array<{ label: string; value: string }>>>({});

  useEffect(() => {
    if (!adapter.getSelectOptions) return;

    const companyId = String(state.headerValues._companyId ?? '');
    const coId = String(state.headerValues._coId ?? '');

    const fieldsWithSource = template.fields.filter(
      (f) => f.context === 'header' || f.context === 'line' || f.context === 'line-detail',
    ).filter((f) => (f as import('../MasterDocument.types').FieldDescriptor & { optionsSource?: string }).optionsSource);

    if (fieldsWithSource.length === 0) return;

    let cancelled = false;
    const loads = fieldsWithSource.map(async (f) => {
      const src = (f as { optionsSource?: string }).optionsSource!;
      try {
        const opts = await adapter.getSelectOptions!(src, companyId || undefined, coId || undefined);
        if (!cancelled) setDynamicOptions((prev) => ({ ...prev, [f.key]: opts }));
      } catch { /* fallback: keep static options */ }
    });
    Promise.allSettled(loads);

    return () => { cancelled = true; };
  }, [adapter, template.fields, state.headerValues._companyId, state.headerValues._coId]);

  // ── Separate header vs line fields ────────────────
  // Applies template visibleOn filtering + API field-rules overrides + dynamic options.
  const headerFields = useMemo(() => {
    const base = template.fields.filter((f) => {
      if (f.context !== 'header') return false;
      if (f.visibleOn && f.visibleOn.length > 0 && !f.visibleOn.includes('*')) {
        return f.visibleOn.includes(state.docState);
      }
      return true;
    });
    const withRules = base
      .filter((f) => !fieldRules || fieldRules[f.key]?.visible !== false)
      .map((f) => {
        let updated = f;
        if (fieldRules?.[f.key]) {
          const rule = fieldRules[f.key];
          const editableOn = rule.editable
            ? [...new Set([...f.editableOn, state.docState])]
            : f.editableOn.filter((s) => s !== state.docState && s !== '*');
          updated = { ...updated, editableOn };
        }
        if (dynamicOptions[f.key]) {
          updated = { ...updated, options: dynamicOptions[f.key] };
        }
        return updated;
      });
    return applyPermissions(withRules, userPermissions);
  }, [template.fields, fieldRules, dynamicOptions, state.docState, userPermissions]);

  const lineFields = useMemo(() => {
    const base = template.fields.filter((f) => {
      if (f.context !== 'line' && f.context !== 'line-detail') return false;
      return isLineFieldVisibleInState(f, state.docState);
    });
    const withRules = base
      .filter((f) => !fieldRules || fieldRules[f.key]?.visible !== false)
      .map((f) => {
        let updated = f;
        if (fieldRules?.[f.key]) {
          const rule = fieldRules[f.key];
          const editableOn = rule.editable
            ? [...new Set([...f.editableOn, state.docState])]
            : f.editableOn.filter((s) => s !== state.docState && s !== '*');
          updated = { ...updated, editableOn };
        }
        if (dynamicOptions[f.key]) {
          updated = { ...updated, options: dynamicOptions[f.key] };
        }
        return updated;
      });
    return applyPermissions(withRules, userPermissions);
  }, [template.fields, fieldRules, dynamicOptions, state.docState, userPermissions]);

  // ── Resolved header sections (H1) ────────────────
  // Filters by docState (visibleOn), field conditions (visibleWhen/hiddenWhen) and RBAC.
  const resolvedHeaderSections = useMemo(() => {
    return template.layout.header.sections.filter((s) => {
      if (s.visibleOn && s.visibleOn.length > 0 && !s.visibleOn.includes('*')) {
        if (!s.visibleOn.includes(state.docState)) return false;
      }
      if (s.visibleWhen && !evaluateCondition(s.visibleWhen, state.headerValues as Record<string, unknown>)) return false;
      if (s.hiddenWhen && evaluateCondition(s.hiddenWhen, state.headerValues as Record<string, unknown>)) return false;
      if (s.permissionVisibility && userPermissions !== null && !userPermissions.includes(s.permissionVisibility)) return false;
      return true;
    });
  }, [template.layout.header.sections, state.docState, state.headerValues, userPermissions]);

  // ── Resolved line columns (H2) ───────────────────
  // Filters by field conditions (visibleWhen/hiddenWhen) and RBAC.
  const resolvedLineColumns = useMemo(() => {
    return template.layout.detail.columns.filter((c) => {
      if (c.visibleWhen && !evaluateCondition(c.visibleWhen, state.headerValues as Record<string, unknown>)) return false;
      if (c.hiddenWhen && evaluateCondition(c.hiddenWhen, state.headerValues as Record<string, unknown>)) return false;
      if (c.permissionVisibility && userPermissions !== null && !userPermissions.includes(c.permissionVisibility)) return false;
      return true;
    });
  }, [template.layout.detail.columns, state.headerValues, userPermissions]);

  // ── canAddLine — encabezado lleno (§13.3.1) ─────────
  // Bloquea agregar líneas hasta que todos los campos required del encabezado tengan valor.
  const canAddLine = useMemo(() => {
    if (state.mode === 'view') return false;
    return headerFields
      .filter((f) => f.required)
      .every((f) => {
        const val = state.headerValues[f.key];
        return val !== null && val !== undefined && val !== '';
      });
  }, [state.mode, headerFields, state.headerValues]);

  // ── LookupField configs from template.searchers ──
  const lookupConfigs = useMemo(() => {
    const configs: Record<string, LookupFieldConfig> = {};
    for (const [fieldKey, cfg] of Object.entries(template.searchers ?? {})) {
      configs[fieldKey] = {
        entity: cfg.entity,
        displayFields: cfg.displayFields,
        searchFields: cfg.searchFields,
        displayTemplate: cfg.displayTemplate,
        valueField: cfg.valueField,
        pageSize: cfg.pageSize,
        filters: cfg.filters,
        bindFields: cfg.bindFields,
        filterDependencies: cfg.filterDependencies,
      };
    }
    return configs;
  }, [template.searchers]);

  // ── Handle LookupField record selection (bindFields) ──
  const handleRecordSelect = useCallback(
    (fieldKey: string, record: Record<string, unknown> | null) => {
      if (!record) return;
      const searcherCfg = template.searchers?.[fieldKey];
      if (!searcherCfg?.bindFields) return;
      // Apply bindFields: { "item_name": "nombre" } → set headerValues.item_name = record.nombre
      for (const [targetField, sourceField] of Object.entries(searcherCfg.bindFields)) {
        const value = record[sourceField];
        if (value !== undefined) {
          handleHeaderFieldChange(targetField, value);
        }
      }
    },
    [template.searchers, handleHeaderFieldChange],
  );

  // ── Server rules callback ────────────────────────
  const handleEvaluateServerRule = useCallback(
    (ruleId: string, formData: Record<string, unknown>) => {
      if (!adapter.evaluateServerRule) return Promise.resolve({});
      return adapter.evaluateServerRule(ruleId, formData, state.documentId);
    },
    [adapter, state.documentId],
  );

  // ── Widget slot (G4) ─────────────────────────────
  // Tracks the current form values from the line modal; fed by onLineFormValuesChange.
  const [lineFormValues, setLineFormValues] = useState<Record<string, unknown>>({});

  const lineWidgetSlot = useMemo<ReactNode>(() => {
    const widgets = template.layout.detail.lineModal?.widgets;
    if (!widgets || widgets.length === 0 || !adapter.getLineWidgetData) return undefined;

    // Filter widgets by visibleWhen/hiddenWhen conditions evaluated against current form values
    const visibleWidgets = widgets.filter((w: LineModalWidgetConfig) => {
      if (w.visibleWhen && !evaluateCondition(w.visibleWhen as FieldCondition, lineFormValues)) return false;
      if (w.hiddenWhen && evaluateCondition(w.hiddenWhen as FieldCondition, lineFormValues)) return false;
      return true;
    });

    if (visibleWidgets.length === 0) return undefined;

    return (
      <div className="flex flex-col h-full divide-y divide-border-secondary dark:divide-dark-border-primary">
        {visibleWidgets.map((w: LineModalWidgetConfig) => (
          <LineWidgetPanel
            key={w.widgetKey}
            config={w}
            formValues={lineFormValues}
            documentId={state.documentId}
            adapter={adapter}
          />
        ))}
      </div>
    );
  }, [template.layout.detail.lineModal?.widgets, adapter, lineFormValues, state.documentId]);

  // ── Crossing ──────────────────────────────────────
  const baseUrl = (adapter as { baseUrl?: string }).baseUrl ?? 'http://localhost:5204';
  const crossingFetch = useMemo(() => createCrossingFetch(adapter, baseUrl), [adapter, baseUrl]);

  const crossing = useCrossing({
    config: template.crossing,
    documentId: state.documentId,
    docState: state.docState,
    hasLines: state.lines.length > 0,
    crossingFetch,
    onDocumentGenerated: (docId) => handleAction(`navigate_document:${docId}`),
  });

  const crossingProps = useMemo(() => {
    if (!crossing || !template.crossing) return undefined;
    const { state: cs, actions: ca } = crossing;
    return {
      sourceSelector: {
        selectedDocuments: cs.selectedSourceDocuments,
        onAdd: ca.addSourceDocument,
        onRemove: ca.removeSourceDocument,
        locked: cs.sourceSelectorLocked,
        searchDocuments: ca.searchSourceDocuments,
      },
      selectionMode: template.crossing.generateOn.includes(state.docState),
      selectedLineIds: cs.selectedLineIds,
      onLineSelect: ca.toggleLineSelection,
      onTrySelectTerminalLine: ca.trySelectTerminalLine,
      lineStatuses: cs.lineStatuses,
      lineSelectionErrors: cs.lineSelectionErrors,
      pendingLines: cs.pendingLines,
      quantitiesToCross: cs.quantitiesToCross,
      onQuantityChange: ca.setQuantityToCross,
      formatNumber: adapter.formatNumber,
      pendingLinesFetchedAt: cs.pendingLinesFetchedAt,
      pendingLinesLoading: cs.pendingLinesLoading,
      onRefreshPendingLines: ca.refreshPendingLines,
      activeTab: cs.activeTab,
      onTabChange: ca.setActiveTab,
      traceabilityLabel: template.crossing.traceability?.label ?? 'Trazabilidad',
      traceabilityTree: cs.traceabilityTree,
      traceabilityLoading: cs.traceabilityLoading,
      traceabilityError: cs.traceabilityError,
      onRetryTraceability: ca.refreshTraceability,
      onTraceabilityNodeClick: (nodeId: string) => handleAction(`navigate_document:${nodeId}`),
      classMenuOptions: cs.crossingClassOptions,
      // selectClass cierra el menú y abre el modal de header con la clase elegida.
      onSelectClass: ca.selectClass,
      canGenerate: cs.canGenerate,
      lineCloseModal: cs.lineCloseModal,
      onOpenLineCloseModal: ca.openLineCloseModal,
      onCloseLineCloseModal: ca.closeLineCloseModal,
      onConfirmLineClose: ca.confirmLineClose,
      lineActions: template.crossing?.lineActions,
      generateModal: cs.generateModal,
      onOpenGenerateModal: ca.openGenerateModal,
      onCancelGenerateModal: ca.cancelGenerateModal,
      onConfirmGenerate: ca.confirmGenerate,
      generateError: cs.generateError,
      onClearGenerateError: ca.clearGenerateError,
      generateHeaderFields: template.crossing?.generateHeaderFields ?? [],
      pageErrors: cs.pageErrors,
      onDismissPageError: ca.dismissPageError,
    };
  }, [crossing, template.crossing, state.docState, state.lines.length, handleAction]);

  // ── Render ────────────────────────────────────────
  return (
    <>
      <MasterDocument
        documentId={state.documentId}
        documentNumber={(state.headerValues['_documentNumber'] as string) ?? undefined}
        docTypeBadge={template.identity.label}
        breadcrumbLabel={template.identity.breadcrumbLabel}
        onBreadcrumbClick={() => handleAction('navigate_back')}
        docState={state.docState}
        stateBadge={resolvedStateBadge}
        mode={state.mode}
        transitions={transitions}
        onTransition={handleTransition}
        actions={actionsWithPrint}
        contextItems={contextItems}
        currencyPanel={currencyPanel}
        headerLayout={{ ...template.layout.header, sections: resolvedHeaderSections }}
        headerFields={headerFields}
        headerValues={state.headerValues}
        headerErrors={state.headerErrors}
        onHeaderFieldChange={handleHeaderFieldChange}
        lookupConfigs={lookupConfigs}
        fetcher={adapter.fetcher}
        onRecordSelect={handleRecordSelect}
        linesTitle={template.layout.detail.title}
        lines={state.lines}
        lineColumns={resolvedLineColumns}
        lineFields={lineFields}
        lineComputedRules={lineComputedRules}
        lineServerRules={template.serverRules}
        onEvaluateServerRule={adapter.evaluateServerRule ? handleEvaluateServerRule : undefined}
        lineModalSections={template.layout.detail.lineModal?.sections}
        serialSupport={template.layout.detail.serialSupport}
        serialReadOnly={
          state.mode === 'view' ||
          (template.layout.detail.serialSupport
            ? state.docState !== template.stateMachine.initial
            : undefined)
        }
        validateSerial={adapter.validateSerial?.bind(adapter)}
        fetchAvailableSerials={adapter.fetchAvailableSerials?.bind(adapter)}
        lineWidgetSlot={lineWidgetSlot}
        onLineFormValuesChange={adapter.getLineWidgetData ? setLineFormValues : undefined}
        canAddLine={canAddLine}
        onAddLine={() => {}}
        onEditLine={() => {}}
        onDeleteLine={handleDeleteLine}
        onDuplicateLine={state.mode !== 'view' ? handleDuplicateLine : undefined}
        lineEditable={template.layout.detail.lineModal?.editable ?? true}
        onLineSave={handleLineSave}
        factBoxSections={factBoxSections}
        conflict={conflictProp}
        forbidden={forbiddenProp}
        crossing={crossingProps}
        loading={state.loading}
        error={state.error}
        busy={state.saving}
      />

      <CurrencySelectorModal
        open={currencyModalOpen}
        currentCode={currencyCode}
        currencies={availableCurrencies}
        loading={currenciesLoading}
        onSelect={handleCurrencySelect}
        onClose={() => setCurrencyModalOpen(false)}
      />

      {activeModalListConfig && adapter.genericFetch && (
        <DocumentModalList
          open={modalListOpen}
          onClose={() => setModalListOpen(false)}
          config={activeModalListConfig}
          documentId={state.documentId}
          lineId={modalListLineId}
          fetcher={adapter.genericFetch.bind(adapter)}
          formatCurrency={adapter.formatCurrency}
          formatDate={adapter.formatDate}
        />
      )}
    </>
  );
}
