import React from 'react';
import { Dropdown } from '../Dropdown/Dropdown';
import { ChevronDownIcon, GlobeAltIcon, BuildingOffice2Icon } from './icons';
import type { MasterCrudCompany } from './MasterCrud.types';

interface CompanySelectorProps {
  companies: MasterCrudCompany[];
  selectedCompany?: MasterCrudCompany;
  onCompanyChange: (company: MasterCrudCompany, ...args: any[]) => void;
  className?: string;
  disabled?: boolean;
  /**
   * Cuando es true, la compañía se muestra como etiqueta estática (sin interacción).
   * Se usa cuando companyRequired=true en MasterCrud: no existe vinculación ni cambio
   * de contexto posible, por lo que un comboBox no aplica.
   * Renderiza un <span> (no un <button>) para que no sea posible habilitarlo desde devtools.
   */
  readOnly?: boolean;
  /** Función de traducción inyectada por el padre */
  t: (key: string, defaultValue?: string) => string;
}

/**
 * CompanySelector - Componente interno para selección de compañía en MasterCrud
 *
 * Implementa el diseño unificado de Siesa para el cambio de contexto de compañía.
 */
export const CompanySelector: React.FC<CompanySelectorProps> = ({
  companies,
  selectedCompany,
  onCompanyChange,
  className = '',
  disabled = false,
  readOnly = false,
  t,
}) => {
  if (!companies.length) return null;

  const pillBaseClasses = `
    flex items-center gap-1 px-[6px] py-[4px] rounded-[6px]
    bg-[#f3e8ff] dark:bg-purple-900/20 border border-purple-200 dark:border-purple-800
    text-[#7e22ce] dark:text-purple-300
  `.replace(/\s+/g, ' ').trim();

  const triggerClasses = `
    ${pillBaseClasses} transition-all focus:outline-none
    ${disabled ? 'opacity-60 cursor-not-allowed' : 'hover:bg-[#ebd5ff] dark:hover:bg-purple-900/40 cursor-pointer'}
  `.replace(/\s+/g, ' ').trim();

  const labelClasses = "text-[12px] font-normal leading-4";

  const iconClasses = "w-3 h-3";

  const isGlobal = !selectedCompany || String(selectedCompany.uuid) === '000';
  const ContextIcon = isGlobal ? GlobeAltIcon : BuildingOffice2Icon;

  const companyLabel = selectedCompany?.name
    || (companies.length > 0 ? t('loading', 'Cargando...') : t('selectCompany', 'Seleccionar Compañía'));

  // ── Modo solo lectura (companyRequired=true en la página de edición) ──────
  // Se usa <span> en lugar de <button> para que no exista ningún elemento
  // interactivo que pueda habilitarse desde las DevTools del navegador.
  if (readOnly) {
    return (
      <div className={`relative inline-block ${className}`}>
        <span className={pillBaseClasses}>
          <BuildingOffice2Icon className={iconClasses} aria-hidden="true" />
          <span className={labelClasses}>{companyLabel}</span>
        </span>
      </div>
    );
  }

  const trigger = (
    <button type="button" className={triggerClasses} disabled={disabled}>
      <ContextIcon className={iconClasses} />
      <span className={labelClasses}>{companyLabel}</span>
      <ChevronDownIcon className={iconClasses} />
    </button>
  );

  return (
    <div className={`relative inline-block ${className}`}>
      {disabled ? (
        trigger
      ) : (
        <Dropdown
          menuClassName="w-72"
          renderTrigger={() => trigger}
          items={companies.map((company) => ({
            children: (
              <div className="flex flex-col py-1">
                <span className="font-bold text-sm text-content-primary dark:text-dark-content-primary leading-tight">
                  {company.name}
                </span>
                <div className="flex items-center gap-2 mt-0.5">
                  <span className="text-[10px] font-medium text-content-tertiary uppercase tracking-wider">
                    {t('code', 'Código')}: {company.code}
                  </span>
                </div>
              </div>
            ),
            onClick: () => onCompanyChange(company),
            className: selectedCompany?.uuid === company.uuid
              ? 'bg-purple-50 dark:bg-purple-900/20'
              : '',
          }))}
        />
      )}
    </div>
  );
};
