/**
 * Catálogo de indicadores económicos externos para el Widget Builder.
 * Solo se incluyen indicadores VERIFICADOS end-to-end (endpoint accesible, respuesta parseable).
 *
 * Estado actual (2026-04-16):
 *   ✅ co_trm  — TRM Colombia, datos.gov.co (Socrata), verificado
 *   ✅ int_btc — Bitcoin USD, CoinGecko, verificado
 *
 * 🗺️ ROADMAP — Pendientes de investigación:
 *   IPC Colombia  → datos.gov.co IDs cambiaron; nueva ruta: suameca.banrep.gov.co (SDMX)
 *   TPM Colombia  → Portal Banrep migró a SDMX; requiere doc de parámetros específicos
 *   FRED (USA/Int) → Verificados estructuralmente (400 = key faltante, no 404), pendiente
 *                    prueba con api_key real (gratuita en fredaccount.stlouisfed.org)
 */

export interface EconomicIndicator {
  id: string;
  bandera: string;
  pais: 'Colombia' | 'USA' | 'Internacional';
  categoria: 'Divisa' | 'Precios' | 'Tasas' | 'Laboral' | 'Macro' | 'Commodities' | 'Cripto';
  nombre: string;
  descripcion: string;
  unidad: string;
  frecuencia: string;
  endpoint: string;
  metodo: 'GET' | 'POST';
  /** Params estáticos que se agregan a la URL (sin api_key — se agrega dinámicamente) */
  params: Record<string, string>;
  /** Path al campo valor en la respuesta (dot-notation, ej: "valor", "observations[0].value") */
  campo_valor: string;
  /** Path al campo fecha en la respuesta */
  campo_fecha: string;
  requiere_key: boolean;
  key_nombre?: string;
  key_url?: string;
  notas?: string;
}

