export function getIndicatorById(id: string): EconomicIndicator | undefined {
  return INDICATORS_CATALOG.find(i => i.id === id);
}

/**
 * Construye la URL completa del indicador con params + api_key opcional.
 *
 * IMPORTANTE: No usa URLSearchParams porque codifica '$' como '%24',
 * lo que rompe las APIs Socrata (datos.gov.co) que requieren '$literal'
 * en parámetros como $limit, $order, $where.
 * Las claves se pasan sin codificar; solo los valores se codifican.
 */
export function buildIndicatorUrl(indicator: EconomicIndicator, apiKey?: string): string {
  const parts: string[] = [];

  for (const [k, v] of Object.entries(indicator.params)) {
    parts.push(`${k}=${encodeURIComponent(v)}`);
  }

  if (indicator.requiere_key && apiKey) {
    parts.push(`api_key=${encodeURIComponent(apiKey)}`);
  }

  if (parts.length === 0) return indicator.endpoint;

  const separator = indicator.endpoint.includes('?') ? '&' : '?';
  return `${indicator.endpoint}${separator}${parts.join('&')}`;
}
