import { clsx } from 'clsx';
import type { StateBadgeProps } from './MasterDocument.types';

/**
 * StateBadge — insignia visual que muestra el estado actual de un documento.
 *
 * Renderiza una etiqueta con colores personalizados (fondo y texto) definidos
 * por la máquina de estados del template. En modo oscuro aplica un filtro
 * de brillo/saturación para mantener la legibilidad.
 *
 * @see MasterDocument.types — `StateBadgeProps` para la definición de colores
 *
 * @example
 * ```tsx
 * <StateBadge label="Aprobado" bg="#d1fae5" color="#065f46" />
 * ```
 */
export function StateBadge({ label, bg, color, className }: StateBadgeProps) {
  return (
    <span
      role="status"
      className={clsx(
        'inline-flex items-center px-[10px] py-[3px] rounded-full text-xs leading-4 font-semibold transition-colors duration-200 select-none',
        'dark:[filter:brightness(0.85)_saturate(1.2)]',
        className,
      )}
      style={{ backgroundColor: bg, color }}
    >
      {label}
    </span>
  );
}
