import { useTranslation } from 'react-i18next'

const FALLBACK_STRINGS: Record<string, string> = {
  placeholder: 'Select...',
  searchPlaceholder: 'Search...',
  noResults: 'No results found',
  loading: 'Loading...',
  minChars: 'Type at least {{count}} characters',
  error: 'An error occurred',
  notFound: '[Record not found]',
  clear: 'Clear selection',
  open: 'Open dropdown',
  close: 'Close dropdown',
  'announcements.loading': 'Loading results',
  'announcements.noResults': 'No results found',
  'announcements.cleared': 'Selection cleared',
  'announcements.opened': 'Dropdown opened, {{count}} results available',
  'announcements.closed': 'Dropdown closed',
  'announcements.selected': '{{value}} selected',
  'announcements.resultsLoaded': '{{count}} results loaded',
  'validation.required': 'This field is required',
  'validation.requiredIndicator': '*',
}

function interpolate(template: string, params?: Record<string, unknown>): string {
  if (!params) return template
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => String(params[key] ?? ''))
}

type TFunction = (key: string, params?: Record<string, unknown>) => string

interface UseTranslationSafeResult {
  t: TFunction
  i18n: ReturnType<typeof useTranslation>['i18n'] | null
}

export function useTranslationSafe(): UseTranslationSafeResult {
  try {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    const { t: i18nT, i18n } = useTranslation('lookupField')
    // If i18n is not initialized, fall back
    if (!i18n.isInitialized) {
      throw new Error('i18n not initialized')
    }
    return {
      t: (key: string, params?: Record<string, unknown>) =>
        params ? i18nT(key, params as Record<string, string | number>) : i18nT(key),
      i18n,
    }
  } catch {
    // Return fallback t function when i18next is not available
    const fallbackT: TFunction = (key: string, params?: Record<string, unknown>) => {
      const template = FALLBACK_STRINGS[key] ?? key
      return interpolate(template, params)
    }
    return { t: fallbackT, i18n: null }
  }
}
