import { clsx } from 'clsx';
import type { Breakpoint, ContextStripProps } from './MasterDocument.types';

/**
 * Mapa breakpoint → clase responsive de Tailwind que oculta el item únicamente
 * dentro de ese rango de ancho. Las cadenas son literales para que el JIT de
 * Tailwind las detecte al hacer build. La franja sólo es visible en `md+`, por lo
 * que `xs`/`sm` rara vez aplican, pero se incluyen por completitud.
 *
 *   md  → 768–1023px   |  lg → 1024–1279px
 *   xl  → 1280–1535px  |  2xl → ≥1536px
 */
const HIDE_ON_BREAKPOINT_CLASS: Record<Breakpoint, string> = {
  xs: 'max-sm:hidden',
  sm: 'sm:max-md:hidden',
  md: 'md:max-lg:hidden',
  lg: 'lg:max-xl:hidden',
  xl: 'xl:max-2xl:hidden',
  '2xl': '2xl:hidden',
};

function hideClasses(breakpoints?: Breakpoint[]): string {
  if (!breakpoints?.length) return '';
  return breakpoints.map((bp) => HIDE_ON_BREAKPOINT_CLASS[bp]).join(' ');
}

/**
 * Franja contextual que muestra campos clave del documento (cliente, vendedor, etc.)
 * en una barra horizontal compacta debajo del ActionBar. Visible solo en md+.
 *
 * Los items reflowean con `flex-wrap`: cuando no caben en una sola línea envuelven
 * a la siguiente (la franja crece en alto) en lugar de solaparse. Los valores largos
 * se truncan con ellipsis y exponen el texto completo en `title`. Cada item puede
 * declarar `hideOnBreakpoints` para esconderse en anchos concretos.
 *
 * @see MasterDocument.types - ContextStripProps / ContextStripItem
 */
export function ContextStrip({ items, currencyPanel, className }: ContextStripProps) {
  if (items.length === 0) return null;

  return (
    <div
      className={clsx(
        'hidden md:flex flex-wrap items-center min-h-12 gap-x-2 gap-y-1',
        'bg-bg-primary border-b border-border-secondary px-4 py-1.5',
        'dark:bg-dark-bg-primary dark:border-dark-border-primary',
        className,
      )}
      role="region"
      aria-label="Contexto del documento"
    >
      <div className="flex flex-wrap items-center gap-y-1 min-w-0">
        {items.map((item, index) => (
          <div
            key={item.label}
            className={clsx('flex items-center min-w-0', hideClasses(item.hideOnBreakpoints))}
          >
            {index > 0 && (
              <div
                className="w-px h-6 bg-border-secondary dark:bg-dark-border-primary mx-3 shrink-0"
                aria-hidden="true"
              />
            )}
            <div className="flex flex-col gap-0 min-w-0 max-w-[14rem]">
              <span className="text-xs font-bold uppercase tracking-tight leading-tight text-content-secondary dark:text-dark-content-secondary truncate">
                {item.label}
              </span>
              <span
                title={item.value}
                className={clsx(
                  'text-sm font-semibold leading-tight truncate',
                  item.accent ? 'text-primary-custom-600 dark:text-primary-custom-500' : 'text-content-primary dark:text-dark-content-primary',
                  item.mono && 'tabular-nums',
                )}
              >
                {item.value}
              </span>
            </div>
          </div>
        ))}
      </div>

      {currencyPanel && (
        <div className="ml-auto shrink-0 pl-4">
          {currencyPanel}
        </div>
      )}
    </div>
  );
}
