import { clsx } from 'clsx';
import type { FactBoxCfdeProps, CfdeStatus } from './MasterDocument.types';

/**
 * Configuración de colores por estado DIAN.
 *
 * Se utilizan colores semánticos de Tailwind (amber, blue, green, red) porque
 * el sistema de tokens actual solo define `error-*`. Cuando se agreguen tokens
 * `success-*`, `warning-*` e `info-*` al sistema, migrar a esos tokens.
 */
const statusConfig: Record<CfdeStatus, { label: string; bg: string; color: string; icon: string }> = {
  PENDING:  { label: 'Pendiente',  bg: 'bg-amber-100 dark:bg-amber-900/20', color: 'text-amber-700 dark:text-amber-400', icon: '⏳' },
  SENT:     { label: 'Enviada',    bg: 'bg-blue-100 dark:bg-blue-900/20',   color: 'text-blue-700 dark:text-blue-400',   icon: '📤' },
  ACCEPTED: { label: 'Aceptada',   bg: 'bg-green-100 dark:bg-green-900/20', color: 'text-green-700 dark:text-green-400', icon: '✓' },
  REJECTED: { label: 'Rechazada',  bg: 'bg-error-bg dark:bg-error-bg/20',   color: 'text-error-content dark:text-error-content', icon: '✗' },
  ERROR:    { label: 'Error',      bg: 'bg-error-bg dark:bg-error-bg/20',   color: 'text-error-content dark:text-error-content', icon: '!' },
};

/**
 * Widget de información DIAN (Factura Electrónica) para el panel FactBox.
 *
 * Muestra el estado de transmisión DIAN con su insignia de color, el número de
 * FE, CUFE, fecha de emisión, contador de impresiones y enlace al QR. Expone
 * acciones de Retransmitir (estados REJECTED/ERROR) y Descargar PDF (estado
 * ACCEPTED) cuando se proveen los callbacks correspondientes.
 *
 * @see docs/colors.md - Sistema de tokens de color
 * @see MasterDocument.types - FactBoxCfdeProps, CfdeStatus
 *
 * @example
 * ```tsx
 * <FactBoxCfde
 *   data={{ status: 'ACCEPTED', number: 'FE-0001', cufe: 'abc123' }}
 *   onDownloadPdf={() => downloadPdf()}
 * />
 * ```
 */
export function FactBoxCfde({ data, onRetransmit, onDownloadPdf, className }: FactBoxCfdeProps) {
  const cfg = statusConfig[data.status];

  return (
    <div className={clsx('flex flex-col gap-2.5', className)}>
      {/* Status badge */}
      <div className="flex items-center justify-between">
        <span className="text-xs text-content-tertiary dark:text-dark-content-secondary">Estado DIAN</span>
        <span
          className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold ${cfg.bg} ${cfg.color}`}
          aria-label={`Estado: ${cfg.label}`}
        >
          <span className="text-[10px]" aria-hidden="true">{cfg.icon}</span>
          {cfg.label}
        </span>
      </div>

      {/* CFDE Number */}
      {data.number && (
        <div className="flex items-center justify-between">
          <span className="text-xs text-content-tertiary dark:text-dark-content-secondary">Número FE</span>
          <span className="text-xs font-semibold text-content-primary dark:text-dark-content-primary">
            {data.number}
          </span>
        </div>
      )}

      {/* CUFE */}
      {data.cufe && (
        <div>
          <span className="text-xs text-content-tertiary dark:text-dark-content-secondary block mb-0.5">CUFE</span>
          <span className="text-[10px] text-content-secondary dark:text-dark-content-secondary break-all leading-relaxed">
            {data.cufe}
          </span>
        </div>
      )}

      {/* Issue date */}
      {data.issueDate && (
        <div className="flex items-center justify-between">
          <span className="text-xs text-content-tertiary dark:text-dark-content-secondary">Fecha emisión</span>
          <span className="text-xs text-content-primary dark:text-dark-content-primary">
            {data.issueDate}
          </span>
        </div>
      )}

      {/* Print count */}
      {data.printCount != null && (
        <div className="flex items-center justify-between">
          <span className="text-xs text-content-tertiary dark:text-dark-content-secondary">Impresiones</span>
          <span className="text-xs font-semibold text-content-primary dark:text-dark-content-primary">
            {data.printCount}
          </span>
        </div>
      )}

      {/* QR link */}
      {data.qrUrl && (
        <a
          href={data.qrUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="text-xs font-semibold text-primary-600 dark:text-primary-400 hover:underline"
        >
          Ver QR DIAN
        </a>
      )}

      {/* Actions */}
      {(onRetransmit || onDownloadPdf) && (
        <div className="flex gap-2 pt-1 border-t border-border-secondary dark:border-dark-border-primary">
          {onRetransmit && (data.status === 'REJECTED' || data.status === 'ERROR') && (
            <button
              type="button"
              onClick={onRetransmit}
              aria-label="Retransmitir documento a la DIAN"
              className="flex-1 text-xs font-semibold text-primary-600 dark:text-primary-400 py-1.5 rounded-md hover:bg-primary-100 dark:hover:bg-primary-600/10 transition-colors"
            >
              Retransmitir
            </button>
          )}
          {onDownloadPdf && data.status === 'ACCEPTED' && (
            <button
              type="button"
              onClick={onDownloadPdf}
              aria-label="Descargar PDF de la factura electrónica"
              className="flex-1 text-xs font-semibold text-primary-600 dark:text-primary-400 py-1.5 rounded-md hover:bg-primary-100 dark:hover:bg-primary-600/10 transition-colors"
            >
              Descargar PDF
            </button>
          )}
        </div>
      )}
    </div>
  );
}
