/**
 * useToast — internal toast abstraction.
 *
 * If the consumer provides a `toast` callback prop, delegates to it.
 * Otherwise falls back to `fireInternalToast` which dispatches a DOM event
 * picked up by `InternalToastContainer` (always mounted inside MasterPatternView).
 *
 * @module hooks/useToast
 * @see FMPV-MVWC-E002-S002 I-005
 */
import { fireInternalToast } from '../components/InternalToastContainer';

export type ToastType = 'success' | 'error' | 'warning' | 'info';
export type ToastCallback = (type: ToastType, message: string) => void;

export interface ToastAPI {
  showSuccess: (message: string) => void;
  showError: (message: string) => void;
  showWarning: (message: string) => void;
  showInfo: (message: string) => void;
}

/**
 * Returns toast notification methods.
 * Delegates to the consumer-provided `toast` callback when available;
 * otherwise fires the internal event bus handled by InternalToastContainer.
 *
 * @param externalToast - Optional toast callback from MasterPatternViewProps
 */
export function useToast(externalToast?: ToastCallback): ToastAPI {
  const dispatch = (type: ToastType, message: string) => {
    if (externalToast) {
      externalToast(type, message);
    } else {
      fireInternalToast(type, message);
    }
  };

  return {
    showSuccess: (message) => dispatch('success', message),
    showError: (message) => dispatch('error', message),
    showWarning: (message) => dispatch('warning', message),
    showInfo: (message) => dispatch('info', message),
  };
}
