import { SerialCapturePanel } from './SerialCapturePanel';
import { SerialSelectPanel } from './SerialSelectPanel';
import type { SerialRow } from '../adapter/MasterDocumentAdapter.types';

export interface SerialCaptureModeProps {
  mode: 'capture';
  /** Códigos de serial capturados. */
  serials: string[];
  required: number;
  readOnly?: boolean;
  /** Error externo (p.ej. `adapter.validateSerial`). */
  externalError?: string | null;
  onChange: (next: string[]) => void;
  className?: string;
}

export interface SerialSelectModeProps {
  mode: 'select';
  /** Seriales disponibles (paginados por el adapter en el kit final). */
  rows: SerialRow[];
  /** IDs seleccionados. */
  value: string[];
  required: number;
  readOnly?: boolean;
  pageSize?: number;
  onChange: (next: string[]) => void;
  className?: string;
  // ── Modo servidor (cableado vía useSerialPanel) ────────────
  /** Búsqueda controlada server-side. */
  query?: string;
  onQueryChange?: (query: string) => void;
  /** Página actual (1-based) controlada server-side. */
  page?: number;
  onPageChange?: (page: number) => void;
  /** Total de registros del lado servidor. */
  total?: number;
  /** Indicador de carga de la página. */
  loading?: boolean;
}

export type SerialPanelProps = SerialCaptureModeProps | SerialSelectModeProps;

/**
 * Panel nativo de seriales del kit. Selecciona la UI según `mode`:
 * - `capture` → entrada por escáner/teclado ([[SerialCapturePanel]]).
 * - `select`  → selección desde inventario ([[SerialSelectPanel]]).
 *
 * Componente presentacional. La activación condicional (`_itemIsSerialized`),
 * la lectura de la cantidad requerida y el cableado del adapter los resuelve el
 * contenedor (`LineFormModal` + hook `useSerialPanel`, paso 2).
 */
export function SerialPanel(props: SerialPanelProps) {
  if (props.mode === 'capture') {
    return (
      <SerialCapturePanel
        serials={props.serials}
        required={props.required}
        readOnly={props.readOnly}
        externalError={props.externalError}
        onChange={props.onChange}
        className={props.className}
      />
    );
  }
  return (
    <SerialSelectPanel
      rows={props.rows}
      value={props.value}
      required={props.required}
      readOnly={props.readOnly}
      pageSize={props.pageSize}
      onChange={props.onChange}
      className={props.className}
      query={props.query}
      onQueryChange={props.onQueryChange}
      page={props.page}
      onPageChange={props.onPageChange}
      total={props.total}
      loading={props.loading}
    />
  );
}
