import React, { createContext, useContext } from 'react';

export interface DynamicEntitiesContextType {
    baseUrl: string;
    onError?: (error: Error) => void;
}

export const DynamicEntitiesContext = createContext<DynamicEntitiesContextType | undefined>(undefined);

export interface DynamicEntitiesProviderProps {
    baseUrl: string;
    onError?: (error: Error) => void;
    children: React.ReactNode;
}

export const DynamicEntitiesProvider: React.FC<DynamicEntitiesProviderProps> = ({ baseUrl, onError, children }) => {
    return (
        <DynamicEntitiesContext.Provider value={{ baseUrl, onError }}>
            {children}
        </DynamicEntitiesContext.Provider>
    );
};

export const useDynamicEntitiesContext = (): DynamicEntitiesContextType => {
    const context = useContext(DynamicEntitiesContext);
    if (!context) {
        throw new Error('useDynamicEntitiesContext must be used within a DynamicEntitiesProvider');
    }
    return context;
};

export const useOptionalDynamicEntitiesContext = (): DynamicEntitiesContextType | undefined => {
    return useContext(DynamicEntitiesContext);
};
