/**
 * FormActionBar — mode-aware action bar for the form panel.
 *
 * Create/Edit mode: "Guardar" (primary) + "Cancelar" (outline)
 * View mode: "Regresar" + "Editar" (primary) + "Solo lectura" badge
 * Edit mode: "Acciones" ≡ dropdown — items vary by company context (mock: form-menu-wrap)
 * Shows dirty indicator (•) in title when isDirty=true.
 *
 * @module components/form/FormActionBar
 * @see FMPV-MVWC-E003-S001 I-003, FMPV-MVWC-E004-S001 I-002
 */
import React, { useState, useCallback, useRef, useEffect } from 'react';
import { Save, X, ArrowLeft, Pencil, Eye, Menu, Plus, Power, Building2, RotateCcw, Globe, ChevronDown } from 'lucide-react';
import { Button } from '../../../Button/Button';
import type { FormMode } from '../../types/internal.types';
import type { MasterPatternViewCompany } from '../../types/service.types';
import { CompanySelector } from '../toolbar/CompanySelector';

export interface FormActionBarProps {
  mode: FormMode;
  title: string;
  isDirty: boolean;
  onSave: () => void;
  onCancel: () => void;
  onEdit: () => void;
  /** Called when user selects "Crear nuevo registro" from hamburger menu (editing mode only) */
  onHamburgerCreate?: () => void;
  /** Called when user selects "Cambiar estado" from hamburger menu (editing mode only) */
  onHamburgerChangeStatus?: () => void;
  /** Called when user selects "Habilitar compañía" (non-UNIVERSAL types only) */
  onHamburgerEnableCompany?: () => void;
  /** Called when user selects "Usar datos globales" (company context only) */
  onHamburgerUseGlobalData?: () => void;
  /** Called when user toggles "Mostrar datos globales" (company context only) */
  onHamburgerToggleShowGlobal?: () => void;
  /** Current state of "Mostrar datos globales" toggle */
  showGlobalValues?: boolean;
  /** Company context — undefined hides the selector (UNIVERSAL) */
  companies?: MasterPatternViewCompany[];
  activeCompanyId?: string;
  onCompanyChange?: (company: MasterPatternViewCompany) => void;
  definitionType?: string;
  /** Current record's active status — shown as badge next to company selector */
  recordIsActive?: boolean;
  /** Compact mode: renders action buttons icon-only (no labels) to save horizontal space (sidebar) */
  compact?: boolean;
  /** Disables the Guardar button — used when the full record failed to load from the server. */
  saveDisabled?: boolean;
  /** Disables the company selector — prevents company switching in certain contexts. */
  companyDisabled?: boolean;
  /** Hides the Editar button completely in view mode. */
  editHidden?: boolean;
  /** Renders the Editar button as disabled (grayed out, not clickable) in view mode. */
  editGrayed?: boolean;
  /** Tooltip text shown on the grayed-out Editar button to explain why editing is unavailable. */
  editGrayedReason?: string;
}


export function FormActionBar({
  mode,
  title,
  isDirty,
  onSave,
  onCancel,
  onEdit,
  onHamburgerCreate,
  onHamburgerChangeStatus,
  onHamburgerEnableCompany,
  onHamburgerUseGlobalData,
  onHamburgerToggleShowGlobal,
  showGlobalValues = false,
  companies,
  activeCompanyId,
  onCompanyChange,
  definitionType,
  recordIsActive,
  compact = false,
  saveDisabled = false,
  companyDisabled = false,
  editHidden = false,
  editGrayed = false,
  editGrayedReason,
}: FormActionBarProps) {
  const displayTitle = isDirty ? `• ${title}` : title;
  const isViewing = mode === 'viewing';
  const isEditing = mode === 'editing';
  const showCompany = definitionType !== 'UNIVERSAL';

  // "company context" = a specific company is selected (not global / not UNIVERSAL)
  const isCompanyContext = showCompany && !!activeCompanyId && activeCompanyId !== 'global';

  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  const toggleMenu = useCallback(() => setMenuOpen((v) => !v), []);

  const close = useCallback((fn?: () => void) => {
    setMenuOpen(false);
    fn?.();
  }, []);

  useEffect(() => {
    if (!menuOpen) return;
    const handler = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [menuOpen]);

  return (
    <div className="flex items-start gap-2 px-5 pt-3.5 pb-2">
      <div className="flex flex-col gap-1.5 flex-1 min-w-0">
        <span data-testid="form-title" className="text-xl font-semibold text-[#1355b7] tracking-tight leading-7">
          {displayTitle}
        </span>
        {/* Meta row: company context + status badge + readonly badge */}
        <div className="flex items-center gap-2 flex-wrap">
          {showCompany && (
            <CompanySelector
              companies={companies ?? []}
              activeCompanyId={activeCompanyId}
              onCompanyChange={onCompanyChange ?? (() => {})}
              showGlobalOption={definitionType === 'GLOBAL'}
              disabled={companyDisabled}
            />
          )}
          {recordIsActive !== undefined && (
            <span
              data-testid="form-status-badge"
              className={`px-2 py-0.5 rounded text-[11px] font-semibold ${
                recordIsActive
                  ? 'bg-[#ecfccb] text-[#4d7c0f]'
                  : 'bg-[#d4d4d8] text-[#52525b] dark:bg-dark-bg-secondary dark:text-dark-content-secondary'
              }`}
            >
              {recordIsActive ? 'Activo' : 'Inactivo'}
            </span>
          )}
          {isViewing && (
            <span
              data-testid="form-readonly-badge"
              className="flex items-center gap-1 px-2 py-0.5 rounded bg-background-secondary dark:bg-dark-bg-secondary text-content-tertiary dark:text-dark-content-tertiary text-[11px] font-bold w-fit"
            >
              <Eye size={11} />
              Solo lectura
            </span>
          )}
        </div>
      </div>

      {/* "Acciones" ≡ menu — edit mode only (mock: form-menu-wrap) */}
      {isEditing && (
        <div className="relative flex-shrink-0" ref={menuRef}>
          <button
            type="button"
            data-testid="form-hamburger-button"
            onClick={toggleMenu}
            aria-haspopup="true"
            aria-expanded={menuOpen}
            title="Acciones"
            className="inline-flex items-center gap-2 px-3 h-9 rounded-md border text-sm font-bold cursor-pointer transition-all bg-background-secondary dark:bg-dark-bg-secondary border-border-primary dark:border-dark-border-primary text-content-tertiary dark:text-dark-content-tertiary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary"
          >
            <Menu size={14} />
            {!compact && 'Acciones'}
            {!compact && <ChevronDown size={12} className={`transition-transform ${menuOpen ? 'rotate-180' : ''}`} />}
          </button>

          {menuOpen && (
            <div
              data-testid="form-hamburger-menu"
              className="absolute right-0 top-full mt-1 bg-bg-primary dark:bg-dark-bg-primary rounded-md border border-border-primary dark:border-dark-border-primary shadow-md z-50 min-w-[250px] py-1"
            >
              {/* GLOBAL-only items: override controls and company assignment */}
              {definitionType === 'GLOBAL' && (
                <>
                  {isCompanyContext && (
                    <>
                      <button
                        type="button"
                        data-testid="form-hamburger-use-global"
                        className="w-full flex items-center gap-2 px-3 py-2 text-sm text-content-primary dark:text-dark-content-primary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary cursor-pointer"
                        onClick={() => close(onHamburgerUseGlobalData)}
                      >
                        <RotateCcw size={13} />
                        Usar datos globales
                      </button>
                      <button
                        type="button"
                        data-testid="form-hamburger-show-global"
                        className="w-full flex items-center justify-between gap-2 px-3 py-2 text-sm text-content-primary dark:text-dark-content-primary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary cursor-pointer"
                        onClick={() => close(onHamburgerToggleShowGlobal)}
                      >
                        <span className="flex items-center gap-2 whitespace-nowrap">
                          <Globe size={13} />
                          Mostrar datos globales
                        </span>
                        {/* Toggle — pixel-exact match to mock .dd-toggle-track / .dd-toggle-thumb */}
                        <span style={{
                          width: 28, height: 16, borderRadius: 8, flexShrink: 0,
                          background: showGlobalValues
                            ? 'var(--text-color-primary-custom-600)'
                            : 'var(--color-border-primary)',
                          position: 'relative', display: 'inline-block',
                          transition: 'background .2s',
                        }}>
                          <span style={{
                            width: 12, height: 12, borderRadius: '50%',
                            background: 'var(--color-bg-primary)',
                            position: 'absolute', top: 2,
                            left: showGlobalValues ? 14 : 2,
                            transition: 'left .15s',
                            boxShadow: '0 1px 2px rgba(0,0,0,.2)',
                          }} />
                        </span>
                      </button>
                      <hr className="my-1 border-border-primary dark:border-dark-border-primary" />
                    </>
                  )}
                  <button
                    type="button"
                    data-testid="form-hamburger-enable-company"
                    className="w-full flex items-center gap-2 px-3 py-2 text-sm text-content-primary dark:text-dark-content-primary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary cursor-pointer"
                    onClick={() => close(onHamburgerEnableCompany)}
                  >
                    <Building2 size={13} />
                    Habilitar compañía
                  </button>
                </>
              )}

              <button
                type="button"
                data-testid="form-hamburger-create"
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-content-primary dark:text-dark-content-primary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary cursor-pointer"
                onClick={() => close(onHamburgerCreate)}
              >
                <Plus size={13} />
                Crear nuevo registro
              </button>

              <hr className="my-1 border-border-primary dark:border-dark-border-primary" />

              <button
                type="button"
                data-testid="form-hamburger-change-status"
                className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#dc2626] hover:bg-background-secondary dark:hover:bg-dark-bg-secondary cursor-pointer"
                onClick={() => close(onHamburgerChangeStatus)}
              >
                <Power size={13} />
                {recordIsActive ? 'Desactivar' : 'Activar'}
              </button>
            </div>
          )}
        </div>
      )}

      <div className="flex items-center gap-2">
        {isViewing ? (
          <>
            <Button type="outline" size="l" leftIcon={<ArrowLeft size={14} />} data-testid="form-back-button" title="Regresar" onClick={onCancel}>
              {!compact && 'Regresar'}
            </Button>
            {!editHidden && (
              <Button
                type="default"
                size="l"
                leftIcon={<Pencil size={14} />}
                data-testid="form-edit-button"
                title={editGrayed ? (editGrayedReason ?? 'Editar no disponible') : 'Editar'}
                disabled={editGrayed}
                onClick={onEdit}
              >
                {!compact && 'Editar'}
              </Button>
            )}
          </>
        ) : (
          <>
            <Button type="outline" size="l" leftIcon={<X size={14} />} data-testid="form-cancel-button" title="Cancelar" onClick={onCancel}>
              {!compact && 'Cancelar'}
            </Button>
            <Button type="default" size="l" leftIcon={<Save size={14} />} data-testid="form-save-button" title="Guardar" onClick={onSave} disabled={saveDisabled}>
              {!compact && 'Guardar'}
            </Button>
          </>
        )}
      </div>
    </div>
  );
}
