/**
 * TableHeader - Componente para el header de una columna
 */
const TableHeader = <T,>({
  column,
  sortable,
  sorted,
  sortDirection,
  onSort,
}: TableHeaderProps<T>) => {
  // Clases base del header
  const baseClasses = `
    flex
    items-center
    gap-3
    px-4 py-2.5 min-h-[40px]
    w-full
    border-b
    border-border-primary
    dark:border-dark-border-primary
    transition-colors
    duration-150
  `;

  // Clases según sortable
  const sortableClasses = sortable
    ? `
      cursor-pointer
      hover:bg-background-secondary
      dark:hover:bg-dark-bg-primary/50
      select-none
    `
    : '';

  // Clases de alineación del contenedor flex
  const alignClasses = {
    left: 'justify-start',
    center: 'justify-center',
    right: 'justify-end',
  };

  // Clases de alineación interna del span de contenido del header
  // Necesario porque flex-1 ocupa todo el ancho y justify-* del padre no centra el contenido interno
  const spanAlignClasses = {
    left: '',
    center: 'flex justify-center items-center',
    right: 'flex justify-end items-center',
  };

  // Clases según stickyRight
  const stickyClasses = column.stickyRight
    ? 'sticky right-0 z-10 bg-white dark:bg-dark-bg-primary shadow-[-2px_0_5px_rgba(0,0,0,0.05)]'
    : '';

  const combinedClasses = [baseClasses, sortableClasses, stickyClasses, alignClasses[column.align || 'left']]
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();

  return (
    <div
      className={combinedClasses}
      onClick={sortable ? onSort : undefined}
      role={sortable ? 'button' : undefined}
      tabIndex={sortable ? 0 : undefined}
      onKeyDown={
        sortable
          ? (e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onSort();
              }
            }
          : undefined
      }
    >
      {/* Texto del header */}
      <span
        className={`
          flex-1
          min-w-0
          text-sm
          font-semibold
          text-content-primary
          dark:text-dark-content-primary
          text-ellipsis
          overflow-hidden
          whitespace-nowrap
          ${spanAlignClasses[column.align || 'left']}
        `}
      >
        {column.header}
      </span>

      {/* Iconos de sort */}
      {sortable && (
        <span className={`shrink-0 transition-colors duration-150 ${
          sorted
            ? 'text-primary-custom-600 dark:text-primary-custom-600'
            : 'text-content-secondary dark:text-content-secondary opacity-40'
        }`}>
          {sorted && sortDirection === 'asc' && <ChevronUpIcon />}
          {sorted && sortDirection === 'desc' && <ChevronDownIcon />}
          {!sorted && <ChevronUpDownIcon />}
        </span>
      )}
    </div>
  );
};

/**
 * TableCell - Componente para una celda de datos
 */
const TableCell: React.FC<TableCellProps & {
  isStriped?: boolean;
  rowIndex?: number;
  isStickyRight?: boolean;
  className?: string;
  isSelected?: boolean;
  isFirst?: boolean;
  isLast?: boolean;
}> = ({
  children,
  align = 'left',
  width,
  isStriped = false,
  rowIndex = 0,
  isStickyRight = false,
  className = '',
  isSelected = false,
  isFirst = false,
  isLast = false,
}) => {
  // Clases de alineación horizontal
  const alignClasses = {
    left: 'justify-start',
    center: 'justify-center',
    right: 'justify-end',
  };

  // Lógica de fondo: prioridad selección > zebra > base
  const bgClass = isSelected
    ? 'bg-[#f7fcff] dark:bg-primary-900/20'
    : isStriped && rowIndex % 2 === 1
      ? 'bg-background-secondary dark:bg-dark-bg-primary/30'
      : 'bg-white dark:bg-dark-bg-primary';

  // Clases para sticky column
  const stickyClasses = isStickyRight
    ? 'sticky right-0 z-10 shadow-[-2px_0_5px_rgba(0,0,0,0.05)]'
    : '';

  // Redondeo solo si está seleccionado
  const roundedClasses = isSelected
    ? `${isFirst ? 'rounded-l-lg' : ''} ${isLast ? 'rounded-r-lg' : ''}`
    : '';

  return (
    <div
      className={`
        flex
        items-center
        ${alignClasses[align]}
        px-4 py-4 min-h-[56px]
        w-full
        ${isSelected ? 'border-b-transparent' : 'border-b border-border-secondary dark:border-dark-border-primary'}
        ${bgClass}
        ${stickyClasses}
        ${roundedClasses}
        ${!isSelected ? 'group-hover:bg-[#f9fafb] dark:group-hover:bg-white/[0.02]' : ''}
        transition-colors
        duration-150
        ${className}
      `}
    >
      <div
        className={`
          text-sm
          text-content-primary
          dark:text-dark-content-primary
          flex
          ${alignClasses[align]}
          w-full
        `}
      >
        {children}
      </div>
    </div>
  );
};


/**
 * Pagination - Componente de paginación
 */
const Pagination: React.FC<PaginationProps> = ({
  currentPage,
  totalPages,
  onPageChange,
  previousLabel = 'Anterior',
  nextLabel = 'Siguiente',
  pageSize,
  pageSizeOptions,
  onPageSizeChange,
  totalRecords,
  perPageLabel = 'por pág.',
  recordsLabel = 'registros',
  goToPageLabel = 'Pág.',
}) => {
  const [goToValue, setGoToValue] = useState('');

  const showExtras = !!(pageSizeOptions && pageSizeOptions.length > 0 && onPageSizeChange && pageSize);
  const multiPage = totalPages > 1;

  // ===== LÓGICA DE NÚMEROS DE PÁGINA =====
  const getPageNumbers = () => {
    const pages: (number | string)[] = [];
    const maxVisible = 7;
    if (totalPages <= maxVisible) {
      for (let i = 1; i <= totalPages; i++) pages.push(i);
    } else {
      pages.push(1);
      if (currentPage <= 3) {
        pages.push(2, 3);
      } else if (currentPage >= totalPages - 2) {
        pages.push('...');
        pages.push(totalPages - 2, totalPages - 1);
      } else {
        pages.push('...');
        pages.push(currentPage);
        pages.push('...');
      }
      if (totalPages > 1) pages.push(totalPages);
    }
    return pages;
  };

  const pageNumbers = getPageNumbers();

  // ===== IR A PÁGINA =====
  const handleGoTo = () => {
    const n = parseInt(goToValue, 10);
    if (!isNaN(n) && n >= 1 && n <= totalPages) onPageChange(n);
    setGoToValue('');
  };

  // ===== TOKEN DE ESTILOS — idéntico para botones y controles =====
  // Todos los elementos interactivos de la barra comparten: color, peso, hover y transición.
  const interactiveBase = `
    text-sm font-semibold
    text-primary-600 dark:text-primary-600
    hover:bg-blue-50 dark:hover:bg-blue-900/20
    transition-colors duration-150
  `;

  // Botones de navegación (Anterior / Siguiente)
  const navBtnCls = `
    ${interactiveBase}
    flex items-center gap-1.5 px-3 py-1.5 rounded-md
    disabled:opacity-40 disabled:cursor-not-allowed
  `;

  // Número de página activo
  const pageActiveCls = `
    flex items-center justify-center min-w-[32px] px-2 py-1.5 rounded-md
    text-sm font-semibold text-primary-600 dark:text-primary-600
    bg-blue-100 dark:bg-blue-900/30
    transition-colors duration-150
  `;

  // Número de página inactivo
  const pageInactiveCls = `
    flex items-center justify-center min-w-[32px] px-2 py-1.5 rounded-md
    text-sm font-semibold text-primary-600 dark:text-primary-600
    hover:bg-blue-50 dark:hover:bg-blue-900/20
    transition-colors duration-150
  `;

  // Select e Input: mismo color/peso/hover que los botones.
  // Borde azul sutil para affordance (indica que son interactivos), fondo transparente.
  const formControlCls = `
    ${interactiveBase}
    bg-transparent
    border border-blue-200 dark:border-blue-800/60
    rounded-md py-1.5
    focus:outline-none focus:border-primary-custom-400 dark:focus:border-dark-border-custom
    disabled:opacity-40 disabled:cursor-not-allowed
    cursor-pointer
  `;

  // ===== SECCIÓN DE NAVEGACIÓN (compartida) =====
  const navSection = (
    <div className="flex items-center">
      <button
        onClick={() => currentPage > 1 && onPageChange(currentPage - 1)}
        disabled={!multiPage || currentPage === 1}
        className={navBtnCls}
      >
        <ArrowLeftIcon />
        <span>{previousLabel}</span>
      </button>

      {multiPage && (
        <div className="flex items-center">
          {pageNumbers.map((page, index) =>
            page === '...' ? (
              <span
                key={`ellipsis-${index}`}
                className="flex items-center justify-center px-2 py-1.5 text-sm font-semibold text-primary-600 dark:text-primary-600 select-none"
              >
                …
              </span>
            ) : (
              <button
                key={page}
                onClick={() => onPageChange(page as number)}
                className={page === currentPage ? pageActiveCls : pageInactiveCls}
              >
                {page}
              </button>
            )
          )}
        </div>
      )}

      <button
        onClick={() => currentPage < totalPages && onPageChange(currentPage + 1)}
        disabled={!multiPage || currentPage === totalPages}
        className={navBtnCls}
      >
        <span>{nextLabel}</span>
        <ArrowRightIcon />
      </button>
    </div>
  );

  // ===== LAYOUT CON EXTRAS =====
  if (showExtras) {
    return (
      <div className="flex items-center justify-between w-full gap-4 flex-wrap">

        {/* IZQUIERDA — Selector de registros por página + total */}
        <div className="flex items-center gap-1.5 flex-none">
          {/* Wrapper relativo para superponer el chevron sobre el select nativo */}
          <div className="relative flex items-center">
            <select
              value={pageSize}
              onChange={(e) => onPageSizeChange!(Number(e.target.value))}
              aria-label="Registros por página"
              className={`${formControlCls} appearance-none pl-2.5 pr-7`}
            >
              {pageSizeOptions!.map((size) => (
                <option key={size} value={size}>{size}</option>
              ))}
            </select>
            {/* Chevron superpuesto — usa currentColor = text-primary-600 */}
            <span className="absolute right-1.5 pointer-events-none flex items-center text-primary-600 dark:text-primary-600">
              <ChevronDownIcon />
            </span>
          </div>
          <span className="text-sm font-semibold text-primary-600 dark:text-primary-600 whitespace-nowrap">
            {perPageLabel}
          </span>
          {totalRecords !== undefined && (
            <>
              <span className="text-content-secondary dark:text-content-secondary select-none px-0.5">·</span>
              <span className="text-sm text-content-secondary dark:text-content-secondary whitespace-nowrap">
                {totalRecords.toLocaleString()} {recordsLabel}
              </span>
            </>
          )}
        </div>

        {/* CENTRO — Navegación */}
        {navSection}

        {/* DERECHA — Ir a página */}
        <div className="flex items-center gap-1.5 flex-none">
          <span className="text-sm font-semibold text-primary-600 dark:text-primary-600 whitespace-nowrap">
            {goToPageLabel}
          </span>
          <input
            type="number"
            min={1}
            max={totalPages || 1}
            value={goToValue}
            onChange={(e) => setGoToValue(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') handleGoTo(); }}
            onBlur={handleGoTo}
            placeholder={String(currentPage)}
            disabled={!multiPage}
            aria-label="Ir a página"
            className={`${formControlCls} w-12 text-center px-1.5`}
          />
        </div>
      </div>
    );
  }

  // ===== LAYOUT ORIGINAL (sin extras — backward compatible) =====
  return (
    <div className="flex items-center justify-between w-full h-9">
      <button
        onClick={() => currentPage > 1 && onPageChange(currentPage - 1)}
        disabled={currentPage === 1}
        className={navBtnCls}
      >
        <ArrowLeftIcon />
        <span>{previousLabel}</span>
      </button>

      <div className="flex items-center">
        {pageNumbers.map((page, index) =>
          page === '...' ? (
            <span key={`ellipsis-${index}`} className="flex items-center justify-center px-3 py-2 text-sm font-semibold text-primary-600 dark:text-primary-600">
              {page}
            </span>
          ) : (
            <button
              key={page}
              onClick={() => onPageChange(page as number)}
              className={`flex items-center justify-center px-3 py-2 rounded-md text-sm font-semibold text-primary-600 dark:text-primary-600 transition-colors duration-150 ${page === currentPage ? 'bg-blue-100 dark:bg-blue-900/30' : 'hover:bg-blue-50 dark:hover:bg-blue-900/20'}`}
            >
              {page}
            </button>
          )
        )}
      </div>

      <button
        onClick={() => currentPage < totalPages && onPageChange(currentPage + 1)}
        disabled={currentPage === totalPages}
        className={navBtnCls}
      >
        <span>{nextLabel}</span>
        <ArrowRightIcon />
      </button>
    </div>
  );
};

/**
 * Table - Componente principal de tabla
 *
 * Características implementadas:
 * - Definición de columnas flexible con accessor y render custom
 * - Sorting en columnas (controlado o no controlado)
 * - Variantes: basic, fullWidth, striped, grid
 * - Dark mode completo en todos los estados
 * - Estados de loading y empty
 * - Filas clickeables
 * - Accesibilidad con roles y keyboard navigation
 *
 * Mejores prácticas implementadas:
 * - Orden de modificadores: {responsive}:{dark}:{state}:{utility}
 * - Dark mode con estrategia 'class' (darkMode: 'class')
 * - Tokens de color consistentes con la documentación
 * - Type safety con TypeScript estricto y generics
 * - Accesibilidad con ARIA labels y keyboard support
 *
 * @see docs/colors.md - Sistema de colores
 * @see docs/typography.md - Sistema tipográfico (Label/Small para headers, Paragraph/Small para cells)
 * @see docs/spacing.md - Sistema de espaciado
 * @see docs/shadows.md - Sistema de sombras
 *
 * @example
 * ```tsx
 * // Uso básico
 * <Table
 *   title="Usuarios"
 *   columns={[
 *     { header: 'Nombre', accessor: 'name' },
 *     { header: 'Email', accessor: 'email' },
 *     { header: 'Rol', accessor: 'role', sortable: true },
 *   ]}
 *   data={users}
 * />
 *
 * // Con render custom
 * <Table
 *   columns={[
 *     {
 *       header: 'Estado',
 *       accessor: 'status',
 *       render: (value) => (
 *         <Badge color={value === 'active' ? 'green' : 'red'}>
 *           {value}
 *         </Badge>
 *       ),
 *     },
 *   ]}
 *   data={data}
 * />
 *
 * // Variante striped
 * <Table
 *   variant="striped"
 *   columns={columns}
 *   data={data}
 * />
 * ```
 */
export const Table = <T extends Record<string, any>>({
  title,
  columns,
  data,
  variant = 'basic',
  showBorder = true,
  showShadow = true,
  showPadding = true,
  // onRowClick, // TODO: Implement row click functionality
  onSort,
  sortColumn: externalSortColumn,
  sortDirection: externalSortDirection,
  fullWidth = false,
  emptyMessage = 'No hay datos disponibles',
  loading = false,
  loadingRows = 5,
  pagination,
  isRowSelected,
  className = '',
  id,
}: TableProps<T>) => {
  // ===== ESTADO INTERNO DE SORT =====
  const [internalSortColumn, setInternalSortColumn] = useState<keyof T | string | null>(null);
  const [internalSortDirection, setInternalSortDirection] = useState<SortDirection>(null);

  // Usar sort externo si está controlado, sino usar interno
  const sortColumn = externalSortColumn !== undefined ? externalSortColumn : internalSortColumn;
  const sortDirection = externalSortDirection !== undefined ? externalSortDirection : internalSortDirection;

  // ===== MANEJAR SORT =====
  const handleSort = (columnAccessor: keyof T | string) => {
    let newDirection: SortDirection = 'asc';

    // Si ya está ordenado por esta columna, cambiar dirección
    if (sortColumn === columnAccessor) {
      if (sortDirection === 'asc') {
        newDirection = 'desc';
      } else if (sortDirection === 'desc') {
        newDirection = null;
      }
    }

    // Si sort es controlado, llamar callback
    if (onSort) {
      onSort(columnAccessor, newDirection);
    } else {
      // Sino, actualizar estado interno
      setInternalSortColumn(newDirection ? columnAccessor : null);
      setInternalSortDirection(newDirection);
    }
  };

  // ===== OBTENER VALOR DE CELDA =====
  const getCellValue = (row: T, accessor: keyof T | ((row: T) => any)) => {
    if (typeof accessor === 'function') {
      return accessor(row);
    }
    return row[accessor];
  };

  // ===== CLASES DEL CONTAINER =====
  const containerBaseClasses = `
    flex
    flex-col
    gap-4
    bg-white
    dark:bg-dark-bg-primary
    rounded-xl
    transition-all
    duration-150
  `;

  const containerBorderClasses = showBorder
    ? 'border border-border-primary dark:border-dark-border-primary'
    : '';

  const containerShadowClasses = showShadow ? 'shadow-base' : '';

  const containerPaddingClasses = showPadding ? 'p-8' : 'p-0';

  const containerWidthClasses = fullWidth || variant === 'fullWidth' ? 'w-full' : '';

  const containerClasses = [
    containerBaseClasses,
    containerBorderClasses,
    containerShadowClasses,
    containerPaddingClasses,
    containerWidthClasses,
    className,
  ]
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();

  // ===== CLASES DE LA TABLA =====
  const tableGridClasses = variant === 'grid'
    ? `
      border
      border-border-primary
      dark:border-dark-border-primary
      rounded-lg
      overflow-hidden
    `
    : '';

  // ===== RENDER =====
  return (
    <div className={containerClasses} id={id}>
      {/* Título opcional */}
      {title && (
        <div className="flex items-center justify-center w-full">
          <h3
            className="
              text-base
              font-semibold
              text-content-primary
              dark:text-dark-content-primary
              text-ellipsis
              overflow-hidden
              whitespace-nowrap
            "
          >
            {title}
          </h3>
        </div>
      )}

      {/* Tabla */}
      <div
        className={`grid overflow-x-auto ${tableGridClasses}`}
        style={{
          display: 'grid',
          width: '100%',
          minWidth: '100%',
          gridTemplateColumns: columns.map(c => {
            const width = c.width || '1fr';
            const widthStr = String(width);
            
            // Si el ancho no es flexible (fr, %) ni es 'auto', 
            // lo transformamos en minmax para forzar expansión.
            if (!widthStr.includes('fr') && !widthStr.includes('%') && widthStr !== 'auto') {
              const finalWidth = /^\d+$/.test(widthStr) ? `${widthStr}px` : widthStr;
              return `minmax(${finalWidth}, 1fr)`;
            }
            return width;
          }).join(' '),
        }}
      >
        {/* Headers */}
        {columns.map((column, colIndex) => {
          const accessor = typeof column.accessor === 'function'
            ? `column_${colIndex}`
            : String(column.accessor);

          return (
            <TableHeader
              key={`header-${accessor}`}
              column={column}
              sortable={column.sortable || false}
              sorted={sortColumn === accessor}
              sortDirection={sortColumn === accessor ? sortDirection : null}
              onSort={() => handleSort(accessor)}
            />
          );
        })}

        {/* Loading skeleton */}
        {loading && (
          <>
            {Array.from({ length: loadingRows }).map((_, rowIndex) => (
              columns.map((column, colIndex) => {
                const accessor = typeof column.accessor === 'function'
                  ? `column_${colIndex}`
                  : String(column.accessor);

                return (
                  <TableCell
                    key={`loading-${rowIndex}-${accessor}`}
                    align={column.align}
                    isStriped={variant === 'striped'}
                    rowIndex={rowIndex}
                  >
                    <div
                      className="
                        h-4
                        w-full
                        bg-background-secondary
                        dark:bg-dark-border-primary
                        rounded
                        animate-pulse
                      "
                    />
                  </TableCell>
                );
              })
            ))}
          </>
        )}

        {/* Datos reales */}
        {!loading && data.length > 0 && (
          <>
            {data.map((row, rowIndex) => {
              const isSelected = isRowSelected?.(row, rowIndex);
              return (
                <div key={`row-${rowIndex}`} className="contents group">
                  {columns.map((column, colIndex) => {
                    const accessor = typeof column.accessor === 'function'
                      ? `column_${colIndex}`
                      : String(column.accessor);
                    const value = getCellValue(row, column.accessor);
                    const content = column.render
                      ? column.render(value, row, rowIndex)
                      : value;

                    return (
                      <TableCell
                        key={`cell-${rowIndex}-${accessor}`}
                        align={column.align}
                        isStriped={variant === 'striped'}
                        rowIndex={rowIndex}
                        isStickyRight={column.stickyRight}
                        isSelected={isSelected}
                        isFirst={colIndex === 0}
                        isLast={colIndex === columns.length - 1}
                      >
                        {content}
                      </TableCell>
                    );
                  })}
                </div>
              );
            })}
          </>
        )}

        {/* Estado empty */}
        {!loading && data.length === 0 && (
          <div
            className="
              flex
              items-center
              justify-center
              px-6
              py-12
              text-sm
              text-content-secondary
              dark:text-content-secondary
            "
            style={{ gridColumn: `1 / ${columns.length + 1}` }}
          >
            {emptyMessage}
          </div>
        )}
      </div>

      {/* Paginación */}
      {pagination && (
        <div className={!showPadding ? 'p-4 border-t border-border-secondary dark:border-dark-border-primary' : ''}>
          <Pagination
            currentPage={pagination.currentPage}
            totalPages={pagination.totalPages}
            onPageChange={pagination.onPageChange}
            previousLabel={pagination.previousLabel}
            nextLabel={pagination.nextLabel}
            pageSize={pagination.pageSize}
            pageSizeOptions={pagination.pageSizeOptions}
            onPageSizeChange={pagination.onPageSizeChange}
            totalRecords={pagination.totalRecords}
            perPageLabel={pagination.perPageLabel}
            recordsLabel={pagination.recordsLabel}
            goToPageLabel={pagination.goToPageLabel}
          />
        </div>
      )}
    </div>
  );
};
