import React, { useMemo } from 'react';
import { Responsive as ResponsiveGridLayoutOriginal } from 'react-grid-layout';
import type { Layout, LayoutItem } from 'react-grid-layout';
import 'react-grid-layout/css/styles.css';
import 'react-resizable/css/styles.css';

import { withResponsiveWidth } from '../components/DashboardEngine/components/WidthProviderHOC';
import type { UserWidgetPreferenceBase, WidgetDefinitionBase } from '../components/DashboardEngine/types';

// Envolvemos el grid responsivo con nuestro HOC a prueba de memory leaks (Vite 8 fix)
const ResponsiveGrid = withResponsiveWidth(ResponsiveGridLayoutOriginal);

interface DashboardGridProps<
  TPreference extends UserWidgetPreferenceBase = UserWidgetPreferenceBase,
  TDefinition extends WidgetDefinitionBase = WidgetDefinitionBase
> {
  layout: TPreference[];
  catalog: TDefinition[];
  isEditMode: boolean;
  globalFilters: Record<string, unknown>;
  onLayoutChange: (newLayout: TPreference[]) => void;
  onRemoveWidget: (id: string) => void;
  renderWidget: (
    preference: TPreference,
    definition: TDefinition,
    isEditMode: boolean,
    globalFilters: Record<string, unknown>,
    onRemove: (id: string) => void
  ) => React.ReactNode;
}

export const DashboardGrid = <
  TPreference extends UserWidgetPreferenceBase,
  TDefinition extends WidgetDefinitionBase
>({
  layout,
  catalog,
  isEditMode,
  globalFilters,
  onLayoutChange,
  onRemoveWidget,
  renderWidget
}: DashboardGridProps<TPreference, TDefinition>) => {
  const gridLayouts = useMemo(() => {
    const validLayouts: LayoutItem[] = layout.map(pref => {
      const def = catalog.find(c => c.widget_id === pref.widget_id);
      return {
        i: pref.id,
        x: pref.pos_x,
        y: pref.pos_y,
        w: pref.col_span,
        h: pref.row_span,
        minW: def?.col_min || 2,
        maxW: def?.col_max || 12,
        isDraggable: isEditMode,
        isResizable: isEditMode,
      };
    });

    return { lg: validLayouts, md: validLayouts };
  }, [layout, catalog, isEditMode]);

  const handleLayoutChange = (currentLayout: Layout) => {
    if (!isEditMode) return;

    const updatedPreferences = layout.map(pref => {
      const gridItem = currentLayout.find(item => item.i === pref.id);
      if (gridItem) {
        return {
          ...pref,
          pos_x: gridItem.x,
          pos_y: gridItem.y,
          col_span: gridItem.w,
          row_span: gridItem.h,
          modificado_en: new Date().toISOString()
        } as TPreference;
      }
      return pref;
    });

    onLayoutChange(updatedPreferences);
  };

  return (
    <div className={`min-h-[500px] transition-all duration-300 ${isEditMode ? 'bg-gray-50/50 rounded-xl outline outline-2 outline-dashed outline-gray-200' : ''}`}>
      <ResponsiveGrid
        className="layout"
        layouts={gridLayouts}
        measureBeforeMount={true}
        breakpoints={{ lg: 1280, md: 992, sm: 768, xs: 480, xxs: 0 }}
        cols={{ lg: 12, md: 12, sm: 6, xs: 4, xxs: 2 }}
        rowHeight={148}
        margin={[12, 12]}
        onLayoutChange={handleLayoutChange}
        isDraggable={isEditMode}
        isResizable={isEditMode}
        draggableHandle=".drag-handle"
        compactType="vertical"
        useCSSTransforms={true}
      >
        {layout.map(pref => {
          const definition = catalog.find(c => c.widget_id === pref.widget_id);
          if (!definition) return <div key={pref.id}>Widget desconocido</div>;

          return (
            <div key={pref.id}>
              {renderWidget(pref, definition, isEditMode, globalFilters, onRemoveWidget)}
            </div>
          );
        })}
      </ResponsiveGrid>
    </div>
  );
};
