/**
 * Thin wrapper shim around `cmdk` (the shadcn `Command` primitive).
 *
 * Re-exports the named subcomponents so the FormCacheSelector imports them
 * from `lib/ui/command`. Lets tests mock a single module instead of cmdk's
 * internals, and decouples future swaps to a Kit-provided combobox.
 *
 * All exports are forwardRef wrappers that apply shadcn-style Tailwind classes
 * so the combobox renders with correct padding, hover/selected states, and
 * scroll containment out of the box — matching the standard shadcn spec.
 */

import * as React from 'react';
import { Command as CommandPrimitive } from 'cmdk';
import { Search } from 'lucide-react';

export const Command = CommandPrimitive;

export const CommandList = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.List>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.List>
>(({ className = '', ...props }, ref) => (
  <CommandPrimitive.List
    ref={ref}
    className={['max-h-[300px] overflow-y-auto overflow-x-hidden', className].filter(Boolean).join(' ')}
    {...props}
  />
));
CommandList.displayName = 'CommandList';

export const CommandEmpty = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Empty>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Empty>
>(({ className = '', ...props }, ref) => (
  <CommandPrimitive.Empty
    ref={ref}
    className={['py-6 text-center text-sm text-gray-500', className].filter(Boolean).join(' ')}
    {...props}
  />
));
CommandEmpty.displayName = 'CommandEmpty';

