CommandSeparator.displayName = 'CommandSeparator';

export const CommandInput = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Input>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Input>
>(({ className = '', ...props }, ref) => (
  <div className="flex items-center border-b px-3" cmdk-input-wrapper="">
    <Search className="mr-2 h-4 w-4 shrink-0 text-gray-400" aria-hidden="true" />
    <CommandPrimitive.Input
      ref={ref}
      className={['flex h-9 w-full bg-transparent py-2 text-sm outline-none placeholder:text-gray-400 disabled:cursor-not-allowed disabled:opacity-50', className].filter(Boolean).join(' ')}
      {...props}
    />
  </div>
));
CommandInput.displayName = 'CommandInput';
