import React, { useState, useCallback } from 'react';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import type { DragEndEvent } from '@dnd-kit/core';
import {
  arrayMove,
  sortableKeyboardCoordinates,
} from '@dnd-kit/sortable';
import { Button } from '../Button/Button';
import { AdvancedSearchGroup } from './parts/AdvancedSearchGroup';
import { CloseIcon as XMarkIcon, FunnelIcon } from './icons';
import type { MasterCrudField, AdvancedFilter } from './MasterCrud.types';

interface MasterCrudAdvancedSearchProps {
  fields: MasterCrudField[];
  onSearch: (filters: AdvancedFilter[]) => void;
  onClose: () => void;
  initialSearchTerm?: string;
  initialSearchField?: string;
  showConnectors?: boolean; // Se mantiene por compatibilidad pero ahora la lógica es siempre visible
  maxFilters?: number;
  filterableFields?: string[];
  t: (key: string, defaultValue?: string) => string;
}

/**
 * MasterCrudAdvancedSearch - Nueva versión con soporte de grupos y Drag & Drop
 * Permite composiciones lógicas complejas de forma visual y minimalista.
 */
export const MasterCrudAdvancedSearch: React.FC<MasterCrudAdvancedSearchProps> = ({
  fields,
  onSearch,
  onClose,
  initialSearchTerm,
  initialSearchField,
  showConnectors = false,
  filterableFields = [],
  t,
}) => {
  const searchableFields = React.useMemo(() => {
    if (filterableFields && filterableFields.length > 0) {
      return fields.filter(f => filterableFields.includes(f.accessorKey as string));
    }
    return fields.filter(f => f.config?.searchable !== false);
  }, [fields, filterableFields]);

  // Sensores para DND
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Estado inicial: Un grupo raíz con una regla
  const [rootGroup, setRootGroup] = useState<AdvancedFilter>(() => {
    const firstField = searchableFields[0]?.accessorKey as string || '';
    const initialRule: AdvancedFilter = {
      id: `rule-${Math.random().toString(36).substr(2, 9)}`,
      field: (initialSearchField && initialSearchField !== 'all') ? initialSearchField : firstField,
      connector: 'AND',
      value: initialSearchTerm || '',
      operator: 'contains',
      isGroup: false,
    };

    return {
      id: 'root',
      connector: 'AND',
      isGroup: true,
      children: [initialRule],
    };
  });

  // ===== FUNCIONES RECURSIVAS DE MANIPULACIÓN =====

  const updateNode = useCallback((node: AdvancedFilter, id: string, updates: Partial<AdvancedFilter>): AdvancedFilter => {
    if (node.id === id) return { ...node, ...updates };
    if (node.children) {
      return { ...node, children: node.children.map(child => updateNode(child, id, updates)) };
    }
    return node;
  }, []);

  const removeNode = useCallback((node: AdvancedFilter, id: string): AdvancedFilter | null => {
    if (node.id === id) return null;
    if (node.children) {
      const newChildren = node.children
        .map(child => removeNode(child, id))
        .filter((child): child is AdvancedFilter => child !== null);
      return { ...node, children: newChildren };
    }
    return node;
  }, []);

  const addRuleToGroup = useCallback((node: AdvancedFilter, groupId: string): AdvancedFilter => {
    if (node.id === groupId) {
      const newRule: AdvancedFilter = {
        id: `rule-${Math.random().toString(36).substr(2, 9)}`,
        field: searchableFields[0]?.accessorKey as string || '',
        connector: 'AND',
        value: '',
        operator: 'contains',
        isGroup: false,
      };
      return { ...node, children: [...(node.children || []), newRule] };
    }
    if (node.children) {
      return { ...node, children: node.children.map(child => addRuleToGroup(child, groupId)) };
    }
    return node;
  }, [searchableFields]);

  const addGroupToGroup = useCallback((node: AdvancedFilter, groupId: string): AdvancedFilter => {
    if (node.id === groupId) {
      const newGroup: AdvancedFilter = {
        id: `group-${Math.random().toString(36).substr(2, 9)}`,
        connector: 'AND',
        isGroup: true,
        children: [{
          id: `rule-${Math.random().toString(36).substr(2, 9)}`,
          field: searchableFields[0]?.accessorKey as string || '',
          connector: 'AND',
          value: '',
          operator: 'contains',
          isGroup: false,
        }],
      };
      return { ...node, children: [...(node.children || []), newGroup] };
    }
    if (node.children) {
      return { ...node, children: node.children.map(child => addGroupToGroup(child, groupId)) };
    }
    return node;
  }, [searchableFields]);

  const reorderNodes = useCallback((node: AdvancedFilter, activeId: string, overId: string): AdvancedFilter => {
    if (node.children) {
      const activeIndex = node.children.findIndex(c => c.id === activeId);
      const overIndex = node.children.findIndex(c => c.id === overId);

      if (activeIndex !== -1 && overIndex !== -1) {
        return { ...node, children: arrayMove(node.children, activeIndex, overIndex) };
      }
      return { ...node, children: node.children.map(child => reorderNodes(child, activeId, overId)) };
    }
    return node;
  }, []);

  // ===== HANDLERS =====

  const handleUpdate = (id: string, updates: Partial<AdvancedFilter>) => {
    setRootGroup(prev => updateNode(prev, id, updates));
  };

  const handleRemove = (id: string) => {
    setRootGroup(prev => {
      const updated = removeNode(prev, id);
      return updated || prev; // Evitar que el root desaparezca
    });
  };

  const handleAddRule = (groupId: string) => {
    setRootGroup(prev => addRuleToGroup(prev, groupId));
  };

  const handleAddGroup = (groupId: string) => {
    setRootGroup(prev => addGroupToGroup(prev, groupId));
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (over && active.id !== over.id) {
      setRootGroup(prev => reorderNodes(prev, active.id as string, over.id as string));
    }
  };

  const handleFilter = () => {
    // Enviamos el rootGroup completo para preservar su connector (AND/OR).
    // El servicio recibe [rootGroup] y puede usar evaluateFilter(item, rootGroup)
    // que aplica rootGroup.connector sobre sus hijos correctamente.
    onSearch([rootGroup]);
  };

  const handleClear = () => {
    const firstField = searchableFields[0]?.accessorKey as string || '';
    setRootGroup({
      id: 'root',
      connector: 'AND',
      isGroup: true,
      children: [{
        id: `rule-${Math.random().toString(36).substr(2, 9)}`,
        field: firstField,
        connector: 'AND',
        value: '',
        operator: 'contains',
        isGroup: false,
      }],
    });
    onSearch([]);
  };

  return (
    <div className="bg-white dark:bg-dark-bg-primary p-5 animate-in slide-in-from-top duration-300 rounded-2xl shadow-lg border border-border-secondary dark:border-dark-border-primary">
      {/* Header - Más compacto */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="p-1.5 bg-primary-50 dark:bg-primary-900/20 rounded-lg">
            <FunnelIcon className="w-4 h-4 text-primary-600" />
          </div>
          <div className="flex flex-col">
            <span className="text-xs font-bold text-content-primary dark:text-dark-content-primary uppercase tracking-widest">
              {t('advancedSearch', 'Búsqueda Avanzada')}
            </span>
          </div>
        </div>
        <Button
          type="outline"
          size="xs"
          iconOnly
          leftIcon={<XMarkIcon className="w-3.5 h-3.5" />}
          onClick={onClose}
          ariaLabel={t('close', 'Cerrar')}
          className="!bg-white dark:!bg-dark-bg-primary"
        />
      </div>

      {/* Árbol de Filtros con DND */}
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <AdvancedSearchGroup
          group={rootGroup}
          fields={fields}
          onUpdate={handleUpdate}
          onRemove={handleRemove}
          onAddRule={handleAddRule}
          onAddGroup={handleAddGroup}
          isRoot
          showConnectors={showConnectors}
          t={t}
        />
      </DndContext>

      {/* Footer Centrado */}
      <div className="flex justify-center items-center gap-4 mt-10 pt-6 border-t border-border-secondary dark:border-dark-border-primary">
        <Button 
          type="plain" 
          size="base" 
          onClick={handleClear} 
          className="text-content-primary dark:text-dark-content-primary font-bold hover:text-primary-600 transition-colors"
        >
          {t('clearAllFilters', 'Limpiar todos los filtros')}
        </Button>
        <Button 
          type="default" 
          size="l" 
          leftIcon={<FunnelIcon className="w-4 h-4" />} 
          onClick={handleFilter} 
          className="px-16 shadow-lg transform hover:scale-105 transition-all duration-200"
        >
          {t('applyFilters', 'Filtrar Resultados')}
        </Button>
      </div>
    </div>
  );
};
