import Skeleton from 'react-loading-skeleton'
import 'react-loading-skeleton/dist/skeleton.css'
import { useTranslations } from '../providers/ContactServiceProvider'

const SKELETON_ROWS = 3

interface ContactGridSkeletonProps {
  layout?: 'table' | 'card'
}

export function ContactGridSkeleton({ layout = 'table' }: ContactGridSkeletonProps) {
  const t = useTranslations()

  if (layout === 'card') {
    return (
      <div className="flex flex-col gap-3">
        {Array.from({ length: SKELETON_ROWS }).map((_, i) => (
          <div key={i} className="rounded-md bg-white p-4 shadow-sm dark:bg-slate-900">
            <Skeleton width={160} height={16} />
            <Skeleton width={200} height={14} className="mt-1" />
            <Skeleton width={120} height={12} className="mt-1" />
          </div>
        ))}
      </div>
    )
  }

  return (
    <table className="w-full">
      <thead>
        <tr className="border-b border-slate-200 dark:border-slate-700">
          <th className="py-3 px-4 text-left text-sm font-medium text-slate-500">{t.skeleton.column.name}</th>
          <th className="py-3 px-4 text-left text-sm font-medium text-slate-500">{t.skeleton.column.email}</th>
          <th className="py-3 px-4 text-left text-sm font-medium text-slate-500">{t.skeleton.column.phone}</th>
          <th className="py-3 px-4 text-right text-sm font-medium text-slate-500">{t.skeleton.column.actions}</th>
        </tr>
      </thead>
      <tbody>
        {Array.from({ length: SKELETON_ROWS }).map((_, i) => (
          <tr key={i} className="border-b border-slate-100 dark:border-slate-800">
            <td className="py-3 px-4"><Skeleton width={140} /></td>
            <td className="py-3 px-4"><Skeleton width={180} /></td>
            <td className="py-3 px-4"><Skeleton width={120} /></td>
            <td className="py-3 px-4 text-right"><Skeleton width={80} /></td>
          </tr>
        ))}
      </tbody>
    </table>
  )
}
