import React, { useState, useRef, useEffect } from 'react';
import { Input } from '../Input/Input';
import { Button } from '../Button/Button';
import { Dropdown } from '../Dropdown/Dropdown';
import { CompanySelector } from './CompanySelector';
import type { MasterCrudToolbarProps, ToolbarViewType, MasterCrudCompany } from './MasterCrud.types';
import { 
  SearchIcon, 
  FilterIcon, 
  ChevronDownIcon, 
  GridIcon, 
  ListIcon, 
  SortAscIcon, 
  SortDescIcon,
  Bars3Icon,
  FunnelIcon,
  AdjustmentsIcon,
  ChevronRightIcon
} from './icons';

/**
 * MasterCrudToolbar - Barra de herramientas para MasterCrud
 */
export const MasterCrudToolbar: React.FC<MasterCrudToolbarProps> = ({
  title,
  searchPlaceholder,
  searchValue = '',
  onSearchChange,
  showSearch = true,
  filterOptions = [],
  selectedFilter,
  onFilterChange,
  showFilter = true,
  filterButtonText,
  sortOptions = [],
  selectedSort,
  onSortChange,
  sortDirection = 'asc',
  onSortDirectionChange,
  showSort = true,
  sortButtonText,
  viewType = 'list',
  onViewChange,
  showViewToggle = true,
  showAdvancedSearch = false,
  extraContent,
  className = '',
  globalActions = [],
  batchActions = [],
  hasSelection = false,
  isAdvancedSearchActive = false,
  onAdvancedSearchToggle,
  initialFiltersVisible = false,
  activeByCompany = false,
  companyRequired = false,
  companies = [],
  selectedCompany,
  onCompanyChange,
  t,
}) => {
  // Use translations for defaults if props are not provided
  const finalSearchPlaceholder = searchPlaceholder || `${t('search', 'Buscar')}...`;
  const finalFilterButtonText = filterButtonText || t('filterBy', 'Filtrar');
  const finalSortButtonText = sortButtonText || t('sortBy', 'Ordenar');

  // ===== ESTADO DE VISIBILIDAD DE BÚSQUEDA =====
  const [isSearchVisible, setIsSearchVisible] = useState(initialFiltersVisible);
  const [isFullyOpen, setIsFullyOpen] = useState(initialFiltersVisible);

  // Reiniciar estado de apertura total cuando se cierra
  useEffect(() => {
    if (!isSearchVisible) {
      setIsFullyOpen(false);
    }
  }, [isSearchVisible]);

  // ===== ESTADO DE DROPDOWNS =====
  const [filterOpen, setFilterOpen] = useState(false);
  const [sortOpen, setSortOpen] = useState(false);

  const filterRef = useRef<HTMLDivElement>(null);
  const sortRef = useRef<HTMLDivElement>(null);

  // ===== CERRAR DROPDOWN AL HACER CLICK FUERA =====
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterRef.current && !filterRef.current.contains(event.target as Node)) {
        setFilterOpen(false);
      }
      if (sortRef.current && !sortRef.current.contains(event.target as Node)) {
        setSortOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // ===== ACCIONES A MOSTRAR =====
  const currentActions = hasSelection ? batchActions : globalActions;
  const actionsLabel = hasSelection ? t('batchActions', 'Acciones grupales') : t('actions', 'Acciones');

  // Separar acciones directas y de menú
  const directActions = currentActions.filter(a => a.displayType === 'direct');
  const menuActions = currentActions.filter(a => a.displayType !== 'direct');

  // ===== CLASES DEL CONTENEDOR PRINCIPAL =====
  const containerClasses = `
    flex
    flex-wrap
    items-center
    justify-between
    gap-4
    min-w-[256px]
    w-full
    p-4
    bg-background-secondary
    dark:bg-dark-bg-primary
    border-b
    border-border-primary
    dark:border-dark-border-primary
    sticky
    top-0
    z-20
    rounded-tl-2xl
    ${className}
  `
    .replace(/\s+/g, ' ')
    .trim();

  // ===== CLASES DEL TÍTULO =====
  // Figma: Font 20px Bold, color #1355b7 (link hover primary)
  const titleClasses = `
    text-xl
    font-semibold
    leading-7
    tracking-tight
    text-[#1355b7]
    dark:text-primary-600
    pr-6
    shrink-0
  `
    .replace(/\s+/g, ' ')
    .trim();

  // ===== CLASES DEL CONTENEDOR DE CONTROLES =====
  const controlsContainerClasses = `
    flex
    flex-wrap
    items-center
    justify-end
    gap-4
    flex-1
    min-w-[256px]
  `
    .replace(/\s+/g, ' ')
    .trim();

  // ===== CLASES BASE PARA BOTONES DE DROPDOWN =====
  const dropdownButtonClasses = `
    inline-flex
    items-center
    justify-center
    gap-3
    px-3
    py-2
    text-sm
    font-medium
    leading-5
    bg-transparent
    border
    border-primary-300
    rounded-lg
    text-primary-600
    hover:border-primary-300
    hover:bg-white/50
    focus:outline-none
    focus:ring-2
    focus:ring-primary-400
    focus:ring-offset-2
    transition-all
    duration-150
    dark:border-dark-border-custom
    dark:text-primary-500
    dark:hover:border-dark-border-custom
    dark:focus:ring-dark-border-custom
  `
    .replace(/\s+/g, ' ')
    .trim();

  // ===== CLASES DEL MENÚ DROPDOWN =====
  const dropdownMenuClasses = `
    absolute
    z-50
    right-0
    top-full
    mt-1
    min-w-[160px]
    max-h-60
    overflow-y-auto
    p-1
    bg-white
    border
    border-border-secondary
    rounded-lg
    shadow-lg
    dark:bg-dark-bg-primary
    dark:border-dark-border-primary
  `
    .replace(/\s+/g, ' ')
    .trim();

  // ===== CLASES DE ITEM DEL DROPDOWN =====
  const getDropdownItemClasses = (isSelected: boolean) => `
    flex
    items-center
    gap-2
    px-3
    py-2
    text-sm
    font-normal
    rounded-md
    cursor-pointer
    transition-colors
    duration-150
    ${
      isSelected
        ? 'bg-primary-600 text-primary-inverse-content dark:bg-primary-600 dark:text-primary-inverse-content'
        : 'text-content-primary hover:bg-primary-600 hover:text-primary-inverse-content dark:text-dark-content-primary dark:hover:bg-primary-600 dark:hover:text-primary-inverse-content'
    }
  `
    .replace(/\s+/g, ' ')
    .trim();

  // ===== CLASES DEL TOGGLE DE VISTA =====
  const viewToggleContainerClasses = `
    inline-flex
    items-center
    h-9
    bg-transparent
    border
    border-primary-300
    rounded-lg
    overflow-hidden
    dark:border-dark-border-custom
  `
    .replace(/\s+/g, ' ')
    .trim();

  const getViewToggleButtonClasses = (isActive: boolean) => `
    flex
    items-center
    justify-center
    w-9
    h-full
    transition-all
    duration-150
    ${
      isActive
        ? 'bg-primary-600 text-primary-inverse-content dark:bg-dark-bg-inverse dark:text-dark-content-inverse'
        : 'text-primary-600 hover:bg-white/50 dark:text-primary-500 dark:hover:bg-white/5'
    }
    ${!isActive ? 'border-l first:border-l-0 border-primary-300 dark:border-dark-border-custom' : ''}
  `
    .replace(/\s+/g, ' ')
    .trim();

  // ===== MANEJAR SELECCIÓN DE FILTRO =====
  const handleFilterSelect = (value: string) => {
    onFilterChange?.(value);
    setFilterOpen(false);
  };

  // ===== MANEJAR SELECCIÓN DE ORDENAMIENTO =====
  const handleSortSelect = (value: string) => {
    onSortChange?.(value);
    setSortOpen(false);
  };

  // ===== MANEJAR CAMBIO DE VISTA =====
  const handleViewChange = (view: ToolbarViewType) => {
    onViewChange?.(view);
  };

  // ===== MANEJAR TOGGLE DIRECCIÓN =====
  const handleSortDirectionToggle = () => {
    const newDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    onSortDirectionChange?.(newDirection);
  };

  // ===== OBTENER LABEL DEL SORT SELECCIONADO =====
  const selectedSortLabel = sortOptions.find((opt) => opt.value === selectedSort)?.label || sortButtonText;

  // ===== MANEJAR SELECCIÓN DE COMPAÑÍA =====
  const handleCompanySelect = (company: MasterCrudCompany) => {
    onCompanyChange?.(company, undefined);
  };

  return (
    <div className={containerClasses}>
      {/* Título y Compañía */}
      <div className="flex flex-col shrink-0 min-w-0 pr-6">
        <h2 className={titleClasses.replace('pr-6', '')}>{title}</h2>
        {activeByCompany && companies.length > 0 && (
          <CompanySelector 
            companies={companies} 
            selectedCompany={selectedCompany} 
            onCompanyChange={handleCompanySelect}
            className="mt-1"
            t={t}
          />
        )}
      </div>

      {/* Contenedor de controles */}
      <div className={controlsContainerClasses}>
        
        {/* CLUSTER DE BÚSQUEDA Y FILTROS (ANIMADO) */}
        <div 
          className={`
            flex items-center gap-4 transition-all duration-500 ease-in-out py-2 px-1
            ${isSearchVisible ? 'max-w-[1000px] opacity-100' : 'max-w-0 opacity-0 pointer-events-none'}
            ${isFullyOpen ? 'overflow-visible' : 'overflow-hidden'}
          `}
          onTransitionEnd={() => {
            if (isSearchVisible) setIsFullyOpen(true);
          }}
        >
          {/* Input de búsqueda */}
          {showSearch && (
            <div className="flex items-center gap-2 flex-none w-[250px]">
              <div className="flex-1">
                <Input
                  type="text"
                  inputSize="sm"
                  placeholder={finalSearchPlaceholder}
                  value={searchValue}
                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => onSearchChange?.(e.target.value)}
                  startIcon={<SearchIcon className="w-4 h-4 text-primary-600 dark:text-primary-500" />}
                  disabled={isAdvancedSearchActive}
                  className="h-[38px] border-primary-300 dark:border-dark-border-custom shadow-none placeholder:text-primary-400 dark:placeholder:text-primary-500/60"
                />
              </div>
              {showAdvancedSearch && (
                <Button
                  type={isAdvancedSearchActive ? 'default' : 'outline'}
                  size="sm"
                  iconOnly
                  leftIcon={<FunnelIcon className="w-4 h-4" />}
                  onClick={onAdvancedSearchToggle}
                  ariaLabel={t('advancedSearch', 'Búsqueda avanzada')}
                  title={t('advancedSearch', 'Búsqueda avanzada')}
                />
              )}
            </div>
          )}

          {/* Dropdown de Filtros */}
          {showFilter && filterOptions.length > 0 && (
            <div className="relative flex-none" ref={filterRef}>
              <button
                type="button"
                className={dropdownButtonClasses}
                onClick={() => setFilterOpen(!filterOpen)}
                aria-expanded={filterOpen}
                aria-haspopup="listbox"
              >
                <FilterIcon className="w-4 h-4" />
                <span>{finalFilterButtonText}</span>
                <ChevronDownIcon
                  className={`w-4 h-4 transition-transform duration-150 ${filterOpen ? 'rotate-180' : ''}`}
                />
              </button>

              {filterOpen && (
                <div className={dropdownMenuClasses} role="listbox">
                  {filterOptions.map((option) => (
                    <div
                      key={option.value}
                      className={getDropdownItemClasses(selectedFilter === option.value)}
                      onClick={() => handleFilterSelect(option.value)}
                      role="option"
                      aria-selected={selectedFilter === option.value}
                    >
                      {option.icon && <span className="w-4 h-4">{option.icon}</span>}
                      <span>{option.label}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Grupo de Ordenamiento (Dropdown + Botón Dirección) */}
          {showSort && sortOptions.length > 0 && (
            <div className="flex items-center gap-2 flex-none">
              <div className="relative" ref={sortRef}>
                <button
                  type="button"
                  className={dropdownButtonClasses}
                  onClick={() => setSortOpen(!sortOpen)}
                  aria-expanded={sortOpen}
                  aria-haspopup="listbox"
                >
                  <SortAscIcon className="w-4 h-4" />
                  <span>{selectedSort ? (sortOptions.find(o => o.value === selectedSort)?.label || selectedSort) : finalSortButtonText}</span>
                  <ChevronDownIcon
                    className={`w-4 h-4 transition-transform duration-150 ${sortOpen ? 'rotate-180' : ''}`}
                  />
                </button>

                {sortOpen && (
                  <div className={dropdownMenuClasses} role="listbox">
                    {sortOptions.map((option) => (
                      <div
                        key={option.value}
                        className={getDropdownItemClasses(selectedSort === option.value)}
                        onClick={() => handleSortSelect(option.value)}
                        role="option"
                        aria-selected={selectedSort === option.value}
                      >
                        <span>{option.label}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {/* Botón de Dirección */}
              <button
                type="button"
                className={`
                  ${dropdownButtonClasses}
                  px-2
                  w-[38px]
                  ${!selectedSort ? 'opacity-50 cursor-not-allowed pointer-events-none' : ''}
                `}
                onClick={handleSortDirectionToggle}
                disabled={!selectedSort}
                aria-label={sortDirection === 'asc' ? t('sortAsc', 'Ordenar ascendente') : t('sortDesc', 'Ordenar descendente')}
                title={sortDirection === 'asc' ? t('sortAsc', 'Ordenar ascendente') : t('sortDesc', 'Ordenar descendente')}
              >
                {sortDirection === 'asc' ? (
                  <SortAscIcon className="w-5 h-5" />
                ) : (
                  <SortDescIcon className="w-5 h-5" />
                )}
              </button>
            </div>
          )}
        </div>

        {/* BOTÓN DISPARADOR (TOGGLE SEARCH) */}
        <Button
          type={isSearchVisible ? 'default' : 'outline'}
          size="l"
          iconOnly
          leftIcon={isSearchVisible ? <ChevronRightIcon className="w-5 h-5" /> : <AdjustmentsIcon className="w-5 h-5" />}
          onClick={() => setIsSearchVisible(!isSearchVisible)}
          ariaLabel={isSearchVisible ? t('hideSearch', 'Ocultar búsqueda') : t('showSearch', 'Mostrar búsqueda')}
          title={isSearchVisible ? t('hideSearch', 'Ocultar búsqueda') : t('showSearch', 'Mostrar búsqueda')}
          className="transition-all duration-300 active:scale-95 !bg-transparent !text-primary-600 !border-primary-300"
        />

        {/* Toggle de Vista (Grid/Lista) */}
        {showViewToggle && (
          <div className={viewToggleContainerClasses} role="group" aria-label={t('changeView', 'Cambiar vista')}>
            <button
              type="button"
              className={getViewToggleButtonClasses(viewType === 'grid')}
              onClick={() => handleViewChange('grid')}
              aria-label={t('gridView', 'Vista de cuadrícula')}
              aria-pressed={viewType === 'grid'}
            >
              <GridIcon className="w-4 h-4" />
            </button>
            <button
              type="button"
              className={getViewToggleButtonClasses(viewType === 'list')}
              onClick={() => handleViewChange('list')}
              aria-label={t('listView', 'Vista de lista')}
              aria-pressed={viewType === 'list'}
            >
              <ListIcon className="w-5 h-5" />
            </button>
          </div>
        )}

        {/* Acciones Directas (Globales/Grupales) */}
        {directActions.map((action) => {
          const actionName = typeof action.name === 'function' ? action.name(null) : action.name;
          const actionIcon = typeof action.icon === 'function' ? action.icon(null) : action.icon;
          
          return (
            <Button
              key={action.id || actionName}
              type="outline"
              size="l"
              leftIcon={actionIcon}
              onClick={() => action.action?.([])}
              disabled={typeof action.disabled === 'function' ? action.disabled(null as any) : action.disabled}
              className="!bg-transparent !text-primary-600 !border-primary-300"
            >
              {actionName}
            </Button>
          );
        })}

        {/* Combo Menú de Acciones (Globales/Grupales) */}
        {menuActions.length > 0 && (
          <Dropdown
            menuClassName="w-56"
            renderTrigger={() => (
              <Button
                type="outline"
                size="l"
                leftIcon={<Bars3Icon className="w-4 h-4" />}
                rightIcon={<ChevronDownIcon className="w-4 h-4" />}
                className="!bg-transparent !text-primary-600 !border-primary-300"
              >
                {actionsLabel}
              </Button>
            )}
            items={menuActions.map(action => {
              const actionName = typeof action.name === 'function' ? action.name(null) : action.name;
              const actionIcon = typeof action.icon === 'function' ? action.icon(null) : action.icon;
              
              return {
                children: actionName,
                icon: actionIcon,
                disabled: typeof action.disabled === 'function' ? action.disabled(null as any) : action.disabled,
                onClick: () => action.action?.([]),
                className: actionName.toLowerCase().includes('eliminar') || actionName.toLowerCase().includes('delete')
                  ? 'text-error-content hover:text-error-content dark:text-error-content'
                  : '',
              };
            })}
          />
        )}

        {/* Contenido extra */}
        {extraContent}
      </div>
    </div>
  );
};
