import { Ability, AbilityBuilder } from '@casl/ability';

type Actions = 'view' | 'create' | 'delete';
type Subjects = 'Widget' | 'Dashboard' | 'all';
export type DashboardAbility = Ability<[Actions, Subjects]>;

export function createDashboardAbility(userRoles: string[]): DashboardAbility {
  const { can, build } = new AbilityBuilder<DashboardAbility>(Ability);

  if (userRoles.length > 0) {
    can('view', 'Dashboard');
    can('view', 'Widget');
  }

  if (userRoles.includes('admin')) {
    can('create', 'Widget');
    can('delete', 'Widget');
  }

  return build();
}

export function canUserViewWidget(userRoles: string[], widgetRoles: string[]): boolean {
  if (widgetRoles.length === 0) return true;
  return userRoles.some(role => widgetRoles.includes(role));
}
