import React, { useState, useMemo } from 'react';
import { Search, X, Plus, Minus, Pencil, Settings2, Trash2, AlertTriangle } from 'lucide-react';
import type { WidgetDefinition, UserWidgetPreference } from '../types';
import { getTypeIcon, getTypeLabel } from '../utils/widgetTypeConfig';
import { WidgetBuilder } from './WidgetBuilder/WidgetBuilder';

interface WidgetManagerPanelProps {
  isOpen: boolean;
  catalog: WidgetDefinition[];
  currentLayout: UserWidgetPreference[];
  isAdmin?: boolean;
  userId?: string;
  showExternalEndpoints?: boolean;
  onClose: () => void;
  onRequestAdd: (widget: WidgetDefinition) => void;
  onRequestModify: (widget: WidgetDefinition, preference: UserWidgetPreference) => void;
  onRemoveWidget: (instanceId: string) => void;
  onWidgetCreated: (definition: WidgetDefinition) => void | Promise<void>;
  onWidgetUpdated?: (definition: WidgetDefinition) => void;
  onDeleteWidget?: (widgetId: string) => void;
}


export const WidgetManagerPanel: React.FC<WidgetManagerPanelProps> = ({
  isOpen, catalog, currentLayout, isAdmin = false, userId,
  showExternalEndpoints = false, onClose, onRequestAdd, onRequestModify,
  onRemoveWidget, onWidgetCreated, onWidgetUpdated, onDeleteWidget,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('Todas');
  const [isBuilderOpen, setIsBuilderOpen] = useState(false);
  const [pendingDeleteWidget, setPendingDeleteWidget] = useState<WidgetDefinition | null>(null);

  const categories = useMemo(() => {
    const cats = new Set(catalog.map(w => w.categoria).filter(Boolean));
    return ['Todas', ...Array.from(cats)];
  }, [catalog]);

  const filteredCatalog = useMemo(() => {
    const inLayoutIds = new Set(currentLayout.map(p => p.widget_id));
    return catalog
      .filter(w => {
        const matchSearch = w.nombre.toLowerCase().includes(searchTerm.toLowerCase());
        const matchCategory = categoryFilter === 'Todas' || w.categoria === categoryFilter;
        return matchSearch && matchCategory;
      })
      .sort((a, b) => {
        const aIn = inLayoutIds.has(a.widget_id) ? 0 : 1;
        const bIn = inLayoutIds.has(b.widget_id) ? 0 : 1;
        return aIn - bIn;
      });
  }, [catalog, currentLayout, searchTerm, categoryFilter]);

  if (!isOpen) return null;

  return (
    <>
      <div className="fixed inset-y-0 right-0 w-[348px] bg-white shadow-2xl border-l border-gray-200 z-50 flex flex-col">

        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-100">
          <h2 className="text-lg font-semibold text-gray-800">Catálogo de Indicadores</h2>
          <button onClick={onClose} className="p-1 hover:bg-gray-100 rounded text-gray-500">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Búsqueda y filtros */}
        <div className="p-4 border-b border-gray-100 space-y-3 bg-gray-50">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Buscar indicador..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-3 py-2 text-sm border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div className="flex gap-2 overflow-x-auto pb-1 custom-scrollbar">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setCategoryFilter(cat)}
                className={`px-3 py-1 text-xs font-medium rounded-full whitespace-nowrap transition-colors ${
                  categoryFilter === cat
                    ? 'bg-blue-600 text-white'
                    : 'bg-white border border-gray-200 text-gray-600 hover:bg-gray-50'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Lista de widgets */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {filteredCatalog.length === 0 ? (
            <div className="text-center text-gray-500 mt-10 text-sm">No se encontraron indicadores.</div>
          ) : (
            filteredCatalog.map(widget => {
              const pref = currentLayout.find(p => p.widget_id === widget.widget_id);
              const inLayout = !!pref;
              const TypeIcon = getTypeIcon(widget.tipo);
              const typeLabel = getTypeLabel(widget.tipo);
              const isSeed = !widget.propietario_id;
              const canDelete = !isSeed && isAdmin;

              return (
                <div
                  key={widget.widget_id}
                  className={`p-3 rounded-lg border transition-all ${
                    inLayout ? 'border-blue-200 bg-blue-50/30' : 'border-gray-200 bg-white hover:border-gray-300'
                  }`}
                >
                  <div className="flex justify-between items-start mb-1">
                    <div className="flex items-center gap-2 min-w-0">
                      <TypeIcon className="w-4 h-4 text-gray-500 flex-shrink-0" />
                      <h4 className="text-sm font-semibold text-gray-800 truncate">{widget.nombre}</h4>
                    </div>
                    <div className="flex items-center gap-1 flex-shrink-0">
                      <span className="text-[10px] uppercase font-bold tracking-wider text-blue-700 bg-blue-50 px-1.5 py-0.5 rounded">
                        {widget.categoria}
                      </span>
                      {canDelete && onDeleteWidget && (
                        <button
                          onClick={() => setPendingDeleteWidget(widget)}
                          className="p-1 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                          title="Eliminar widget del catálogo"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </div>
                  </div>
                  <p className="text-xs text-gray-500 mb-3 line-clamp-2">{widget.descripcion}</p>
                  <div className="flex items-center justify-between">
                    <span className="text-xs text-gray-400">{typeLabel}</span>
                    {inLayout ? (
                      <div className="flex gap-1">
                        <button
                          onClick={() => pref && onRemoveWidget(pref.id)}
                          className="flex items-center gap-1 text-xs font-medium text-red-600 hover:text-red-700 bg-red-50 hover:bg-red-100 px-2 py-1 rounded transition-colors"
                        >
                          <Minus className="w-3.5 h-3.5" /> Quitar
                        </button>
                        <button
                          onClick={() => pref && onRequestModify(widget, pref)}
                          className="flex items-center gap-1 text-xs font-medium text-blue-600 hover:text-blue-700 bg-blue-50 hover:bg-blue-100 px-2 py-1 rounded transition-colors"
                        >
                          <Pencil className="w-3.5 h-3.5" /> Modificar
                        </button>
                      </div>
                    ) : (
                      <button
                        onClick={() => onRequestAdd(widget)}
                        className="flex items-center gap-1 text-xs font-medium text-blue-600 hover:text-blue-700 bg-blue-50 hover:bg-blue-100 px-2 py-1 rounded transition-colors"
                      >
                        <Plus className="w-3.5 h-3.5" /> Agregar
                      </button>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Botón Builder (solo admin con endpoints externos) */}
        {isAdmin && showExternalEndpoints && (
          <div className="p-4 border-t border-gray-200 bg-gray-50">
            <button
              onClick={() => setIsBuilderOpen(true)}
              className="w-full py-2 bg-white border border-gray-300 text-gray-600 text-xs font-medium rounded shadow-sm hover:bg-gray-50 transition-all flex items-center justify-center gap-1.5"
            >
              <Settings2 className="w-3.5 h-3.5" /> Conectar API externa (avanzado)
            </button>
          </div>
        )}
      </div>

      <WidgetBuilder
        isOpen={isBuilderOpen}
        onClose={() => setIsBuilderOpen(false)}
        onSuccess={(w) => { onWidgetCreated(w); setIsBuilderOpen(false); }}
        isAdmin={isAdmin}
        showExternalEndpoints={showExternalEndpoints}
      />

      {/* Dialog de confirmación — Eliminar Widget del Catálogo */}
      {pendingDeleteWidget && onDeleteWidget && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center bg-gray-900/60 backdrop-blur-sm p-4">
          <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm p-6 animate-in fade-in zoom-in duration-150">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 rounded-full bg-red-100 flex items-center justify-center flex-shrink-0">
                <AlertTriangle className="w-5 h-5 text-red-600" />
              </div>
              <div>
                <h3 className="font-semibold text-gray-900">Eliminar widget</h3>
                <p className="text-sm text-gray-500">Esta acción no se puede deshacer.</p>
              </div>
            </div>
            <p className="text-sm text-gray-600 mb-6">
              ¿Confirmas que quieres eliminar{' '}
              <span className="font-semibold">"{pendingDeleteWidget.nombre}"</span> del catálogo?
              Se eliminará para todos los usuarios que lo tengan agregado.
            </p>
            <div className="flex items-center justify-end gap-3">
              <button
                onClick={() => setPendingDeleteWidget(null)}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 hover:bg-gray-200 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button
                onClick={() => { onDeleteWidget(pendingDeleteWidget.widget_id); setPendingDeleteWidget(null); }}
                className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-red-600 hover:bg-red-700 rounded-lg transition-colors"
              >
                <Trash2 className="w-4 h-4" /> Eliminar widget
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};
