import React, { useRef, useState, useEffect, useCallback } from 'react';
import { clsx } from 'clsx';
import { ArrowLeftIcon, EllipsisHorizontalIcon, Bars3BottomRightIcon } from '@heroicons/react/24/outline';
import { Button } from '../Button/Button';
import { Dropdown } from '../Dropdown/Dropdown';
import type { DropdownItemProps } from '../Dropdown/Dropdown.types';
import { StateBadge } from './StateBadge';
import type { ActionBarProps } from './MasterDocument.types';

// ─── ActionBar ─────────────────────────────────────────────

/**
 * Barra de acciones principal del documento maestro.
 *
 * Contiene breadcrumb, número de documento, badge de estado, botones de
 * transición (con overflow responsivo a dropdown), toggle de FactBox y
 * menú de acciones adicionales.
 *
 * @see MasterDocument.types - ActionBarProps
 */
export function ActionBar({
  breadcrumbLabel,
  onBreadcrumbClick,
  documentId,
  documentNumber,
  stateBadge,
  docTypeBadge,
  transitions,
  onTransition,
  actions,
  onToggleFactBox,
  factBoxOpen,
  className,
}: ActionBarProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const leftRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLDivElement>(null);
  const [visibleCount, setVisibleCount] = useState<number>(Infinity);

  type UnifiedAction = {
    key: string;
    label: string;
    icon?: React.ReactNode;
    variant: 'primary' | 'secondary' | 'danger' | 'ghost';
    onClick: () => void;
    disabled?: boolean;
    disabledReason?: string;
    loading?: boolean;
    group: 'transition' | 'action';
  };

  const allItems: UnifiedAction[] = [
    ...actions
      .filter((a) => a.position !== 'moreMenu')
      .map((a) => ({
        key: `a-${a.key}`,
        label: a.label,
        icon: a.icon,
        variant: a.variant ?? ('ghost' as const),
        onClick: a.onClick,
        disabled: a.disabled,
        disabledReason: a.disabledReason,
        loading: false,
        group: 'action' as const,
      })),
    ...transitions.map((t) => ({
      key: `t-${t.actionKey ?? t.to}`,
      label: t.label,
      icon: t.icon,
      variant: t.style,
      onClick: () => onTransition(t.to),
      disabled: t.disabled,
      loading: t.loading,
      group: 'transition' as const,
    })),
  ];

  const moreMenuActions = actions.filter((a) => a.position === 'moreMenu');

  const calculateOverflow = useCallback(() => {
    const container = containerRef.current;
    const left = leftRef.current;
    const measure = measureRef.current;
    if (!container || !left || !measure) return;

    const style = getComputedStyle(container);
    const paddingH = (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
    const containerInner = container.offsetWidth - paddingH;
    const leftWidth = left.offsetWidth;
    const gap = parseFloat(style.gap) || 16;
    const available = containerInner - leftWidth - gap;

    const buttons = measure.querySelectorAll<HTMLElement>('[data-measure-btn]');
    if (buttons.length === 0) return;

    const overflowBtnWidth = 44;
    const btnGap = 8;
    let used = 0;
    let fit = 0;

    for (let i = 0; i < buttons.length; i++) {
      const w = buttons[i].offsetWidth;
      const gapW = i > 0 ? btnGap : 0;
      const candidate = used + gapW + w;
      const isLast = i === buttons.length - 1;
      const reserve = isLast ? 0 : overflowBtnWidth + btnGap;
      if (candidate + reserve <= available) {
        used = candidate;
        fit++;
      } else {
        break;
      }
    }
    setVisibleCount(fit >= allItems.length ? Infinity : fit);
  }, [allItems.length]);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const observer = new ResizeObserver(() => calculateOverflow());
    observer.observe(el);
    calculateOverflow();
    return () => observer.disconnect();
  }, [calculateOverflow]);

  useEffect(() => {
    requestAnimationFrame(calculateOverflow);
  }, [transitions.length, actions.length, calculateOverflow]);

  const visible = visibleCount === Infinity ? allItems : allItems.slice(0, visibleCount);
  const overflow = visibleCount === Infinity ? [] : allItems.slice(visibleCount);

  const variantMap: Record<string, 'default' | 'outline' | 'plain'> = {
    primary: 'default',
    secondary: 'outline',
    danger: 'outline',
    ghost: 'plain',
  };

  const dropdownItems: DropdownItemProps[] = [];

  if (overflow.length > 0) {
    const overflowTransitions = overflow.filter((i) => i.group === 'transition');
    const overflowActions = overflow.filter((i) => i.group === 'action');

    if (overflowTransitions.length > 0) {
      dropdownItems.push({ isHeading: true, children: 'Transiciones' });
      overflowTransitions.forEach((item) => {
        dropdownItems.push({
          children: item.label,
          icon: item.icon,
          onClick: item.onClick,
          disabled: item.disabled,
          className: item.variant === 'danger' ? '!text-error-content' : '',
        });
      });
    }

    if (overflowActions.length > 0) {
      if (overflowTransitions.length > 0) dropdownItems.push({ isDivider: true });
      dropdownItems.push({ isHeading: true, children: 'Acciones' });
      overflowActions.forEach((item) => {
        dropdownItems.push({
          children: item.label,
          icon: item.icon,
          onClick: item.onClick,
          disabled: item.disabled,
          description: item.disabled ? item.disabledReason : undefined,
        });
      });
    }
  }

  if (moreMenuActions.length > 0) {
    if (dropdownItems.length > 0) dropdownItems.push({ isDivider: true });
    moreMenuActions.forEach((a) => {
      dropdownItems.push({
        children: a.label,
        icon: a.icon,
        onClick: a.onClick,
        disabled: a.disabled,
        description: a.disabled ? a.disabledReason : undefined,
        className: a.variant === 'danger' ? '!text-error-content' : '',
      });
    });
  }

  const showOverflowBtn = dropdownItems.length > 0;

  return (
    <>
      {/* Hidden measurement container */}
      <div
        ref={measureRef}
        className="flex items-center gap-2"
        style={{ position: 'fixed', top: -9999, left: -9999, visibility: 'hidden', pointerEvents: 'none' }}
        aria-hidden="true"
      >
        {allItems.map((item, i) => (
          <div key={i} data-measure-btn className="inline-flex">
            <Button type={variantMap[item.variant] ?? 'plain'} size="base" leftIcon={item.icon} tabIndex={-1}>
              {item.label}
            </Button>
          </div>
        ))}
      </div>

      {/* ActionBar */}
      <div
        ref={containerRef}
        className={clsx(
          'flex items-center justify-between gap-4 w-full h-[52px] px-4',
          'bg-bg-primary sticky top-0 z-[100]',
          'border-b border-border-secondary',
          'dark:bg-dark-bg-primary dark:border-dark-border-primary',
          className,
        )}
        role="toolbar"
        aria-label="Barra de acciones del documento"
      >
        {/* Left side */}
        <div ref={leftRef} className="flex items-center gap-3 min-w-0 shrink-0">
          <button
            type="button"
            onClick={onBreadcrumbClick}
            className={clsx(
              'flex items-center gap-1.5 text-sm font-medium text-content-tertiary',
              'hover:text-content-primary transition-all duration-150 shrink-0',
              'focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2 rounded-md',
              'dark:text-dark-content-secondary dark:hover:text-dark-content-primary',
              'dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary',
            )}
          >
            <ArrowLeftIcon className="w-4 h-4" aria-hidden="true" />
            <span className="hidden sm:inline">{breadcrumbLabel}</span>
          </button>

          <div className="w-px h-5 bg-border-secondary dark:bg-dark-border-primary shrink-0" />

          {(documentNumber || documentId) && (
            <span className="text-sm font-bold text-content-primary dark:text-dark-content-primary shrink-0">
              {documentNumber || documentId}
            </span>
          )}

          {stateBadge && <StateBadge {...stateBadge} />}

          {docTypeBadge && (
            <span className={clsx(
              'inline-flex items-center rounded-full px-[10px] py-[3px] text-[10.5px] font-semibold',
              'bg-background-secondary text-content-tertiary',
              'dark:bg-dark-bg-secondary dark:text-dark-content-secondary',
            )}>
              {docTypeBadge}
            </span>
          )}
        </div>

        {/* Right side */}
        <div className="flex items-center gap-2 shrink-0">
          {visible.map((item) => (
            // El <span> porta el `title` cuando el botón está deshabilitado: el
            // `Button` aplica `disabled:pointer-events-none`, por lo que el hover
            // no llega al propio botón y el tooltip nativo no se dispararía sobre él.
            <span
              key={item.key}
              title={item.disabled && item.disabledReason ? item.disabledReason : undefined}
              className="inline-flex"
            >
              <Button
                type={variantMap[item.variant] ?? 'plain'}
                size="base"
                leftIcon={item.icon}
                onClick={item.onClick}
                disabled={item.disabled}
                title={!item.disabled ? item.label : undefined}
                ariaLabel={item.label}
                className={clsx(
                  item.variant === 'secondary' && [
                    '!bg-bg-primary !text-content-secondary',
                    '!border-border-primary hover:!bg-background-secondary',
                    '!shadow-[0_1px_3px_rgba(60,64,67,.15),0_1px_2px_rgba(60,64,67,.10)]',
                    'dark:!bg-dark-bg-primary dark:!text-dark-content-secondary dark:!border-dark-border-primary dark:hover:!bg-dark-bg-secondary',
                  ],
                  item.variant === 'danger' && '!border-error-border !text-error-content hover:!bg-error-bg dark:!border-error-border dark:!text-error-content dark:hover:!bg-error-bg',
                )}
              >
                {item.label}
              </Button>
            </span>
          ))}

          {onToggleFactBox && (
            <button
              type="button"
              onClick={onToggleFactBox}
              className={clsx(
                'hidden max-lg:flex items-center justify-center w-9 h-9 rounded-md',
                'text-content-tertiary hover:bg-background-secondary dark:hover:bg-dark-bg-secondary transition-all duration-150',
                'focus:outline-hidden focus:ring-2 focus:ring-primary-400 focus:ring-offset-2',
                factBoxOpen && 'bg-primary-100 text-primary-600 dark:bg-primary-900/30 dark:text-primary-400',
                'dark:text-dark-content-secondary dark:hover:bg-dark-bg-secondary',
                'dark:focus:ring-dark-border-custom dark:focus:ring-offset-dark-bg-primary',
              )}
              title="Panel de información"
              aria-label="Alternar panel de información"
            >
              <Bars3BottomRightIcon className="w-5 h-5" aria-hidden="true" />
            </button>
          )}

          {showOverflowBtn && (
            <>
              {visible.length > 0 && (
                <div className="w-px h-5 bg-border-secondary dark:bg-dark-border-primary" />
              )}
              <Dropdown
                variant="icon-only"
                items={dropdownItems}
                ariaLabel="Más acciones"
                className="!bg-transparent !border-0 hover:!bg-background-secondary dark:hover:!bg-dark-bg-secondary !text-content-secondary dark:!text-dark-content-secondary"
              >
                <EllipsisHorizontalIcon className="w-5 h-5" aria-hidden="true" />
              </Dropdown>
            </>
          )}
        </div>
      </div>
    </>
  );
}
